-- Bible Trivia: complete database setup.
-- Generated by scripts/build-setup-sql.mjs. Do not edit; edit supabase/migrations/ instead.
-- Paste this whole file into Supabase → SQL Editor → Run. Running it again is safe.
-- Afterwards, load the ~17,000 Recall questions with: npm run db:import


-- ======================================================================
-- 20261110000000_init.sql
-- ======================================================================
-- Bible Trivia — database schema (Supabase / Postgres)
--
-- The app works fully offline from the JSON packs in content/packs.
-- This database is the long-term home for the question bank (so it can grow
-- past what ships in the app) and for online features: accounts, synced
-- progress, the daily leaderboard and question reports.
--
-- Apply with the Supabase CLI (`supabase db push`) or paste into the SQL
-- editor. Then load content: `npm run db:seed-sql` and run supabase/seed.sql.

-- ---------- Reference data ----------

create table if not exists books (
  code        text primary key,           -- USFM code: GEN, JHN, REV
  position    smallint not null unique,   -- 1..66 canonical order
  testament   text not null check (testament in ('OT', 'NT')),
  name_en     text not null,
  name_ta     text not null
);

-- ---------- Questions ----------

create table if not exists questions (
  id          text primary key,           -- e.g. 'gen-001'
  type        text not null check (type in ('mcq', 'tf', 'who', 'book', 'blank')),
  book_code   text not null references books(code),
  chapter     smallint not null check (chapter > 0),
  verse       smallint,
  verse_end   smallint,
  difficulty  smallint not null check (difficulty between 1 and 3),
  -- index into options (mcq/who/book/blank) or true/false (tf)
  answer      jsonb not null,
  -- { "q": "...", "options": [...], "explain": "..." }
  en          jsonb not null,
  ta          jsonb not null,
  art         text,                       -- cartoon illustration key
  tags        text[] not null default '{}',
  status      text not null default 'draft' check (status in ('draft', 'review', 'published', 'retired')),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

create index if not exists questions_book_idx on questions (book_code);
create index if not exists questions_type_idx on questions (type) where status = 'published';
-- The app syncs "everything changed since my last sync".
create index if not exists questions_updated_idx on questions (updated_at);

create or replace function set_updated_at() returns trigger
language plpgsql set search_path = public as $$
begin
  new.updated_at := now();
  return new;
end $$;

drop trigger if exists questions_updated_at on questions;
create trigger questions_updated_at before update on questions
  for each row execute function set_updated_at();

-- ---------- Players (v2: online features) ----------

create table if not exists profiles (
  id            uuid primary key references auth.users(id) on delete cascade,
  display_name  text not null check (char_length(display_name) between 1 and 32),
  ui_lang       text not null default 'en' check (ui_lang in ('en', 'ta')),
  xp            integer not null default 0,
  streak        integer not null default 0,
  last_day      date,
  created_at    timestamptz not null default now()
);

create table if not exists answers (
  id           bigint generated always as identity primary key,
  user_id      uuid not null references profiles(id) on delete cascade,
  question_id  text not null references questions(id),
  correct      boolean not null,
  mode         text not null,
  answered_at  timestamptz not null default now()
);
create index if not exists answers_user_idx on answers (user_id, answered_at desc);

create table if not exists daily_results (
  user_id   uuid not null references profiles(id) on delete cascade,
  day       date not null,
  score     integer not null check (score between 0 and 2000),
  correct   smallint not null,
  total     smallint not null,
  created_at timestamptz not null default now(),
  primary key (user_id, day)               -- one daily attempt per person
);
create index if not exists daily_results_board_idx on daily_results (day, score desc);

-- Anyone (signed in or not) can flag a confusing or wrong question.
create table if not exists question_reports (
  id           bigint generated always as identity primary key,
  question_id  text not null references questions(id),
  lang         text not null check (lang in ('en', 'ta')),
  reason       text not null check (char_length(reason) between 1 and 500),
  user_id      uuid references profiles(id) on delete set null,
  created_at   timestamptz not null default now()
);

-- ---------- Row level security ----------

alter table books            enable row level security;
alter table questions        enable row level security;
alter table profiles         enable row level security;
alter table answers          enable row level security;
alter table daily_results    enable row level security;
alter table question_reports enable row level security;

drop policy if exists "books are public" on books;
create policy "books are public" on books for select using (true);
drop policy if exists "published questions are public" on questions;
create policy "published questions are public" on questions for select using (status = 'published');

drop policy if exists "read own profile" on profiles;
create policy "read own profile" on profiles for select using (auth.uid() = id);
drop policy if exists "create own profile" on profiles;
create policy "create own profile" on profiles for insert with check (auth.uid() = id);
drop policy if exists "update own profile" on profiles;
create policy "update own profile" on profiles for update using (auth.uid() = id);

drop policy if exists "read own answers" on answers;
create policy "read own answers" on answers for select using (auth.uid() = user_id);
drop policy if exists "add own answers" on answers;
create policy "add own answers" on answers for insert with check (auth.uid() = user_id);

drop policy if exists "daily board is public" on daily_results;
create policy "daily board is public" on daily_results for select using (true);
drop policy if exists "add own daily result" on daily_results;
create policy "add own daily result" on daily_results for insert with check (auth.uid() = user_id);

drop policy if exists "anyone can report" on question_reports;
create policy "anyone can report" on question_reports for insert
  with check (user_id is null or auth.uid() = user_id);

-- Public daily leaderboard: only names and scores leave the database.
-- security definer lets it read display names without making profiles public.
-- An early version of this file made daily_leaderboard a view; replace it.
drop view if exists daily_leaderboard;
create or replace function daily_leaderboard(p_day date default current_date, p_limit int default 50)
returns table (rank bigint, display_name text, score integer, correct smallint, total smallint)
language sql stable security definer set search_path = public as $$
  select rank() over (order by d.score desc, d.created_at),
         p.display_name, d.score, d.correct, d.total
  from daily_results d
  join profiles p on p.id = d.user_id
  where d.day = p_day
  order by d.score desc, d.created_at
  limit least(greatest(p_limit, 1), 100);
$$;

revoke all on function daily_leaderboard(date, int) from public;
grant execute on function daily_leaderboard(date, int) to anon, authenticated;

-- ---------- Table privileges (RLS above decides which rows) ----------
-- Supabase grants these by default; stated here so the intent is explicit.
grant usage on schema public to anon, authenticated;
grant select on books, questions to anon, authenticated;
grant insert on question_reports to anon, authenticated;
grant select, insert, update on profiles to authenticated;
grant select, insert on answers, daily_results to authenticated;
grant usage on all sequences in schema public to anon, authenticated;

-- ======================================================================
-- 20261110000100_verses_gospel.sql
-- ======================================================================
-- Verses, the gospel presentation, and FAQ for seekers.
-- Content is bilingual jsonb: { "en": "...", "ta": "..." }.

create table if not exists verses (
  id         text primary key,                  -- 'JHN.3.16'
  book_code  text not null references books(code),
  chapter    smallint not null,
  verse      smallint not null,
  en         text not null,                     -- KJV
  ta         text not null,                     -- BSI Tamil O.V.
  daily      boolean not null default true,     -- eligible for Verse of the Day
  updated_at timestamptz not null default now()
);

create table if not exists reading_sources (
  id     text primary key,
  author jsonb not null,
  title  text not null
);

create table if not exists gospel_steps (
  id         text primary key,
  position   smallint not null unique,
  icon       text not null,
  horse      text not null check (horse in ('white', 'red', 'black', 'pale')),
  title      jsonb not null,
  body       jsonb not null,
  prayer     jsonb,
  next       jsonb,
  verse_ids  text[] not null default '{}',
  updated_at timestamptz not null default now()
);

create table if not exists faqs (
  id          text primary key,
  position    smallint not null unique,
  q           jsonb not null,
  a           jsonb not null,
  verse_ids   text[] not null default '{}',
  reading_ids text[] not null default '{}',
  status      text not null default 'published' check (status in ('draft', 'review', 'published')),
  updated_at  timestamptz not null default now()
);

drop trigger if exists verses_updated_at on verses;
create trigger verses_updated_at before update on verses for each row execute function set_updated_at();
drop trigger if exists gospel_steps_updated_at on gospel_steps;
create trigger gospel_steps_updated_at before update on gospel_steps for each row execute function set_updated_at();
drop trigger if exists faqs_updated_at on faqs;
create trigger faqs_updated_at before update on faqs for each row execute function set_updated_at();

alter table verses          enable row level security;
alter table reading_sources enable row level security;
alter table gospel_steps    enable row level security;
alter table faqs            enable row level security;

drop policy if exists "verses are public" on verses;
create policy "verses are public" on verses for select using (true);
drop policy if exists "sources are public" on reading_sources;
create policy "sources are public" on reading_sources for select using (true);
drop policy if exists "gospel is public" on gospel_steps;
create policy "gospel is public" on gospel_steps for select using (true);
drop policy if exists "published faqs are public" on faqs;
create policy "published faqs are public" on faqs for select using (status = 'published');

grant select on verses, reading_sources, gospel_steps, faqs to anon, authenticated;

-- ======================================================================
-- 20261110000200_content_workflow.sql
-- ======================================================================
-- Content workflow for a large question bank (10,000+).
-- The database is the source of truth: generated or hand-written questions are
-- imported as 'review', reviewers fix and approve them in the Supabase table
-- editor, and only 'published' questions reach players.

alter table questions add column if not exists source text not null default 'manual'
  check (source in ('manual', 'generated', 'imported'));
alter table questions add column if not exists review_note text;          -- reviewer's comment
alter table questions add column if not exists reviewed_by text;          -- reviewer name or email
alter table questions add column if not exists reviewed_at timestamptz;
-- Where an imported question came from, so credit and licence terms travel with it.
alter table questions add column if not exists attribution text;        -- e.g. 'Example Ministry, examplequiz.org'
alter table questions add column if not exists license text;            -- e.g. 'CC BY 4.0', 'used with permission'

create index if not exists questions_book_chapter_idx on questions (book_code, chapter);
create index if not exists questions_status_idx on questions (status);

-- Stamp the review time when a question is published.
create or replace function stamp_reviewed() returns trigger
language plpgsql set search_path = public as $$
begin
  if new.status = 'published' and old.status is distinct from 'published' then
    new.reviewed_at := coalesce(new.reviewed_at, now());
  end if;
  return new;
end $$;

drop trigger if exists questions_stamp_reviewed on questions;
create trigger questions_stamp_reviewed before update on questions
  for each row execute function stamp_reviewed();

-- Targets: how many questions we want per book (a guide, not a hard rule).
create table if not exists book_targets (
  book_code  text primary key references books(code),
  target     integer not null check (target >= 0),
  priority   smallint not null default 100,         -- lower = write sooner
  focus_chapters smallint[] not null default '{}'   -- important chapters get more
);
alter table book_targets enable row level security;
-- No public policy: targets are only for the team (dashboard / service role).

-- Progress per book, for the team dashboard (Supabase → SQL editor or table view).
create or replace view book_progress as
select
  b.position,
  b.code,
  b.name_en,
  b.name_ta,
  coalesce(t.target, 0)                                   as target,
  count(q.id) filter (where q.status = 'published')       as published,
  count(q.id) filter (where q.status = 'review')          as in_review,
  count(q.id) filter (where q.status = 'draft')           as draft,
  count(q.id)                                             as total,
  round(100.0 * count(q.id) filter (where q.status = 'published')
        / nullif(t.target, 0), 1)                         as pct_published
from books b
left join book_targets t on t.book_code = b.code
left join questions q on q.book_code = b.code and q.status <> 'retired'
group by b.position, b.code, b.name_en, b.name_ta, t.target
order by b.position;

revoke all on book_progress from anon, authenticated;

-- Players should stop seeing a question once it is retired. The app syncs
-- published rows only, so it also needs the list of ids that were withdrawn.
create or replace function withdrawn_question_ids(p_since timestamptz)
returns table (id text)
language sql stable security definer set search_path = public as $$
  select q.id from questions q
  where q.status <> 'published' and q.updated_at > p_since;
$$;
revoke all on function withdrawn_question_ids(timestamptz) from public;
grant execute on function withdrawn_question_ids(timestamptz) to anon, authenticated;

-- ======================================================================
-- 20261110000300_reports.sql
-- ======================================================================
-- Player reports on questions, recall cards, verses and FAQ answers.
-- Each new report is emailed to the admin by the `report-email` Edge Function
-- (wired with a Database Webhook; see supabase/functions/report-email/README.md).

-- Reports can point at any content (recall cards live outside the questions
-- table), so drop the foreign key and keep a snapshot of what the player saw.
alter table question_reports drop constraint if exists question_reports_question_id_fkey;

alter table question_reports add column if not exists kind text not null default 'question'
  check (kind in ('question', 'recall', 'verse', 'faq', 'gospel'));
alter table question_reports add column if not exists category text not null default 'other'
  check (category in ('wrong_answer', 'typo', 'tamil', 'confusing', 'other'));
alter table question_reports add column if not exists snapshot jsonb;          -- question text, options, answer as shown
alter table question_reports add column if not exists contact text check (contact is null or char_length(contact) <= 200);
alter table question_reports add column if not exists app_version text;
alter table question_reports add column if not exists status text not null default 'new'
  check (status in ('new', 'fixed', 'dismissed'));
alter table question_reports add column if not exists handled_at timestamptz;
alter table question_reports add column if not exists emailed_at timestamptz;

-- The free-text reason becomes optional (the category says what is wrong).
alter table question_reports alter column reason drop not null;
alter table question_reports drop constraint if exists question_reports_reason_check;
alter table question_reports add constraint question_reports_reason_check
  check (reason is null or char_length(reason) <= 1000);
alter table question_reports drop constraint if exists question_reports_snapshot_size;
alter table question_reports add constraint question_reports_snapshot_size
  check (snapshot is null or pg_column_size(snapshot) < 8000);

create index if not exists question_reports_status_idx on question_reports (status, created_at desc);
create index if not exists question_reports_question_idx on question_reports (question_id);

-- Light abuse guard: at most 30 reports per question per day.
-- security definer: players may add reports but not read them, so the count
-- has to run with the owner's rights.
create or replace function limit_reports() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if (select count(*) from question_reports
      where question_id = new.question_id and created_at > now() - interval '1 day') >= 30 then
    raise exception 'too many reports for this question today';
  end if;
  return new;
end $$;

drop trigger if exists question_reports_limit on question_reports;
create trigger question_reports_limit before insert on question_reports
  for each row execute function limit_reports();

-- Team view: open reports with the question's current text alongside.
create or replace view open_reports as
select r.id, r.created_at, r.kind, r.category, r.lang, r.question_id, r.reason, r.contact,
       r.snapshot, q.status as question_status
from question_reports r
left join questions q on q.id = r.question_id
where r.status = 'new'
order by r.created_at desc;
revoke all on open_reports from anon, authenticated;

-- ======================================================================
-- 20261110000400_recall_questions.sql
-- ======================================================================
-- Recall questions (human-written question + answer, e.g. unfoldingWord
-- Translation Questions, ~17,000 rows) live in the same questions table.
--   type = 'recall'
--   en   = { "q": "...", "a": "..." }      (answer text, no options)
--   ta   = null until a Tamil version is written and reviewed
--   answer = null (the answer is the text in en.a / ta.a)

alter table questions drop constraint if exists questions_type_check;
alter table questions add constraint questions_type_check
  check (type in ('mcq', 'tf', 'who', 'book', 'blank', 'recall'));

alter table questions alter column ta drop not null;
alter table questions alter column answer drop not null;

-- Every type except recall still needs both languages and an answer.
alter table questions drop constraint if exists questions_complete_check;
alter table questions add constraint questions_complete_check
  check (type = 'recall' or (ta is not null and answer is not null));
alter table questions drop constraint if exists questions_recall_shape_check;
alter table questions add constraint questions_recall_shape_check
  check (type <> 'recall' or (en ? 'q' and en ? 'a'));

-- The app loads Recall cards one book at a time.
create index if not exists questions_recall_book_idx on questions (book_code, chapter) where type = 'recall';

-- ======================================================================
-- 20261111000500_tamil_translations.sql
-- ======================================================================
-- Tamil for questions that were written in English (Recall), and a way to
-- tell machine translations from ones a person has checked.

alter table questions add column if not exists ta_status text
  check (ta_status in ('machine', 'reviewed'));
comment on column questions.ta_status is
  'machine = Google translation with Tamil Bible names, not yet checked; reviewed = checked by a person';

-- Fills in Tamil only where a question has none yet, so a reviewer's
-- correction is never overwritten by a later machine translation.
-- Input: [{"id": "...", "ta": {"q": "...", "a": "..."}}, ...]
create or replace function apply_machine_tamil(p jsonb)
returns integer
language sql security definer set search_path = public as $$
  with updated as (
    update questions q
    set ta = x.ta, ta_status = 'machine', updated_at = now()
    from jsonb_to_recordset(p) as x(id text, ta jsonb)
    where q.id = x.id and q.ta is null
    returning 1
  )
  select count(*)::integer from updated;
$$;
-- Only the import script (secret key) may call it.
revoke all on function apply_machine_tamil(jsonb) from public, anon, authenticated;

-- When a reviewer edits the Tamil in the dashboard, mark it reviewed.
create or replace function mark_tamil_reviewed() returns trigger
language plpgsql set search_path = public as $$
begin
  if new.ta is distinct from old.ta and old.ta is not null and new.ta_status is not distinct from old.ta_status then
    new.ta_status := 'reviewed';
  end if;
  return new;
end $$;

drop trigger if exists questions_tamil_reviewed on questions;
create trigger questions_tamil_reviewed before update on questions
  for each row execute function mark_tamil_reviewed();

-- ======================================================================
-- 20261111000600_social.sql
-- ======================================================================
-- Accounts, friends and challenges.
--   - A profile is created automatically when someone signs up (Supabase Auth).
--   - Everyone gets a 6-character friend code to share with family.
--   - Friends can challenge each other: same questions, play any time, compare scores.
-- All writes go through the functions below (security definer), which check
-- who is calling; tables are read-only for players and limited to their own rows.

-- ---------- Profiles ----------
alter table profiles add column if not exists friend_code text;
alter table profiles add column if not exists avatar text not null default 'pale'
  check (avatar in ('white', 'red', 'black', 'pale'));
alter table profiles add column if not exists updated_at timestamptz not null default now();
create unique index if not exists profiles_friend_code_idx on profiles (friend_code);

create or replace function new_friend_code() returns text
language plpgsql volatile set search_path = public as $$
declare c text;
begin
  loop
    -- 6 characters from 0-9 and A-F: about 16 million codes, no look-alike O/I/L.
    c := upper(substr(md5(random()::text || clock_timestamp()::text), 1, 6));
    exit when not exists (select 1 from profiles where friend_code = c);
  end loop;
  return c;
end $$;

update profiles set friend_code = new_friend_code() where friend_code is null;

-- New sign-up → profile, using the name given in the sign-up form.
create or replace function handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into profiles (id, display_name, ui_lang, friend_code)
  values (
    new.id,
    left(coalesce(nullif(trim(new.raw_user_meta_data->>'display_name'), ''), nullif(split_part(coalesce(new.email, ''), '@', 1), ''), 'Player'), 32),
    case when new.raw_user_meta_data->>'ui_lang' = 'ta' then 'ta' else 'en' end,
    new_friend_code()
  )
  on conflict (id) do nothing;
  return new;
end $$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users
  for each row execute function handle_new_user();

-- Profiles for people who signed up before this migration.
insert into profiles (id, display_name, friend_code)
select u.id, left(coalesce(nullif(split_part(coalesce(u.email, ''), '@', 1), ''), 'Player'), 32), new_friend_code()
from auth.users u
where not exists (select 1 from profiles p where p.id = u.id);

-- ---------- Friends ----------
create table if not exists friendships (
  requester    uuid not null references profiles(id) on delete cascade,
  addressee    uuid not null references profiles(id) on delete cascade,
  status       text not null default 'pending' check (status in ('pending', 'accepted')),
  created_at   timestamptz not null default now(),
  responded_at timestamptz,
  primary key (requester, addressee),
  check (requester <> addressee)
);
-- One friendship per pair, whichever direction it was asked in.
create unique index if not exists friendships_pair_idx
  on friendships (least(requester, addressee), greatest(requester, addressee));
create index if not exists friendships_addressee_idx on friendships (addressee);

alter table friendships enable row level security;
drop policy if exists "see own friendships" on friendships;
create policy "see own friendships" on friendships for select
  using (auth.uid() in (requester, addressee));
grant select on friendships to authenticated;

create or replace function is_friend(other uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from friendships
    where status = 'accepted'
      and ((requester = auth.uid() and addressee = other) or (addressee = auth.uid() and requester = other))
  );
$$;

-- Send a request by friend code. If they already asked you, you become friends.
create or replace function send_friend_request(p_code text) returns text
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); them uuid; existing friendships;
begin
  if me is null then return 'signed_out'; end if;
  select id into them from profiles where friend_code = upper(trim(p_code));
  if them is null then return 'not_found'; end if;
  if them = me then return 'self'; end if;
  select * into existing from friendships
   where (requester = me and addressee = them) or (requester = them and addressee = me);
  if found then
    if existing.status = 'accepted' then return 'already_friends'; end if;
    if existing.requester = them then
      update friendships set status = 'accepted', responded_at = now()
       where requester = them and addressee = me;
      return 'accepted';
    end if;
    return 'already_sent';
  end if;
  insert into friendships (requester, addressee) values (me, them);
  return 'sent';
end $$;

create or replace function respond_friend_request(p_from uuid, p_accept boolean) returns void
language plpgsql security definer set search_path = public as $$
begin
  if p_accept then
    update friendships set status = 'accepted', responded_at = now()
     where requester = p_from and addressee = auth.uid() and status = 'pending';
  else
    delete from friendships where requester = p_from and addressee = auth.uid() and status = 'pending';
  end if;
end $$;

-- Unfriend, cancel a sent request, or decline.
create or replace function remove_friend(p_other uuid) returns void
language sql security definer set search_path = public as $$
  delete from friendships
   where (requester = auth.uid() and addressee = p_other) or (requester = p_other and addressee = auth.uid());
$$;

-- Everyone you are connected to, with what the app shows about them.
create or replace function my_friends()
returns table (user_id uuid, display_name text, avatar text, friend_code text, xp integer, streak integer,
               status text, incoming boolean, since timestamptz)
language sql stable security definer set search_path = public as $$
  select p.id, p.display_name, p.avatar,
         case when f.status = 'accepted' then p.friend_code end,
         case when f.status = 'accepted' then p.xp end,
         case when f.status = 'accepted' then p.streak end,
         f.status, f.addressee = auth.uid(), coalesce(f.responded_at, f.created_at)
  from friendships f
  join profiles p on p.id = case when f.requester = auth.uid() then f.addressee else f.requester end
  where auth.uid() in (f.requester, f.addressee)
  order by f.status desc, p.display_name;
$$;

-- Today's Daily Challenge: you and your friends.
create or replace function friends_daily_board(p_day date default current_date)
returns table (rank bigint, user_id uuid, display_name text, avatar text, score integer, correct smallint, total smallint, is_me boolean)
language sql stable security definer set search_path = public as $$
  with circle as (
    select auth.uid() as id
    union
    select case when requester = auth.uid() then addressee else requester end
    from friendships where status = 'accepted' and auth.uid() in (requester, addressee)
  )
  select rank() over (order by d.score desc, d.created_at), p.id, p.display_name, p.avatar,
         d.score, d.correct, d.total, p.id = auth.uid()
  from circle c
  join daily_results d on d.user_id = c.id and d.day = p_day
  join profiles p on p.id = c.id
  order by d.score desc, d.created_at;
$$;

-- ---------- Challenges ----------
create table if not exists challenges (
  id           uuid primary key default gen_random_uuid(),
  created_by   uuid not null references profiles(id) on delete cascade,
  mode         text not null check (char_length(mode) <= 20),
  question_ids text[] not null check (array_length(question_ids, 1) between 1 and 30),
  created_at   timestamptz not null default now(),
  expires_at   timestamptz not null default now() + interval '14 days'
);
create table if not exists challenge_players (
  challenge_id uuid not null references challenges(id) on delete cascade,
  user_id      uuid not null references profiles(id) on delete cascade,
  score        integer check (score between 0 and 3000),
  correct      smallint,
  total        smallint,
  finished_at  timestamptz,
  primary key (challenge_id, user_id)
);
create index if not exists challenge_players_user_idx on challenge_players (user_id, finished_at);

alter table challenges enable row level security;
alter table challenge_players enable row level security;

create or replace function in_challenge(p_challenge uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from challenge_players where challenge_id = p_challenge and user_id = auth.uid());
$$;

drop policy if exists "players see their challenges" on challenges;
create policy "players see their challenges" on challenges for select using (in_challenge(id));
drop policy if exists "players see fellow players" on challenge_players;
create policy "players see fellow players" on challenge_players for select using (in_challenge(challenge_id));
grant select on challenges, challenge_players to authenticated;

-- Start a challenge with up to 10 friends. Returns its id.
create or replace function create_challenge(p_mode text, p_question_ids text[], p_friends uuid[]) returns uuid
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); cid uuid; f uuid;
begin
  if me is null then raise exception 'sign in first'; end if;
  if coalesce(array_length(p_friends, 1), 0) not between 1 and 10 then raise exception 'choose 1 to 10 friends'; end if;
  foreach f in array p_friends loop
    if not is_friend(f) then raise exception 'you can only challenge friends'; end if;
  end loop;
  insert into challenges (created_by, mode, question_ids) values (me, p_mode, p_question_ids) returning id into cid;
  insert into challenge_players (challenge_id, user_id)
  select cid, u from unnest(array_append(p_friends, me)) as u
  on conflict do nothing;
  return cid;
end $$;

-- Record your score once.
create or replace function submit_challenge_result(p_challenge uuid, p_score integer, p_correct integer, p_total integer) returns void
language plpgsql security definer set search_path = public as $$
begin
  update challenge_players
     set score = least(greatest(p_score, 0), 3000), correct = p_correct, total = p_total, finished_at = now()
   where challenge_id = p_challenge and user_id = auth.uid() and finished_at is null;
  if not found then raise exception 'not your challenge, or already played'; end if;
end $$;

-- Your challenges with every player's name and result.
create or replace function my_challenges()
returns table (id uuid, mode text, question_ids text[], created_at timestamptz, expires_at timestamptz,
               created_by uuid, players jsonb)
language sql stable security definer set search_path = public as $$
  select c.id, c.mode, c.question_ids, c.created_at, c.expires_at, c.created_by,
         jsonb_agg(jsonb_build_object(
           'user_id', p.id, 'name', p.display_name, 'avatar', p.avatar, 'me', p.id = auth.uid(),
           'score', cp.score, 'correct', cp.correct, 'total', cp.total, 'finished_at', cp.finished_at
         ) order by cp.score desc nulls last, p.display_name)
  from challenges c
  join challenge_players cp on cp.challenge_id = c.id
  join profiles p on p.id = cp.user_id
  where in_challenge(c.id) and c.created_at > now() - interval '30 days'
  group by c.id
  order by c.created_at desc
  limit 50;
$$;

-- ---------- Access ----------
revoke all on function send_friend_request(text), respond_friend_request(uuid, boolean), remove_friend(uuid),
  my_friends(), friends_daily_board(date), create_challenge(text, text[], uuid[]),
  submit_challenge_result(uuid, integer, integer, integer), my_challenges(), is_friend(uuid), in_challenge(uuid)
  from public, anon;
grant execute on function send_friend_request(text), respond_friend_request(uuid, boolean), remove_friend(uuid),
  my_friends(), friends_daily_board(date), create_challenge(text, text[], uuid[]),
  submit_challenge_result(uuid, integer, integer, integer), my_challenges(), is_friend(uuid), in_challenge(uuid)
  to authenticated;
revoke all on function new_friend_code(), handle_new_user() from public, anon, authenticated;

-- Players may edit only their name and avatar (xp and streak are synced by the app too).
drop policy if exists "update own profile" on profiles;
create policy "update own profile" on profiles for update using (auth.uid() = id) with check (auth.uid() = id);

-- ======================================================================
-- 20261111000700_google_names.sql
-- ======================================================================
-- Sign-ups through Google (or other providers) send the person's name as
-- full_name / name; use it for the profile, falling back to the email name.
create or replace function handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into profiles (id, display_name, ui_lang, friend_code)
  values (
    new.id,
    left(coalesce(
      nullif(trim(new.raw_user_meta_data->>'display_name'), ''),
      nullif(trim(new.raw_user_meta_data->>'full_name'), ''),
      nullif(trim(new.raw_user_meta_data->>'name'), ''),
      nullif(split_part(coalesce(new.email, ''), '@', 1), ''),
      'Player'
    ), 32),
    case when new.raw_user_meta_data->>'ui_lang' = 'ta' then 'ta' else 'en' end,
    new_friend_code()
  )
  on conflict (id) do nothing;
  return new;
end $$;
revoke all on function handle_new_user() from public, anon, authenticated;

-- ======================================================================
-- 20261111000800_notifications.sql
-- ======================================================================
-- Push notifications (web push to installed PWAs and browsers).
--   push_subscriptions  one row per device that allowed notifications
--   notification_prefs  what each person wants, when, in which language and time zone
--   notification_queue  messages waiting to be sent by the `push` Edge Function
--   notification_log    one scheduled message of each kind per person per day
-- Friend events are queued by triggers; daily ones by queue_scheduled_notifications(),
-- which Supabase Cron runs every 30 minutes through the `push` function.

create table if not exists push_subscriptions (
  id          bigint generated always as identity primary key,
  user_id     uuid not null references profiles(id) on delete cascade,
  endpoint    text not null unique,
  p256dh      text not null,
  auth        text not null,
  created_at  timestamptz not null default now(),
  last_ok_at  timestamptz
);
create index if not exists push_subscriptions_user_idx on push_subscriptions (user_id);

create table if not exists notification_prefs (
  user_id        uuid primary key references profiles(id) on delete cascade,
  daily_verse    boolean not null default true,
  verse_hour     smallint not null default 7 check (verse_hour between 0 and 23),
  daily_reminder boolean not null default true,
  reminder_hour  smallint not null default 19 check (reminder_hour between 0 and 23),
  streak         boolean not null default true,
  friends        boolean not null default true,
  lang           text not null default 'en' check (lang in ('en', 'ta')),
  time_zone      text not null default 'Asia/Kolkata',
  updated_at     timestamptz not null default now()
);

create table if not exists notification_queue (
  id         bigint generated always as identity primary key,
  user_id    uuid not null references profiles(id) on delete cascade,
  kind       text not null check (kind in ('daily_verse', 'daily_reminder', 'streak_rescue',
                                           'friend_request', 'friend_accepted', 'challenge_received', 'challenge_finished')),
  payload    jsonb not null default '{}',
  created_at timestamptz not null default now(),
  sent_at    timestamptz,
  attempts   smallint not null default 0
);
create index if not exists notification_queue_unsent_idx on notification_queue (created_at) where sent_at is null;

create table if not exists notification_log (
  user_id uuid not null references profiles(id) on delete cascade,
  kind    text not null,
  day     date not null,
  primary key (user_id, kind, day)
);

-- ---------- Access: people manage only their own devices and settings ----------
alter table push_subscriptions enable row level security;
alter table notification_prefs enable row level security;
alter table notification_queue enable row level security;  -- no player policies: server only
alter table notification_log enable row level security;    -- no player policies: server only

drop policy if exists "own subscriptions" on push_subscriptions;
create policy "own subscriptions" on push_subscriptions for all
  using (auth.uid() = user_id) with check (auth.uid() = user_id);
drop policy if exists "own notification prefs" on notification_prefs;
create policy "own notification prefs" on notification_prefs for all
  using (auth.uid() = user_id) with check (auth.uid() = user_id);
grant select, insert, update, delete on push_subscriptions, notification_prefs to authenticated;

-- ---------- Friend events → queue (only for people who want them and have a device) ----------
create or replace function wants_friend_pushes(p_user uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from notification_prefs where user_id = p_user and friends)
     and exists (select 1 from push_subscriptions where user_id = p_user);
$$;

create or replace function queue_friendship_push() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' and new.status = 'pending' and wants_friend_pushes(new.addressee) then
    insert into notification_queue (user_id, kind, payload)
    select new.addressee, 'friend_request', jsonb_build_object('name', display_name)
    from profiles where id = new.requester;
  elsif tg_op = 'UPDATE' and old.status = 'pending' and new.status = 'accepted' and wants_friend_pushes(new.requester) then
    insert into notification_queue (user_id, kind, payload)
    select new.requester, 'friend_accepted', jsonb_build_object('name', display_name)
    from profiles where id = new.addressee;
  end if;
  return new;
end $$;

drop trigger if exists friendships_push on friendships;
create trigger friendships_push after insert or update on friendships
  for each row execute function queue_friendship_push();

create or replace function queue_challenge_push() returns trigger
language plpgsql security definer set search_path = public as $$
declare c challenges;
begin
  select * into c from challenges where id = new.challenge_id;
  if tg_op = 'INSERT' then
    if new.user_id <> c.created_by and wants_friend_pushes(new.user_id) then
      insert into notification_queue (user_id, kind, payload)
      select new.user_id, 'challenge_received', jsonb_build_object('name', display_name, 'mode', c.mode, 'challenge_id', c.id)
      from profiles where id = c.created_by;
    end if;
  elsif old.finished_at is null and new.finished_at is not null
        and not exists (select 1 from challenge_players where challenge_id = new.challenge_id and finished_at is null) then
    -- The last player just finished: tell everyone the result.
    insert into notification_queue (user_id, kind, payload)
    select cp.user_id, 'challenge_finished', jsonb_build_object(
      'mode', c.mode, 'challenge_id', c.id,
      'winner', (select p.display_name from challenge_players x join profiles p on p.id = x.user_id
                 where x.challenge_id = c.id order by x.score desc nulls last limit 1),
      'scores', (select string_agg(p.display_name || ' ' || x.score, ' · ' order by x.score desc)
                 from challenge_players x join profiles p on p.id = x.user_id where x.challenge_id = c.id))
    from challenge_players cp
    where cp.challenge_id = c.id and wants_friend_pushes(cp.user_id);
  end if;
  return new;
end $$;

drop trigger if exists challenge_players_push on challenge_players;
create trigger challenge_players_push after insert or update on challenge_players
  for each row execute function queue_challenge_push();

-- ---------- Daily messages (run every 30 minutes by cron via the push function) ----------
-- Each person's own clock: fires in the first half hour of the chosen hour, once a day.
create or replace function queue_scheduled_notifications(p_now timestamptz default now()) returns integer
language plpgsql security definer set search_path = public as $$
declare queued integer;
begin
  with people as (
    select np.*, pr.streak as streak_days, pr.last_day,
           (p_now at time zone np.time_zone) as local_now,
           (p_now at time zone np.time_zone)::date as local_day
    from notification_prefs np
    join profiles pr on pr.id = np.user_id
    where exists (select 1 from push_subscriptions s where s.user_id = np.user_id)
  ),
  due as (
    select user_id, 'daily_verse' as kind, local_day, jsonb_build_object('day', local_day) as payload
    from people
    where daily_verse and extract(hour from local_now) = verse_hour and extract(minute from local_now) < 30
    union all
    select user_id, 'daily_reminder', local_day, jsonb_build_object('day', local_day)
    from people p
    where daily_reminder and extract(hour from local_now) = reminder_hour and extract(minute from local_now) < 30
      and not exists (select 1 from daily_results d where d.user_id = p.user_id and d.day = p.local_day)
    union all
    -- 8 pm (9 pm if the reminder is already at 8): the streak ends at midnight.
    select user_id, 'streak_rescue', local_day, jsonb_build_object('day', local_day, 'streak', streak_days)
    from people
    where streak and streak_days >= 2
      and extract(hour from local_now) = case when reminder_hour = 20 then 21 else 20 end
      and extract(minute from local_now) < 30
      and last_day = local_day - 1
  ),
  logged as (
    insert into notification_log (user_id, kind, day)
    select user_id, kind, local_day from due
    on conflict do nothing
    returning user_id, kind, day
  )
  insert into notification_queue (user_id, kind, payload)
  select d.user_id, d.kind, d.payload
  from due d join logged l on l.user_id = d.user_id and l.kind = d.kind and l.day = d.local_day;
  get diagnostics queued = row_count;

  -- Housekeeping: drop sent messages after a week, and old log rows.
  delete from notification_queue where sent_at < p_now - interval '7 days';
  delete from notification_log where day < (p_now - interval '14 days')::date;
  return queued;
end $$;

revoke all on function queue_scheduled_notifications(timestamptz), wants_friend_pushes(uuid),
  queue_friendship_push(), queue_challenge_push() from public, anon, authenticated;

-- The push Edge Function uses the secret key (service_role).
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function queue_scheduled_notifications(timestamptz) to service_role;
    grant execute on function apply_machine_tamil(jsonb) to service_role;
    grant select, insert, update, delete on push_subscriptions, notification_prefs, notification_queue, notification_log to service_role;
  end if;
end $$;

-- ======================================================================
-- 20261111000900_head_to_head.sql
-- ======================================================================
-- Head-to-head records between friends, and an all-time wins board.
-- Read-only functions only: no table changes, no data changes.
-- A result counts once everyone in the challenge has played.

-- Your all-time record against each friend: compares your score with theirs in
-- every finished challenge you both played (group challenges included).
create or replace function friend_records()
returns table (user_id uuid, wins integer, losses integer, ties integer)
language sql stable security definer set search_path = public as $$
  select o.user_id,
         count(*) filter (where m.score > o.score)::integer,
         count(*) filter (where m.score < o.score)::integer,
         count(*) filter (where m.score = o.score)::integer
  from challenge_players m
  join challenge_players o on o.challenge_id = m.challenge_id and o.user_id <> m.user_id
  where m.user_id = auth.uid()
    and m.finished_at is not null and o.finished_at is not null
    and is_friend(o.user_id)
  group by o.user_id;
$$;

-- Every challenge you and one friend shared, newest first (not limited to 30 days).
create or replace function friend_history(p_friend uuid)
returns table (challenge_id uuid, mode text, created_at timestamptz, expires_at timestamptz,
               created_by uuid, question_ids text[],
               my_score integer, my_correct smallint, my_total smallint, my_finished_at timestamptz,
               their_score integer, their_correct smallint, their_total smallint, their_finished_at timestamptz,
               players integer)
language sql stable security definer set search_path = public as $$
  select c.id, c.mode, c.created_at, c.expires_at, c.created_by, c.question_ids,
         m.score, m.correct, m.total, m.finished_at,
         o.score, o.correct, o.total, o.finished_at,
         (select count(*)::integer from challenge_players x where x.challenge_id = c.id)
  from challenges c
  join challenge_players m on m.challenge_id = c.id and m.user_id = auth.uid()
  join challenge_players o on o.challenge_id = c.id and o.user_id = p_friend
  where is_friend(p_friend)
  order by c.created_at desc
  limit 500;
$$;

-- You and your friends ranked by challenges won (sole top score), then XP.
create or replace function all_time_board()
returns table (rank bigint, user_id uuid, display_name text, avatar text,
               wins integer, played integer, xp integer, is_me boolean)
language sql stable security definer set search_path = public as $$
  with circle as (
    select auth.uid() as id
    union
    select case when requester = auth.uid() then addressee else requester end
    from friendships where status = 'accepted' and auth.uid() in (requester, addressee)
  ),
  finished as (
    select challenge_id from challenge_players
    group by challenge_id
    having bool_and(finished_at is not null) and count(*) > 1
  ),
  ranked as (
    select cp.user_id,
           rank() over (partition by cp.challenge_id order by cp.score desc) as r,
           count(*) over (partition by cp.challenge_id, cp.score) as same_score
    from challenge_players cp
    join finished f on f.challenge_id = cp.challenge_id
  ),
  -- Ranked among everyone in each challenge, then kept for you and your friends.
  totals as (
    select user_id,
           count(*) filter (where r = 1 and same_score = 1)::integer as wins,
           count(*)::integer as played
    from ranked
    where user_id in (select id from circle)
    group by user_id
  )
  select rank() over (order by coalesce(t.wins, 0) desc, p.xp desc),
         p.id, p.display_name, p.avatar,
         coalesce(t.wins, 0), coalesce(t.played, 0), p.xp, p.id = auth.uid()
  from circle c
  join profiles p on p.id = c.id
  left join totals t on t.user_id = p.id
  order by 1, p.display_name;
$$;

revoke all on function friend_records(), friend_history(uuid), all_time_board() from public, anon;
grant execute on function friend_records(), friend_history(uuid), all_time_board() to authenticated;

-- ======================================================================
-- 20261111001000_hearts.sql
-- ======================================================================
-- Streak hearts: every 5 days in a row earns a heart (max 3); a heart saves the
-- streak on a missed day. Kept on the profile so they follow the player to another phone.
alter table profiles add column if not exists hearts smallint not null default 0;
alter table profiles drop constraint if exists profiles_hearts_range;
alter table profiles add constraint profiles_hearts_range check (hearts between 0 and 3);

-- ======================================================================
-- 20261111001100_friend_invites.sql
-- ======================================================================
-- Friends by QR code: one person shows a QR code, the other scans it, and they
-- are friends straight away (no request to accept). The code holds a one-time
-- invite that expires after 10 minutes, so a screenshot can't be reused later.

create table if not exists friend_invites (
  token      text primary key,
  user_id    uuid not null references profiles(id) on delete cascade,
  expires_at timestamptz not null
);
create index if not exists friend_invites_user_idx on friend_invites (user_id);
-- Only reachable through the functions below.
alter table friend_invites enable row level security;

-- A fresh invite for the QR code (older ones of yours are replaced).
create or replace function create_friend_invite() returns table (token text, expires_at timestamptz)
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); t text; e timestamptz := now() + interval '10 minutes';
begin
  if me is null then raise exception 'signed out'; end if;
  delete from friend_invites where friend_invites.user_id = me or friend_invites.expires_at < now();
  t := replace(gen_random_uuid()::text, '-', '');
  insert into friend_invites (token, user_id, expires_at) values (t, me, e);
  return query select t, e;
end $$;

-- Scanning someone's QR code: become friends now.
create or replace function accept_friend_invite(p_token text) returns text
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); them uuid; existing friendships;
begin
  if me is null then return 'signed_out'; end if;
  select user_id into them from friend_invites where token = p_token and expires_at > now();
  if them is null then return 'expired'; end if;
  if them = me then return 'self'; end if;
  select * into existing from friendships
   where (requester = me and addressee = them) or (requester = them and addressee = me);
  if found then
    if existing.status = 'accepted' then return 'already_friends'; end if;
    update friendships set status = 'accepted', responded_at = now()
     where requester = existing.requester and addressee = existing.addressee;
    return 'accepted';
  end if;
  insert into friendships (requester, addressee, status, responded_at) values (me, them, 'accepted', now());
  return 'accepted';
end $$;

revoke all on function create_friend_invite(), accept_friend_invite(text) from public, anon;
grant execute on function create_friend_invite(), accept_friend_invite(text) to authenticated;

-- Notify the person who showed the code: "X is now your friend".
create or replace function queue_friendship_push() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' and new.status = 'pending' and wants_friend_pushes(new.addressee) then
    insert into notification_queue (user_id, kind, payload)
    select new.addressee, 'friend_request', jsonb_build_object('name', display_name)
    from profiles where id = new.requester;
  elsif tg_op = 'INSERT' and new.status = 'accepted' and wants_friend_pushes(new.addressee) then
    insert into notification_queue (user_id, kind, payload)
    select new.addressee, 'friend_added', jsonb_build_object('name', display_name)
    from profiles where id = new.requester;
  elsif tg_op = 'UPDATE' and old.status = 'pending' and new.status = 'accepted' and wants_friend_pushes(new.requester) then
    insert into notification_queue (user_id, kind, payload)
    select new.requester, 'friend_accepted', jsonb_build_object('name', display_name)
    from profiles where id = new.addressee;
  end if;
  return new;
end $$;

-- ======================================================================
-- 20261111001200_notification_kinds.sql
-- ======================================================================
-- Allow the "X is now your friend" notification (friends by QR code).
alter table notification_queue drop constraint if exists notification_queue_kind_check;
alter table notification_queue add constraint notification_queue_kind_check
  check (kind in ('daily_verse', 'daily_reminder', 'streak_rescue',
                  'friend_request', 'friend_accepted', 'friend_added',
                  'challenge_received', 'challenge_finished'));

-- ======================================================================
-- 20261111001300_practice_sync.sql
-- ======================================================================
-- Practice follows the account: answers (for mistakes, reviews and weak spots),
-- saved questions, and memory-verse progress, synced between a person's devices.
-- Each person sees and writes only their own rows.

create table if not exists practice_answers (
  user_id     uuid not null references profiles(id) on delete cascade,
  -- Made on the device ("<device>-<n>"), so sending the same answer twice is harmless.
  client_key  text not null check (char_length(client_key) <= 80),
  question_id text not null check (char_length(question_id) <= 80),
  book        text not null check (char_length(book) <= 8),
  correct     boolean not null,
  mode        text not null check (char_length(mode) <= 20),
  answered_at timestamptz not null,
  created_at  timestamptz not null default now(),
  primary key (user_id, client_key)
);
-- Devices fetch what's new since they last looked.
create index if not exists practice_answers_pull_idx on practice_answers (user_id, created_at);

create table if not exists saved_questions (
  user_id     uuid not null references profiles(id) on delete cascade,
  question_id text not null check (char_length(question_id) <= 80),
  saved       boolean not null default true,   -- false: un-starred (kept so other devices hear about it)
  updated_at  timestamptz not null default now(),
  primary key (user_id, question_id)
);

create table if not exists practice_state (
  user_id    uuid primary key references profiles(id) on delete cascade,
  memory     jsonb not null default '{}'::jsonb,   -- memory verse id -> level
  my_verses  jsonb not null default '[]'::jsonb,   -- verses the person added
  updated_at timestamptz not null default now()
);
alter table practice_state drop constraint if exists practice_state_size;
alter table practice_state add constraint practice_state_size
  check (pg_column_size(memory) < 100000 and pg_column_size(my_verses) < 300000);

alter table practice_answers enable row level security;
alter table saved_questions enable row level security;
alter table practice_state enable row level security;

drop policy if exists "own practice answers" on practice_answers;
create policy "own practice answers" on practice_answers for all
  using (auth.uid() = user_id) with check (auth.uid() = user_id);
drop policy if exists "own saved questions" on saved_questions;
create policy "own saved questions" on saved_questions for all
  using (auth.uid() = user_id) with check (auth.uid() = user_id);
drop policy if exists "own practice state" on practice_state;
create policy "own practice state" on practice_state for all
  using (auth.uid() = user_id) with check (auth.uid() = user_id);

grant select, insert, update, delete on practice_answers, saved_questions, practice_state to authenticated;

