alter table profiles add constraint profiles_avatar_check check (avatar in (
  'white', 'red', 'black', 'pale',
  'lamb', 'lion', 'dove', 'fish', 'camel', 'donkey', 'ram', 'eagle', 'bear', 'ox',
  'raven', 'horse', 'frog', 'bee', 'sparrow', 'goat', 'deer', 'whale', 'owl', 'fox'
));

