-- verses
insert into verses (id, book_code, chapter, verse, en, ta) values ('GEN.1.1', 'GEN', 1, 1, 'In the beginning God created the heaven and the earth.', 'ஆதியிலே தேவன் வானத்தையும் பூமியையும் சிருஷ்டித்தார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('GEN.1.26', 'GEN', 1, 26, 'And God said, Let us make man in our image, after our likeness: and let them have dominion over the fish of the sea, and over the fowl of the air, and over the cattle, and over all the earth, and over every creeping thing that creepeth upon the earth.', 'பின்பு தேவன்: நமது சாயலாகவும் நமது ரூபத்தின்படியேயும் மனுஷனை உண்டாக்குவோமாக; அவர்கள் சமுத்திரத்தின் மச்சங்களையும், ஆகாயத்துப் பறவைகளையும், மிருகஜீவன்களையும், பூமியனைத்தையும், பூமியின்மேல் ஊரும் சகலப் பிராணிகளையும் ஆளக்கடவர்கள் என்றார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('GEN.1.27', 'GEN', 1, 27, 'So God created man in his own image, in the image of God created he him; male and female created he them.', 'தேவன் தம்முடைய சாயலாக மனுஷனைச் சிருஷ்டித்தார், அவனைத் தேவசாயலாகவே சிருஷ்டித்தார், ஆணும் பெண்ணுமாக அவர்களைச் சிருஷ்டித்தார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('GEN.1.31', 'GEN', 1, 31, 'And God saw every thing that he had made, and, behold, it was very good. And the evening and the morning were the sixth day.', 'அப்பொழுது தேவன் தாம் உண்டாக்கின எல்லாவற்றையும் பார்த்தார், அது மிகவும் நன்றாயிருந்தது; சாயங்காலமும் விடியற்காலமுமாகி ஆறாம் நாள் ஆயிற்று.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('GEN.2.7', 'GEN', 2, 7, 'And the LORD God formed man of the dust of the ground, and breathed into his nostrils the breath of life; and man became a living soul.', 'தேவனாகிய கர்த்தர் மனுஷனைப் பூமியின் மண்ணினாலே உருவாக்கி, ஜீவசுவாசத்தை அவன் நாசியிலே ஊதினார், மனுஷன் ஜீவாத்துமாவானான்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('GEN.2.18', 'GEN', 2, 18, 'And the LORD God said, It is not good that the man should be alone; I will make him an help meet for him.', 'பின்பு தேவனாகிய கர்த்தர்: மனுஷன் தனிமையாயிருப்பது நல்லதல்ல, ஏற்ற துணையை அவனுக்கு உண்டாக்குவேன் என்றார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('GEN.3.15', 'GEN', 3, 15, 'And I will put enmity between thee and the woman, and between thy seed and her seed; it shall bruise thy head, and thou shalt bruise his heel.', 'உனக்கும் ஸ்திரீக்கும், உன் வித்துக்கும் அவள் வித்துக்கும் பகை உண்டாக்குவேன்; அவர் உன் தலையை நசுக்குவார், நீ அவர் குதிங்காலை நசுக்குவாய் என்றார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('GEN.12.2', 'GEN', 12, 2, 'And I will make of thee a great nation, and I will bless thee, and make thy name great; and thou shalt be a blessing:', 'நான் உன்னைப் பெரிய ஜாதியாக்கி, உன்னை ஆசீர்வதித்து, உன் பேரைப் பெருமைப்படுத்துவேன்; நீ ஆசீர்வாதமாய் இருப்பாய்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('GEN.15.6', 'GEN', 15, 6, 'And he believed in the LORD; and he counted it to him for righteousness.', 'அவன் கர்த்தரை விசுவாசித்தான், அதை அவர் அவனுக்கு நீதியாக எண்ணினார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('GEN.18.14', 'GEN', 18, 14, 'Is any thing too hard for the LORD? At the time appointed I will return unto thee, according to the time of life, and Sarah shall have a son.', 'கர்த்தரால் ஆகாத காரியம் உண்டோ? உற்பவகாலத்திட்டத்தில் உன்னிடத்திற்குத் திரும்பவருவேன்; அப்பொழுது சாராளுக்கு ஒரு குமாரன் இருப்பான் என்றார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('GEN.50.20', 'GEN', 50, 20, 'But as for you, ye thought evil against me; but God meant it unto good, to bring to pass, as it is this day, to save much people alive.', 'நீங்கள் எனக்குத் தீமைசெய்ய நினைத்தீர்கள்; தேவனோ, இப்பொழுது நடந்துவருகிறபடியே, வெகு ஜனங்களை உயிரோடே காக்கும்படிக்கு, அதை நன்மையாக முடியப்பண்ணினார்')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('EXO.3.14', 'EXO', 3, 14, 'And God said unto Moses, I AM THAT I AM: and he said, Thus shalt thou say unto the children of Israel, I AM hath sent me unto you.', 'அதற்குத் தேவன்: இருக்கிறவராக இருக்கிறேன் என்று மோசேயுடனே சொல்லி, இருக்கிறேன் என்பவர் என்னை உங்களிடத்துக்கு அனுப்பினார் என்று இஸ்ரவேல் புத்திரரோடே சொல்வாயாக என்றார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('EXO.14.14', 'EXO', 14, 14, 'The LORD shall fight for you, and ye shall hold your peace.', 'கர்த்தர் உங்களுக்காக யுத்தம் பண்ணுவார்; நீங்கள் சும்மாயிருப்பீர்கள் என்றான்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('EXO.15.2', 'EXO', 15, 2, 'The LORD is my strength and song, and he is become my salvation: he is my God, and I will prepare him an habitation; my father’s God, and I will exalt him.', 'கர்த்தர் என் பெலனும் என் கீதமுமானவர்; அவர் எனக்கு இரட்சிப்புமானவர்; அவரே என் தேவன், அவருக்கு வாசஸ்தலத்தை ஆயத்தம்பண்ணுவேன்; அவரே என் தகப்பனுடைய தேவன், அவரை உயர்த்துவேன்;')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('EXO.20.3', 'EXO', 20, 3, 'Thou shalt have no other gods before me.', 'என்னையன்றி உனக்கு வேறே தேவர்கள் உண்டாயிருக்கவேண்டாம்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('EXO.20.12', 'EXO', 20, 12, 'Honour thy father and thy mother: that thy days may be long upon the land which the LORD thy God giveth thee.', 'உன் தேவனாகிய கர்த்தர் உனக்குக் கொடுக்கிற தேசத்திலே உன் நாட்கள் நீடித்திருப்பதற்கு, உன் தகப்பனையும் உன் தாயையும் கனம்பண்ணுவாயாக.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('EXO.33.14', 'EXO', 33, 14, 'And he said, My presence shall go with thee, and I will give thee rest.', 'அதற்கு அவர்: என் சமுகம் உனக்கு முன்பாகச் செல்லும், நான் உனக்கு இளைப்பாறுதல் தருவேன் என்றார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('EXO.34.6', 'EXO', 34, 6, 'And the LORD passed by before him, and proclaimed, The LORD, The LORD God, merciful and gracious, longsuffering, and abundant in goodness and truth,', 'கர்த்தர் அவனுக்கு முன்பாகக் கடந்துபோகிறபோது, அவர்: கர்த்தர், கர்த்தர்; இரக்கமும், கிருபையும், நீடிய சாந்தமும், மகா தயையும், சத்தியமுமுள்ள தேவன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('LEV.19.18', 'LEV', 19, 18, 'Thou shalt not avenge, nor bear any grudge against the children of thy people, but thou shalt love thy neighbour as thyself: I am the LORD.', 'பழிக்குப்பழி வாங்காமலும், உன் ஜனப்புத்திரர்மேல் பொறாமைகொள்ளாமலும், உன்னில் நீ அன்புகூருவதுபோல் பிறனிலும் அன்புகூருவாயாக; நான் கர்த்தர்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('NUM.6.24', 'NUM', 6, 24, 'The LORD bless thee, and keep thee:', 'கர்த்தர் உன்னை ஆசீர்வதித்து, உன்னைக் காக்கக்கடவர்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('NUM.6.25', 'NUM', 6, 25, 'The LORD make his face shine upon thee, and be gracious unto thee:', 'கர்த்தர் தம்முடைய முகத்தை உன்மேல் பிரகாசிக்கப்பண்ணி, உன்மேல் கிருபையாயிருக்கக்கடவர்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('NUM.6.26', 'NUM', 6, 26, 'The LORD lift up his countenance upon thee, and give thee peace.', 'கர்த்தர் தம்முடைய முகத்தை உன்மேல் பிரசன்னமாக்கி, உனக்குச் சமாதானம் கட்டளையிடக்கடவர் என்பதே.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('NUM.23.19', 'NUM', 23, 19, 'God is not a man, that he should lie; neither the son of man, that he should repent: hath he said, and shall he not do it? or hath he spoken, and shall he not make it good?', 'பொய் சொல்ல தேவன் ஒரு மனிதன் அல்ல; மனம்மாற அவர் ஒரு மனுபுத்திரனும் அல்ல; அவர் சொல்லியும் செய்யாதிருப்பாரா? அவர் வசனித்தும் நிறைவேற்றாதிருப்பாரா?')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('DEU.6.4', 'DEU', 6, 4, 'Hear, O Israel: The LORD our God is one LORD:', 'இஸ்ரவேலே, கேள்: நம்முடைய தேவனாகிய கர்த்தர் ஒருவரே கர்த்தர்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('DEU.6.5', 'DEU', 6, 5, 'And thou shalt love the LORD thy God with all thine heart, and with all thy soul, and with all thy might.', 'நீ உன் தேவனாகிய கர்த்தரிடத்தில் உன் முழு இருதயத்தோடும், உன் முழு ஆத்துமாவோடும், உன் முழுப் பலத்தோடும் அன்புகூருவாயாக.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('DEU.7.9', 'DEU', 7, 9, 'Know therefore that the LORD thy God, he is God, the faithful God, which keepeth covenant and mercy with them that love him and keep his commandments to a thousand generations;', 'ஆகையால் உன் தேவனாகிய கர்த்தரே தேவன் என்றும், தம்மில் அன்புகூர்ந்து, தமது கற்பனைகளைக் கைக்கொள்ளுகிறவர்களுக்கு அவர் ஆயிரம் தலைமுறைமட்டும் உடன்படிக்கையையும் தயவையும் காக்கிற உண்மையுள்ள தேவன் என்றும்,')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('DEU.31.6', 'DEU', 31, 6, 'Be strong and of a good courage, fear not, nor be afraid of them: for the LORD thy God, he it is that doth go with thee; he will not fail thee, nor forsake thee.', 'நீங்கள் பலங்கொண்டு திடமனதாயிருங்கள், அவர்களுக்குப் பயப்படவும் திகைக்கவும் வேண்டாம்; உன் தேவனாகிய, கர்த்தர்தாமே உன்னோடேகூட வருகிறார்; அவர் உன்னை விட்டு விலகுவதும் இல்லை; உன்னைக் கைவிடுவதும் இல்லை என்று சொன்னான்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('DEU.31.8', 'DEU', 31, 8, 'And the LORD, he it is that doth go before thee; he will be with thee, he will not fail thee, neither forsake thee: fear not, neither be dismayed.', 'கர்த்தர்தாமே உனக்கு முன்பாகப் போகிறவர், அவர் உன்னோடே இருப்பார்; அவர் உன்னை விட்டு விலகுவதுமில்லை, உன்னைக் கைவிடுவதுமில்லை; நீ பயப்படவும் கலங்கவும் வேண்டாம் என்றான்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('DEU.33.27', 'DEU', 33, 27, 'The eternal God is thy refuge, and underneath are the everlasting arms: and he shall thrust out the enemy from before thee; and shall say, Destroy them.', 'அநாதி தேவனே உனக்கு அடைக்கலம்; அவருடைய நித்திய புயங்கள் உனக்கு ஆதாரம்; அவர் உனக்கு முன்னின்று சத்துருக்களைத் துரத்தி, அவர்களை அழித்துப்போடு என்று கட்டளையிடுவார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JOS.1.9', 'JOS', 1, 9, 'Have not I commanded thee? Be strong and of a good courage; be not afraid, neither be thou dismayed: for the LORD thy God is with thee whithersoever thou goest.', 'நான் உனக்குக் கட்டளையிடவில்லையா? பலங்கொண்டு திடமனதாயிரு; திகையாதே, கலங்காதே, நீ போகும் இடமெல்லாம் உன் தேவனாகிய கர்த்தர் உன்னோடே இருக்கிறார் என்றார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('1SA.2.2', '1SA', 2, 2, 'There is none holy as the LORD: for there is none beside thee: neither is there any rock like our God.', 'கர்த்தரைப்போலப் பரிசுத்தமுள்ளவர் இல்லை; உம்மையல்லாமல் வேறொருவரும் இல்லை; எங்கள் தேவனைப்போல ஒரு கன்மலையும் இல்லை.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('1SA.12.24', '1SA', 12, 24, 'Only fear the LORD, and serve him in truth with all your heart: for consider how great things he hath done for you.', 'நீங்கள் எப்படியும் கர்த்தருக்குப் பயந்து, உங்கள் முழுஇருதயத்தோடும் உண்மையாய் அவரைச் சேவிக்கக்கடவீர்கள்; அவர் உங்களிடத்தில் எவ்வளவு மகிமையான காரியங்களைச் செய்தார் என்பதைச் சிந்தித்துப்பாருங்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('2SA.22.2', '2SA', 22, 2, 'And he said, The LORD is my rock, and my fortress, and my deliverer;', 'கர்த்தர் என் கன்மலையும், என் கோட்டையும், என் ரட்சகருமானவர்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('2SA.22.31', '2SA', 22, 31, 'As for God, his way is perfect; the word of the LORD is tried: he is a buckler to all them that trust in him.', 'தேவனுடைய வழி உத்தமமானது; கர்த்தருடைய வசனம் புடமிடப்பட்டது; தம்மை நம்புகிற அவனைவருக்கும் அவர் கேடகமாயிருக்கிறார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('1CH.16.11', '1CH', 16, 11, 'Seek the LORD and his strength, seek his face continually.', 'கர்த்தரையும் அவர் வல்லமையையும் நாடுங்கள்; அவர் சமுகத்தை நித்தமும் தேடுங்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('1CH.16.34', '1CH', 16, 34, 'O give thanks unto the LORD; for he is good; for his mercy endureth for ever.', 'கர்த்தரைத் துதியுங்கள், அவர் நல்லவர், அவர் கிருபை என்றுமுள்ளது.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JOB.1.21', 'JOB', 1, 21, 'And said, Naked came I out of my mother’s womb, and naked shall I return thither: the LORD gave, and the LORD hath taken away; blessed be the name of the LORD.', 'நிர்வாணியாய் என் தாயின் கர்ப்பத்திலிருந்து வந்தேன்; நிர்வாணியாய் அவ்விடத்துக்குத் திரும்புவேன்; கர்த்தர் கொடுத்தார், கர்த்தர் எடுத்தார்; கர்த்தருடைய நாமத்துக்கு ஸ்தோத்திரம் என்றான்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JOB.19.25', 'JOB', 19, 25, 'For I know that my redeemer liveth, and that he shall stand at the latter day upon the earth:', 'என் மீட்பர் உயிரோடிருக்கிறார் என்றும், அவர் கடைசிநாளில் பூமியின்மேல் நிற்பார் என்றும் நான் அறிந்திருக்கிறேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JOB.23.10', 'JOB', 23, 10, 'But he knoweth the way that I take: when he hath tried me, I shall come forth as gold.', 'ஆனாலும் நான் போகும் வழியை அவர் அறிவார்; அவர் என்னைச் சோதித்தபின் நான் பொன்னாக விளங்குவேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JOB.42.2', 'JOB', 42, 2, 'I know that thou canst do every thing, and that no thought can be withholden from thee.', 'தேவரீர் சகலத்தையும் செய்யவல்லவர்; நீர் செய்ய நினைத்தது தடைபடாது என்பதை அறிந்திருக்கிறேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.1.1', 'PSA', 1, 1, 'Blessed is the man that walketh not in the counsel of the ungodly, nor standeth in the way of sinners, nor sitteth in the seat of the scornful.', 'துன்மார்க்கருடைய ஆலோசனையில் நடவாமலும், பாவிகளுடைய வழியில் நில்லாமலும், பரியாசக்காரர் உட்காரும் இடத்தில் உட்காராமலும்,')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.1.2', 'PSA', 1, 2, 'But his delight is in the law of the LORD; and in his law doth he meditate day and night.', 'கர்த்தருடைய வேதத்தில் பிரியமாயிருந்து, இரவும் பகலும் அவருடைய வேதத்தில் தியானமாயிருக்கிற மனுஷன் பாக்கியவான்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.1.3', 'PSA', 1, 3, 'And he shall be like a tree planted by the rivers of water, that bringeth forth his fruit in his season; his leaf also shall not wither; and whatsoever he doeth shall prosper.', 'அவன் நீர்க்கால்களின் ஓரமாய் நடப்பட்டு, தன் காலத்தில் தன் கனியைத் தந்து, இலையுதிராதிருக்கிற மரத்தைப்போலிருப்பான்; அவன் செய்வதெல்லாம் வாய்க்கும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.4.8', 'PSA', 4, 8, 'I will both lay me down in peace, and sleep: for thou, LORD, only makest me dwell in safety.', 'சமாதானத்தோடே படுத்துக்கொண்டு நித்திரைசெய்வேன்; கர்த்தாவே, நீர் ஒருவரே என்னைச் சுகமாய்த் தங்கப்பண்ணுகிறீர்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.5.3', 'PSA', 5, 3, 'My voice shalt thou hear in the morning, O LORD; in the morning will I direct my prayer unto thee, and will look up.', 'கர்த்தாவே, காலையிலே என் சத்தத்தைக் கேட்டருளுவீர்; காலையிலே உமக்கு நேரே வந்து ஆயத்தமாகி, காத்திருப்பேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.8.1', 'PSA', 8, 1, 'O LORD, our Lord, how excellent is thy name in all the earth! who hast set thy glory above the heavens.', 'எங்கள் ஆண்டவராகிய கர்த்தாவே, உம்முடைய நாமம் பூமியெங்கும் எவ்வளவு மேன்மையுள்ளதாயிருக்கிறது! உம்முடைய மகத்துவத்தை வானங்களுக்கு மேலாக வைத்தீர்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.8.4', 'PSA', 8, 4, 'What is man, that thou art mindful of him? and the son of man, that thou visitest him?', 'மனுஷனை நீர் நினைக்கிறதற்கும், மனுஷகுமாரனை நீர் விசாரிக்கிறதற்கும் அவன் எம்மாத்திரம் என்கிறேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.9.10', 'PSA', 9, 10, 'And they that know thy name will put their trust in thee: for thou, LORD, hast not forsaken them that seek thee.', 'கர்த்தாவே, உம்மைத் தேடுகிறவர்களை நீர் கைவிடுகிறதில்லை; ஆதலால், உமது நாமத்தை அறிந்தவர்கள் உம்மை நம்பியிருப்பார்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.16.8', 'PSA', 16, 8, 'I have set the LORD always before me: because he is at my right hand, I shall not be moved.', 'கர்த்தரை எப்பொழுதும் எனக்கு முன்பாக வைத்திருக்கிறேன்; அவர் என் வலதுபாரிசத்தில் இருக்கிறபடியால் நான் அசைக்கப்படுவதில்லை.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.16.11', 'PSA', 16, 11, 'Thou wilt shew me the path of life: in thy presence is fulness of joy; at thy right hand there are pleasures for evermore.', 'ஜீவமார்க்கத்தை எனக்குத் தெரியப்படுத்துவீர்; உம்முடைய சமுகத்தில் பரிபூரண ஆனந்தமும், உம்முடைய வலது பாரிசத்தில் நித்திய பேரின்பமும் உண்டு.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.18.2', 'PSA', 18, 2, 'The LORD is my rock, and my fortress, and my deliverer; my God, my strength, in whom I will trust; my buckler, and the horn of my salvation, and my high tower.', 'கர்த்தர் என் கன்மலையும், என் கோட்டையும், என் இரட்சகரும், என் தேவனும் நான் நம்பியிருக்கிற என் துருகமும், என் கேடகமும், என் இரட்சணியக் கொம்பும், என் உயர்ந்த அடைக்கலமுமாயிருக்கிறார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.19.1', 'PSA', 19, 1, 'The heavens declare the glory of God; and the firmament sheweth his handywork.', 'வானங்கள் தேவனுடைய மகிமையை வெளிப்படுத்துகிறது, ஆகாயவிரிவு அவருடைய கரங்களின் கிரியையை அறிவிக்கிறது.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.19.14', 'PSA', 19, 14, 'Let the words of my mouth, and the meditation of my heart, be acceptable in thy sight, O LORD, my strength, and my redeemer.', 'என் கன்மலையும் என் மீட்பருமாகிய கர்த்தாவே, என் வாயின் வார்த்தைகளும், என் இருதயத்தின் தியானமும், உமது சமுகத்தில் பிரீதியாயிருப்பதாக.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.23.1', 'PSA', 23, 1, 'The LORD is my shepherd; I shall not want.', 'கர்த்தர் என் மேய்ப்பராயிருக்கிறார், நான் தாழ்ச்சியடையேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.23.4', 'PSA', 23, 4, 'Yea, though I walk through the valley of the shadow of death, I will fear no evil: for thou art with me; thy rod and thy staff they comfort me.', 'நான் மரண இருளின் பள்ளத்தாக்கிலே நடந்தாலும் பொல்லாப்புக்குப் பயப்படேன்; தேவரீர் என்னோடேகூட இருக்கிறீர்; உமது கோலும் உமது தடியும் என்னைத் தேற்றும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.23.6', 'PSA', 23, 6, 'Surely goodness and mercy shall follow me all the days of my life: and I will dwell in the house of the LORD for ever.', 'என் ஜீவனுள்ள நாளெல்லாம் நன்மையும் கிருபையும் என்னைத் தொடரும்; நான் கர்த்தருடைய வீட்டிலே நீடித்த நாட்களாய் நிலைத்திருப்பேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.25.4', 'PSA', 25, 4, 'Shew me thy ways, O LORD; teach me thy paths.', 'கர்த்தாவே, உம்முடைய வழிகளை எனக்குத் தெரிவியும்; உம்முடைய பாதைகளை எனக்குப் போதித்தருளும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.27.1', 'PSA', 27, 1, 'The LORD is my light and my salvation; whom shall I fear? the LORD is the strength of my life; of whom shall I be afraid?', 'கர்த்தர் என் வெளிச்சமும் என் இரட்சிப்புமானவர், யாருக்குப் பயப்படுவேன். கர்த்தர் என் ஜீவனின் பெலனானவர். யாருக்கு அஞ்சுவேன்?')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.27.14', 'PSA', 27, 14, 'Wait on the LORD: be of good courage, and he shall strengthen thine heart: wait, I say, on the LORD.', 'கர்த்தருக்குக் காத்திரு; அவர் உன் இருதயத்தை ஸ்திரப்படுத்துவார்; திடமனதாயிருந்து, கர்த்தருக்கே காத்திரு.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.28.7', 'PSA', 28, 7, 'The LORD is my strength and my shield; my heart trusted in him, and I am helped: therefore my heart greatly rejoiceth; and with my song will I praise him.', 'கர்த்தர் என் பெலனும் என் கேடகமுமாயிருக்கிறார்; என் இருதயம், அவரை நம்பியிருந்தது; நான் சகாயம் பெற்றேன், ஆகையால் என் இருதயம் களிகூருகிறது; என் பாட்டினால் அவரைத் துதிப்பேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.30.5', 'PSA', 30, 5, 'For his anger endureth but a moment; in his favour is life: weeping may endure for a night, but joy cometh in the morning.', 'அவருடைய கோபம் ஒரு நிமிஷம், அவருடைய தயவோ நீடியவாழ்வு; சாயங்காலத்தில் அழுகை தங்கும், விடியற்காலத்திலே களிப்புண்டாகும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.31.24', 'PSA', 31, 24, 'Be of good courage, and he shall strengthen your heart, all ye that hope in the LORD.', 'கர்த்தருக்குக் காத்திருக்கிறவர்களே, நீங்களெல்லாரும் திடமனதாயிருங்கள், அவர் உங்கள் இருதயத்தை ஸ்திரப்படுத்துவார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.32.8', 'PSA', 32, 8, 'I will instruct thee and teach thee in the way which thou shalt go: I will guide thee with mine eye.', 'நான் உனக்குப் போதித்து, நீ நடக்கவேண்டிய வழியை உனக்குக் காட்டுவேன்; உன்மேல் என் கண்ணை வைத்து, உனக்கு ஆலோசனை சொல்லுவேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.34.1', 'PSA', 34, 1, 'I will bless the LORD at all times: his praise shall continually be in my mouth.', 'கர்த்தரை நான் எக்காலத்திலும் ஸ்தோத்திரிப்பேன்; அவர் துதி எப்போதும் என் வாயிலிருக்கும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.34.8', 'PSA', 34, 8, 'O taste and see that the LORD is good: blessed is the man that trusteth in him.', 'கர்த்தர் நல்லவர் என்பதை ருசித்துப்பாருங்கள்; அவர்மேல் நம்பிக்கையாயிருக்கிற மனுஷன் பாக்கியவான்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.34.18', 'PSA', 34, 18, 'The LORD is nigh unto them that are of a broken heart; and saveth such as be of a contrite spirit.', 'நொறுங்குண்ட இருதயமுள்ளவர்களுக்குக் கர்த்தர் சமீபமாயிருந்து, நருங்குண்ட ஆவியுள்ளவர்களை இரட்சிக்கிறார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.37.4', 'PSA', 37, 4, 'Delight thyself also in the LORD: and he shall give thee the desires of thine heart.', 'கர்த்தரிடத்தில் மனமகிழ்ச்சியாயிரு; அவர் உன் இருதயத்தின் வேண்டுதல்களை உனக்கு அருள்செய்வார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.37.5', 'PSA', 37, 5, 'Commit thy way unto the LORD; trust also in him; and he shall bring it to pass.', 'உன் வழியைக் கர்த்தருக்கு ஒப்புவித்து, அவர்மேல் நம்பிக்கையாயிரு; அவரே காரியத்தை வாய்க்கப்பண்ணுவார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.37.7', 'PSA', 37, 7, 'Rest in the LORD, and wait patiently for him: fret not thyself because of him who prospereth in his way, because of the man who bringeth wicked devices to pass.', 'கர்த்தரை நோக்கி அமர்ந்து, அவருக்குக் காத்திரு; காரியசித்தியுள்ளவன்மேலும் தீவினைகளைச் செய்கிற மனுஷன்மேலும் எரிச்சலாகாதே.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.40.1', 'PSA', 40, 1, 'I waited patiently for the LORD; and he inclined unto me, and heard my cry.', 'கர்த்தருக்காகப் பொறுமையுடன் காத்திருந்தேன்; அவர் என்னிடமாய்ச் சாய்ந்து, என் கூப்பிடுதலைக் கேட்டார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.42.1', 'PSA', 42, 1, 'As the hart panteth after the water brooks, so panteth my soul after thee, O God.', 'மானானது நீரோடைகளை வாஞ்சித்துக் கதறுவதுபோல, தேவனே, என் ஆத்துமா உம்மை வாஞ்சித்துக் கதறுகிறது.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.42.11', 'PSA', 42, 11, 'Why art thou cast down, O my soul? and why art thou disquieted within me? hope thou in God: for I shall yet praise him, who is the health of my countenance, and my God.', 'என் ஆத்துமாவே, நீ ஏன் கலங்குகிறாய்? ஏன் எனக்குள் தியங்குகிறாய்? தேவனை நோக்கிக் காத்திரு; என் முகத்திற்கு இரட்சிப்பும் என் தேவனுமாயிருக்கிறவரை நான் இன்னும் துதிப்பேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.46.1', 'PSA', 46, 1, 'God is our refuge and strength, a very present help in trouble.', 'தேவன் நமக்கு அடைக்கலமும் பெலனும், ஆபத்துக்காலத்தில் அநுகூலமுமான துணையுமானவர்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.46.10', 'PSA', 46, 10, 'Be still, and know that I am God: I will be exalted among the heathen, I will be exalted in the earth.', 'நீங்கள் அமர்ந்திருந்து, நானே தேவனென்று அறிந்துகொள்ளுங்கள்; ஜாதிகளுக்குள்ளே உயர்ந்திருப்பேன், பூமியிலே உயர்ந்திருப்பேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.51.10', 'PSA', 51, 10, 'Create in me a clean heart, O God; and renew a right spirit within me.', 'தேவனே, சுத்த இருதயத்தை என்னிலே சிருஷ்டியும், நிலைவரமான ஆவியை என் உள்ளத்திலே புதுப்பியும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.51.12', 'PSA', 51, 12, 'Restore unto me the joy of thy salvation; and uphold me with thy free spirit.', 'உமது இரட்சணியத்தின் சந்தோஷத்தைத் திரும்பவும் எனக்குத் தந்து, உற்சாகமான ஆவி என்னைத் தாங்கும்படி செய்யும்,')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.55.22', 'PSA', 55, 22, 'Cast thy burden upon the LORD, and he shall sustain thee: he shall never suffer the righteous to be moved.', 'கர்த்தர்மேல் உன் பாரத்தைவைத்துவிடு, அவர் உன்னை ஆதரிப்பார்; நீதிமானை ஒருபோதும் தள்ளாடவொட்டார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.56.3', 'PSA', 56, 3, 'What time I am afraid, I will trust in thee.', 'நான் பயப்படுகிற நாளில் உம்மை நம்புவேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.62.1', 'PSA', 62, 1, 'Truly my soul waiteth upon God: from him cometh my salvation.', 'தேவனையே நோக்கி என் ஆத்துமா அமர்ந்திருக்கிறது; அவரால் என் இரட்சிப்பு வரும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.62.8', 'PSA', 62, 8, 'Trust in him at all times; ye people, pour out your heart before him: God is a refuge for us. Selah.', 'ஜனங்களே, எக்காலத்திலும் அவரை நம்புங்கள்; அவர் சமுகத்தில் உங்கள் இருதயத்தை ஊற்றிவிடுங்கள்; தேவன் நமக்கு அடைக்கலமாயிருக்கிறார். (சேலா.)')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.63.1', 'PSA', 63, 1, 'O God, thou art my God; early will I seek thee: my soul thirsteth for thee, my flesh longeth for thee in a dry and thirsty land, where no water is;', 'தேவனே, நீர் என்னுடைய தேவன், அதிகாலமே உம்மைத் தேடுகிறேன்; வறண்டதும் விடாய்த்ததும் தண்ணீரற்றதுமான நிலத்திலே என் ஆத்துமா உம்மேல் தாகமாயிருக்கிறது. என் மாம்சமானது உம்மை வாஞ்சிக்கிறது.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.66.20', 'PSA', 66, 20, 'Blessed be God, which hath not turned away my prayer, nor his mercy from me.', 'என் ஜெபத்தைத் தள்ளாமலும், தமது கிருபையை என்னைவிட்டு விலக்காமலும் இருந்த தேவனுக்கு ஸ்தோத்திரமுண்டாவதாக.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.73.26', 'PSA', 73, 26, 'My flesh and my heart faileth: but God is the strength of my heart, and my portion for ever.', 'என் மாம்சமும் என் இருதயமும் மாண்டுபோகிறது; தேவன் என்றென்றைக்கும் என் இருதயத்தின் கன்மலையும் என் பங்குமாயிருக்கிறார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.84.11', 'PSA', 84, 11, 'For the LORD God is a sun and shield: the LORD will give grace and glory: no good thing will he withhold from them that walk uprightly.', 'தேவனாகிய கர்த்தர் சூரியனும் கேடகமுமானவர்; கர்த்தர் கிருபையையும் மகிமையையும் அருளுவார்; உத்தமமாய் நடக்கிறவர்களுக்கு நன்மையை வழங்காதிரார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.86.5', 'PSA', 86, 5, 'For thou, Lord, art good, and ready to forgive; and plenteous in mercy unto all them that call upon thee.', 'ஆண்டவரே, நீர் நல்லவரும், மன்னிக்கிறவரும், உம்மை நோக்கிக் கூப்பிடுகிற யாவர்மேலும் கிருபை மிகுந்தவருமாயிருக்கிறீர்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.90.12', 'PSA', 90, 12, 'So teach us to number our days, that we may apply our hearts unto wisdom.', 'நாங்கள் ஞான இருதயமுள்ளவர்களாகும்படி, எங்கள் நாட்களை எண்ணும் அறிவை எங்களுக்குப் போதித்தருளும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.91.1', 'PSA', 91, 1, 'He that dwelleth in the secret place of the most High shall abide under the shadow of the Almighty.', 'உன்னதமானவரின் மறைவிலிருக்கிறவன் சர்வவல்லவருடைய நிழலில் தங்குவான்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.91.2', 'PSA', 91, 2, 'I will say of the LORD, He is my refuge and my fortress: my God; in him will I trust.', 'நான் கர்த்தரை நோக்கி: நீர் என் அடைக்கலம், என் கோட்டை, என் தேவன், நான் நம்பியிருக்கிறவர் என்று சொல்லுவேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.91.11', 'PSA', 91, 11, 'For he shall give his angels charge over thee, to keep thee in all thy ways.', 'உன் வழிகளிலெல்லாம் உன்னைக்காக்கும்படி உனக்காகத் தம்முடைய தூதர்களுக்குக் கட்டளையிடுவார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.95.6', 'PSA', 95, 6, 'O come, let us worship and bow down: let us kneel before the LORD our maker.', 'நம்மை உண்டாக்கின கர்த்தருக்கு முன்பாக நாம் பணிந்து குனிந்து முழங்காற்படியிடக்கடவோம் வாருங்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.96.1', 'PSA', 96, 1, 'O sing unto the LORD a new song: sing unto the LORD, all the earth.', 'கர்த்தருக்குப் புதுப்பாட்டைப் பாடுங்கள், பூமியின் குடிகளே, எல்லாரும் கர்த்தரைப் பாடுங்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.100.4', 'PSA', 100, 4, 'Enter into his gates with thanksgiving, and into his courts with praise: be thankful unto him, and bless his name.', 'அவர் வாசல்களில் துதியோடும், அவர் பிராகாரங்களில் புகழ்ச்சியோடும் பிரவேசித்து, அவரைத் துதித்து, அவருடைய நாமத்தை ஸ்தோத்திரியுங்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.100.5', 'PSA', 100, 5, 'For the LORD is good; his mercy is everlasting; and his truth endureth to all generations.', 'கர்த்தர் நல்லவர், அவருடைய கிருபை என்றென்றைக்கும், அவருடைய உண்மை தலைமுறை தலைமுறைக்கும் உள்ளது.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.103.1', 'PSA', 103, 1, 'Bless the LORD, O my soul: and all that is within me, bless his holy name.', 'என் ஆத்துமாவே, கர்த்தரை ஸ்தோத்திரி; என் முழு உள்ளமே, அவருடைய பரிசுத்த நாமத்தை ஸ்தோத்திரி.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.103.2', 'PSA', 103, 2, 'Bless the LORD, O my soul, and forget not all his benefits:', 'என் ஆத்துமாவே, கர்த்தரை ஸ்தோத்திரி; அவர் செய்த சகல உபகாரங்களையும் மறவாதே.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.103.12', 'PSA', 103, 12, 'As far as the east is from the west, so far hath he removed our transgressions from us.', 'மேற்குக்கும் கிழக்குக்கும் எவ்வளவு தூரமோ, அவ்வளவு தூரமாய் அவர் நம்முடைய பாவங்களை நம்மை விட்டு விலக்கினார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.107.1', 'PSA', 107, 1, 'O give thanks unto the LORD, for he is good: for his mercy endureth for ever.', 'கர்த்தரைத் துதியுங்கள்; அவர் நல்லவர் அவர் கிருபை என்றுமுள்ளது.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.112.7', 'PSA', 112, 7, 'He shall not be afraid of evil tidings: his heart is fixed, trusting in the LORD.', 'துர்ச்செய்தியைக் கேட்கிறதினால் பயப்படான்; அவன் இருதயம் கர்த்தரை நம்பித் திடனாயிருக்கும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.118.24', 'PSA', 118, 24, 'This is the day which the LORD hath made; we will rejoice and be glad in it.', 'இது கர்த்தர் உண்டுபண்ணின நாள், இதிலே களிகூர்ந்து மகிழக்கடவோம்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.119.11', 'PSA', 119, 11, 'Thy word have I hid in mine heart, that I might not sin against thee.', 'நான் உமக்கு விரோதமாய்ப் பாவஞ்செய்யாதபடிக்கு, உமது வாக்கை என்னிருதயத்தில் வைத்து வைத்தேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.119.105', 'PSA', 119, 105, 'Thy word is a lamp unto my feet, and a light unto my path.', 'உம்முடைய வசனம் என் கால்களுக்குத் தீபமும், என் பாதைக்கு வெளிச்சமுமாயிருக்கிறது.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.119.130', 'PSA', 119, 130, 'The entrance of thy words giveth light; it giveth understanding unto the simple.', 'உம்முடைய வசனத்தின் பிரசித்தம் வெளிச்சம் தந்து, பேதைகளை உணர்வுள்ளவர்களாக்கும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.121.1', 'PSA', 121, 1, 'I will lift up mine eyes unto the hills, from whence cometh my help.', 'எனக்கு ஒத்தாசை வரும் பர்வதங்களுக்கு நேராக என் கண்களை ஏறெடுக்கிறேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.121.2', 'PSA', 121, 2, 'My help cometh from the LORD, which made heaven and earth.', 'வானத்தையும் பூமியையும் உண்டாக்கின கர்த்தரிடத்திலிருந்து எனக்கு ஒத்தாசை வரும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.121.8', 'PSA', 121, 8, 'The LORD shall preserve thy going out and thy coming in from this time forth, and even for evermore.', 'கர்த்தர் உன் போக்கையும் உன் வரத்தையும் இதுமுதற்கொண்டு என்றைக்குங் காப்பார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.126.5', 'PSA', 126, 5, 'They that sow in tears shall reap in joy.', 'கண்ணீரோடே விதைக்கிறவர்கள் கெம்பீரத்தோடே அறுப்பார்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.127.1', 'PSA', 127, 1, 'Except the LORD build the house, they labour in vain that build it: except the LORD keep the city, the watchman waketh but in vain.', 'கர்த்தர் வீட்டைக் கட்டாராகில், அதைக் கட்டுகிறவர்களின் பிரயாசம் விருதா; கர்த்தர் நகரத்தைக் காவாராகில் காவலாளர் விழித்திருக்கிறது விருதா.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.133.1', 'PSA', 133, 1, 'Behold, how good and how pleasant it is for brethren to dwell together in unity!', 'இதோ, சகோதரர் ஒருமித்து வாசம்பண்ணுகிறது எத்தனை நன்மையும் எத்தனை இன்பமுமானது?')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.136.1', 'PSA', 136, 1, 'O give thanks unto the LORD; for he is good: for his mercy endureth for ever.', 'கர்த்தரைத் துதியுங்கள், அவர் நல்லவர், அவர் கிருபை என்றுமுள்ளது.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.139.14', 'PSA', 139, 14, 'I will praise thee; for I am fearfully and wonderfully made: marvellous are thy works; and that my soul knoweth right well.', 'நான் பிரமிக்கத்தக்க அதிசயமாய் உண்டாக்கப்பட்டபடியால் உம்மைத் துதிப்பேன்; உமது கிரியைகள் அதிசயமானவைகள். அது என் ஆத்துமாவுக்கு நன்றாய்த் தெரியும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.139.23', 'PSA', 139, 23, 'Search me, O God, and know my heart: try me, and know my thoughts:', 'தேவனே என்னை ஆராய்ந்து, என் இருதயத்தை அறிந்துகொள்ளும், என்னைச் சோதித்து, என் சிந்தனைகளை அறிந்துகொள்ளும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.143.8', 'PSA', 143, 8, 'Cause me to hear thy lovingkindness in the morning; for in thee do I trust: cause me to know the way wherein I should walk; for I lift up my soul unto thee.', 'அதிகாலையில் உமது கிருபையைக் கேட்கப்பண்ணும், உம்மை நம்பியிருக்கிறேன், நான் நடக்கவேண்டிய வழியை எனக்குக் காண்பியும்; உம்மிடத்தில் என் ஆத்துமாவை உயர்த்துகிறேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.145.18', 'PSA', 145, 18, 'The LORD is nigh unto all them that call upon him, to all that call upon him in truth.', 'தம்மை நோக்கிக் கூப்பிடுகிற யாவருக்கும், உண்மையாய்த் தம்மை நோக்கிக் கூப்பிடுகிற யாவருக்கும், கர்த்தர் சமீபமாயிருக்கிறார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.147.3', 'PSA', 147, 3, 'He healeth the broken in heart, and bindeth up their wounds.', 'இருதயம் நொறுங்குண்டவர்களைக் குணமாக்குகிறார், அவர்களுடைய காயங்களைக் கட்டுகிறார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PSA.150.6', 'PSA', 150, 6, 'Let every thing that hath breath praise the LORD. Praise ye the LORD.', 'சுவாசமுள்ள யாவும் கர்த்தரைத் துதிப்பதாக. (அல்லேலுூயா.)')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PRO.1.7', 'PRO', 1, 7, 'The fear of the LORD is the beginning of knowledge: but fools despise wisdom and instruction.', 'கர்த்தருக்குப் பயப்படுதலே ஞானத்தின் ஆரம்பம்; மூடர் ஞானத்தையும் போதகத்தையும் அசட்டைபண்ணுகிறார்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PRO.3.5', 'PRO', 3, 5, 'Trust in the LORD with all thine heart; and lean not unto thine own understanding.', 'உன் சுயபுத்தியின்மேல் சாயாமல், உன் முழு இருதயத்தோடும் கர்த்தரில் நம்பிக்கையாயிருந்து,')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PRO.3.6', 'PRO', 3, 6, 'In all thy ways acknowledge him, and he shall direct thy paths.', 'உன் வழிகளிலெல்லாம் அவரை நினைத்துக்கொள்; அப்பொழுது அவர் உன் பாதைகளைச் செவ்வைப்படுத்துவார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PRO.3.9', 'PRO', 3, 9, 'Honour the LORD with thy substance, and with the firstfruits of all thine increase:', 'உன் பொருளாலும், உன் எல்லா விளைவின் முதற்பலனாலும் கர்த்தரைக் கனம்பண்ணு.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PRO.4.23', 'PRO', 4, 23, 'Keep thy heart with all diligence; for out of it are the issues of life.', 'எல்லாக் காவலோடும் உன் இருதயத்தைக் காத்துக்கொள், அதினிடத்தினின்று ஜீவஊற்று புறப்படும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PRO.9.10', 'PRO', 9, 10, 'The fear of the LORD is the beginning of wisdom: and the knowledge of the holy is understanding.', 'கர்த்தருக்குப் பயப்படுதலே ஞானத்தின் ஆரம்பம்; பரிசுத்தரின் அறிவே அறிவு.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PRO.10.12', 'PRO', 10, 12, 'Hatred stirreth up strifes: but love covereth all sins.', 'பகை விரோதங்களை எழுப்பும்; அன்போ சகல பாவங்களையும் மூடும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PRO.11.25', 'PRO', 11, 25, 'The liberal soul shall be made fat: and he that watereth shall be watered also himself.', 'உதாரகுணமுள்ள ஆத்துமா செழிக்கும்; எவன் தண்ணீர் பாய்ச்சுகிறானோ அவனுக்குத் தண்ணீர் பாய்ச்சப்படும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PRO.12.25', 'PRO', 12, 25, 'Heaviness in the heart of man maketh it stoop: but a good word maketh it glad.', 'மனுஷனுடைய இருதயத்திலுள்ள கவலை அதை ஒடுக்கும்; நல்வார்த்தையோ அதை மகிழ்ச்சியாக்கும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PRO.14.12', 'PRO', 14, 12, 'There is a way which seemeth right unto a man, but the end thereof are the ways of death.', 'மனுஷனுக்குச் செம்மையாய்த் தோன்றுகிற வழி உண்டு; அதின் முடிவோ மரண வழிகள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PRO.15.1', 'PRO', 15, 1, 'A soft answer turneth away wrath: but grievous words stir up anger.', 'மெதுவான பிரதியுத்தரம் உக்கிரத்தை மாற்றும்; கடுஞ்சொற்களோ கோபத்தை எழுப்பும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PRO.16.3', 'PRO', 16, 3, 'Commit thy works unto the LORD, and thy thoughts shall be established.', 'உன் செய்கைகளைக் கர்த்தருக்கு ஒப்புவி; அப்பொழுது உன் யோசனைகள் உறுதிப்படும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PRO.16.9', 'PRO', 16, 9, 'A man’s heart deviseth his way: but the LORD directeth his steps.', 'மனுஷனுடைய இருதயம் அவனுடைய வழியை யோசிக்கும்; அவனுடைய நடைகளை உறுதிப்படுத்துகிறவரோ கர்த்தர்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PRO.17.17', 'PRO', 17, 17, 'A friend loveth at all times, and a brother is born for adversity.', 'சிநேகிதன் எல்லாக் காலத்திலும் சிநேகிப்பான்; இடுக்கணில் உதவவே சகோதரன் பிறந்திருக்கிறான்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PRO.18.10', 'PRO', 18, 10, 'The name of the LORD is a strong tower: the righteous runneth into it, and is safe.', 'கர்த்தரின் நாமம் பலத்த துருகம்; நீதிமான் அதற்குள் ஓடிச் சுகமாயிருப்பான்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PRO.19.21', 'PRO', 19, 21, 'There are many devices in a man’s heart; nevertheless the counsel of the LORD, that shall stand.', 'மனுஷனுடைய இருதயத்தின் எண்ணங்கள் அநேகம்; ஆனாலும் கர்த்தருடைய யோசனையே நிலைநிற்கும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PRO.20.27', 'PRO', 20, 27, 'The spirit of man is the candle of the LORD, searching all the inward parts of the belly.', 'மனுஷனுடைய ஆவி கர்த்தர் தந்த தீபமாயிருக்கிறது; அது உள்ளத்திலுள்ளவைகளையெல்லாம் ஆராய்ந்துபார்க்கும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PRO.22.6', 'PRO', 22, 6, 'Train up a child in the way he should go: and when he is old, he will not depart from it.', 'பிள்ளையானவன் நடக்கவேண்டிய வழியிலே அவனை நடத்து; அவன் முதிர்வயதிலும் அதை விடாதிருப்பான்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PRO.27.17', 'PRO', 27, 17, 'Iron sharpeneth iron; so a man sharpeneth the countenance of his friend.', 'இரும்பை இரும்பு கருக்கிடும்; அப்படியே மனுஷனும் தன் சிநேகிதனுடைய முகத்தைக் கருக்கிடுகிறான்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PRO.28.13', 'PRO', 28, 13, 'He that covereth his sins shall not prosper: but whoso confesseth and forsaketh them shall have mercy.', 'தன் பாவங்களை மறைக்கிறவன் வாழ்வடையமாட்டான்; அவைகளை அறிக்கை செய்து விட்டுவிடுகிறவனோ இரக்கம் பெறுவான்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PRO.31.30', 'PRO', 31, 30, 'Favour is deceitful, and beauty is vain: but a woman that feareth the LORD, she shall be praised.', 'செளந்தரியம் வஞ்சனையுள்ளது, அழகும் வீண், கர்த்தருக்குப் பயப்படுகிற ஸ்திரீயே புகழப்படுவாள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ECC.3.1', 'ECC', 3, 1, 'To every thing there is a season, and a time to every purpose under the heaven:', 'ஒவ்வொன்றிற்கும் ஒவ்வொரு காலமுண்டு; வானத்தின் கீழிருக்கிற ஒவ்வொரு காரியத்துக்கும் ஒவ்வொரு சமயமுண்டு.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ECC.3.11', 'ECC', 3, 11, 'He hath made every thing beautiful in his time: also he hath set the world in their heart, so that no man can find out the work that God maketh from the beginning to the end.', 'அவர் சகலத்தையும் அதினதின் காலத்திலே நேர்த்தியாகச் செய்திருக்கிறார்; உலகத்தையும் அவர்கள் உள்ளத்திலே வைத்திருக்கிறார்; ஆதலால் தேவன் ஆதிமுதல் அந்தம்மட்டும் செய்துவரும்கிரியையை மனுஷன் கண்டுபிடியான்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ECC.4.9', 'ECC', 4, 9, 'Two are better than one; because they have a good reward for their labour.', 'ஒண்டியாயிருப்பதிலும் இருவர் கூடியிருப்பது நலம்; அவர்களுடைய பிரயாசத்தினால் அவர்களுக்கு நல்ல பலனுண்டாகும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ECC.12.1', 'ECC', 12, 1, 'Remember now thy Creator in the days of thy youth, while the evil days come not, nor the years draw nigh, when thou shalt say, I have no pleasure in them;', 'நீ உன் வாலிபப்பிராயத்திலே உன் சிருஷ்டிகரை நினை; தீங்குநாட்கள் வராததற்குமுன்னும், எனக்குப் பிரியமானவைகளல்ல என்று நீ சொல்லும் வருஷங்கள் சேராததற்குமுன்னும்,')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ECC.12.13', 'ECC', 12, 13, 'Let us hear the conclusion of the whole matter: Fear God, and keep his commandments: for this is the whole duty of man.', 'காரியத்தின் கடைத்தொகையை கேட்போமாக, தேவனுக்குப் பயந்து, அவர் கற்பனைகளைக் கைக்கொள்; எல்லா மனுஷர்மேலும் விழுந்த கடமை இதுவே.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('SNG.8.7', 'SNG', 8, 7, 'Many waters cannot quench love, neither can the floods drown it: if a man would give all the substance of his house for love, it would utterly be contemned.', 'திரளான தண்ணீர்கள் நேசத்தை அவிக்கமாட்டாது, வெள்ளங்களும் அதைத் தணிக்கமாட்டாது; ஒருவன் தன் வீட்டிலுள்ள ஆஸ்திகளையெல்லாம் நேசத்துக்காகக் கொடுத்தாலும், அது முற்றிலும் அசட்டைபண்ணப்படும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ISA.1.18', 'ISA', 1, 18, 'Come now, and let us reason together, saith the LORD: though your sins be as scarlet, they shall be as white as snow; though they be red like crimson, they shall be as wool.', 'வழக்காடுவோம் வாருங்கள் என்று கர்த்தர் சொல்லுகிறார்; உங்கள் பாவங்கள் சிவேரென்றிருந்தாலும் உறைந்த மழையைப் போல் வெண்மையாகும்; அவைகள் இரத்தாம்பரச் சிவப்பாயிருந்தாலும் பஞ்சைப்போலாகும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ISA.6.8', 'ISA', 6, 8, 'Also I heard the voice of the Lord, saying, Whom shall I send, and who will go for us? Then said I, Here am I; send me.', 'பின்பு யாரை நான் அனுப்புவேன், யார் நமது காரியமாய்ப் போவான் என்று உரைக்கிற ஆண்டவருடைய சத்தத்தைக் கேட்டேன். அதற்கு நான்: இதோ, அடியேன் இருக்கிறேன்; என்னை அனுப்பும் என்றேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ISA.7.14', 'ISA', 7, 14, 'Therefore the Lord himself shall give you a sign; Behold, a virgin shall conceive, and bear a son, and shall call his name Immanuel.', 'ஆதலால் ஆண்டவர் தாமே உங்களுக்கு ஒரு அடையாளத்தைக் கொடுப்பார்; இதோ, ஒரு கன்னிகை கர்ப்பவதியாகி ஒரு குமாரனைப் பெறுவாள், அவருக்கு இம்மானுவேல் என்று பேரிடுவாள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ISA.12.2', 'ISA', 12, 2, 'Behold, God is my salvation; I will trust, and not be afraid: for the LORD JEHOVAH is my strength and my song; he also is become my salvation.', 'இதோ, தேவனே என் இரட்சிப்பு; நான் பயப்படாமல் நம்பிக்கையாயிருப்பேன்; கர்த்தராகிய யேகோவா என் பெலனும், என் கீதமுமானவர்; அவரே எனக்கு இரட்சிப்புமானவர்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ISA.25.1', 'ISA', 25, 1, 'O Lord, thou art my God; I will exalt thee, I will praise thy name; for thou hast done wonderful things; thy counsels of old are faithfulness and truth.', 'கர்த்தாவே, நீரே என் தேவன்; உம்மை உயர்த்தி, உமது நாமத்தைத் துதிப்பேன்; நீர் அதிசயமானவைகளைச் செய்தீர்; உமது ஆலோசனைகள் சத்தியமும் உறுதியுமானவைகள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ISA.26.3', 'ISA', 26, 3, 'Thou wilt keep him in perfect peace, whose mind is stayed on thee: because he trusteth in thee.', 'உம்மை உறுதியாய்ப் பற்றிக்கொண்ட மனதையுடையவன் உம்மையே நம்பியிருக்கிறபடியால், நீர் அவனைப் பூரண சமாதானத்துடன் காத்துக்கொள்வீர்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ISA.30.15', 'ISA', 30, 15, 'For thus saith the Lord GOD, the Holy One of Israel; In returning and rest shall ye be saved; in quietness and in confidence shall be your strength: and ye would not.', 'நீங்கள் மனந்திரும்பி அமர்ந்திருந்தால் இரட்சிக்கப்படுவீர்கள்; அமரிக்கையும் நம்பிக்கையுமே உங்கள் பெலனாயிருக்கும் என்று இஸ்ரவேலின் பரிசுத்தராயிருக்கிற கர்த்தராகிய தேவன் சொல்லுகிறார்; நீங்களோ அப்படிச் செய்ய மனதாயிராமல்;')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ISA.30.21', 'ISA', 30, 21, 'And thine ears shall hear a word behind thee, saying, This is the way, walk ye in it, when ye turn to the right hand, and when ye turn to the left.', 'நீங்கள் வலதுபுறமாய்ச் சாயும்போதும், இடதுபுறமாய்ச் சாயும்போதும்: வழி இதுவே, இதிலே நடவுங்கள் என்று உங்களுக்குப் பின்னாலே சொல்லும் வார்த்தையை உங்கள் காதுகள் கேட்கும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ISA.40.8', 'ISA', 40, 8, 'The grass withereth, the flower fadeth: but the word of our God shall stand for ever.', 'புல் உலர்ந்து பூ உதிரும்; நமது தேவனுடைய வசனமோ என்றென்றைக்கும் நிற்கும் என்பதையே சொல்லென்று உரைத்தது.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ISA.40.29', 'ISA', 40, 29, 'He giveth power to the faint; and to them that have no might he increaseth strength.', 'சோர்ந்துபோகிறவனுக்கு அவர் பெலன் கொடுத்து, சத்துவமில்லாதவனுக்குச் சத்துவத்தைப் பெருகப்பண்ணுகிறார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ISA.40.31', 'ISA', 40, 31, 'But they that wait upon the LORD shall renew their strength; they shall mount up with wings as eagles; they shall run, and not be weary; and they shall walk, and not faint.', 'கர்த்தருக்குக் காத்திருக்கிறவர்களோ புதுப்பெலனடைத்து, கழுகுகளைப்போலச் செட்டைகளை அடித்து எழும்புவார்கள்; அவர்கள் ஓடினாலும் இளைப்படையார்கள், நடந்தாலும் சோர்ந்துபோகார்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ISA.41.10', 'ISA', 41, 10, 'Fear thou not; for I am with thee: be not dismayed; for I am thy God: I will strengthen thee; yea, I will help thee; yea, I will uphold thee with the right hand of my righteousness.', 'நீ பயப்படாதே, நான் உன்னுடனே இருக்கிறேன்; திகையாதே, நான் உன் தேவன்; நான் உன்னைப் பலப்படுத்தி உனக்குச் சகாயம்பண்ணுவேன்; என் நீதியின் வலதுகரத்தினால் உன்னைத் தாங்குவேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ISA.41.13', 'ISA', 41, 13, 'For I the LORD thy God will hold thy right hand, saying unto thee, Fear not; I will help thee.', 'உன் தேவனாயிருக்கிற கர்த்தராகிய நான் உன் வலதுகையைப் பிடித்து பயப்படாதே, நான் உனக்குத் துணைநிற்கிறேன் என்று சொல்லுகிறேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ISA.43.19', 'ISA', 43, 19, 'Behold, I will do a new thing; now it shall spring forth; shall ye not know it? I will even make a way in the wilderness, and rivers in the desert.', 'இதோ, நான் புதிய காரியத்தைச் செய்கிறேன்; இப்பொழுதே அது தோன்றும்; நீங்கள் அதை அறியீர்களா? நான் வனாந்தரத்திலே வழியையும் அவாந்தரவெளியிலே ஆறுகளையும் உண்டாக்குவேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ISA.45.22', 'ISA', 45, 22, 'Look unto me, and be ye saved, all the ends of the earth: for I am God, and there is none else.', 'பூமியின் எல்லையெங்குமுள்ளவர்களே, என்னை நோக்கிப்பாருங்கள்; அப்பொழுது இரட்சிக்கப்படுவீர்கள்; நானே தேவன், வேறொருவரும் இல்லை.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ISA.49.15', 'ISA', 49, 15, 'Can a woman forget her sucking child, that she should not have compassion on the son of her womb? yea, they may forget, yet will I not forget thee.', 'ஸ்திரீயானவள் தன் கர்ப்பத்தின் பிள்ளைக்கு இரங்காமல், தன் பாலகனை மறப்பாளோ? அவர்கள் மறந்தாலும், நான் உன்னை மறப்பதில்லை.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ISA.53.5', 'ISA', 53, 5, 'But he was wounded for our transgressions, he was bruised for our iniquities: the chastisement of our peace was upon him; and with his stripes we are healed.', 'நம்முடைய மீறுதல்களினிமித்தம் அவர் காயப்பட்டு, நம்முடைய அக்கிரமங்களினிமித்தம் அவர் நொறுக்கப்பட்டார்; நமக்குச் சமாதானத்தை உண்டுபண்ணும் ஆக்கினை அவர்மேல் வந்தது; அவருடைய தழும்புகளால் குணமாகிறோம்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ISA.53.6', 'ISA', 53, 6, 'All we like sheep have gone astray; we have turned every one to his own way; and the LORD hath laid on him the iniquity of us all.', 'நாமெல்லாரும் ஆடுகளைப்போல வழிதப்பித்திரிந்து, அவனவன் தன்தன் வழியிலே போனோம்; கர்த்தரோ நம்மெல்லாருடைய அக்கிரமத்தையும் அவர்மேல் விழப்பண்ணினார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ISA.55.6', 'ISA', 55, 6, 'Seek ye the LORD while he may be found, call ye upon him while he is near:', 'கர்த்தரைக் கண்டடையத்தக்க சமயத்தில் அவரைத் தேடுங்கள்; அவர் சமீபமாயிருக்கையில் அவரை நோக்கிக் கூப்பிடுங்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ISA.55.8', 'ISA', 55, 8, 'For my thoughts are not your thoughts, neither are your ways my ways, saith the LORD.', 'என் நினைவுகள் உங்கள் நினைவுகள் அல்ல; உங்கள் வழிகள் என் வழிகளும் அல்லவென்று கர்த்தர் சொல்லுகிறார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ISA.55.11', 'ISA', 55, 11, 'So shall my word be that goeth forth out of my mouth: it shall not return unto me void, but it shall accomplish that which I please, and it shall prosper in the thing whereto I sent it.', 'அப்படியே என் வாயிலிருந்து புறப்படும் வசனமும் இருக்கும், அது வெறுமையாய் என்னிடத்திற்குத் திரும்பாமல், அது நான் விரும்புகிறதைச்செய்து, நான் அதை அனுப்பின காரியமாகும்படி வாய்க்கும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ISA.60.1', 'ISA', 60, 1, 'Arise, shine; for thy light is come, and the glory of the LORD is risen upon thee.', 'எழும்பிப் பிரகாசி; உன் ஒளிவந்தது, கர்த்தருடைய மகிமை உன்மேல் உதித்தது.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ISA.64.8', 'ISA', 64, 8, 'But now, O LORD, thou art our father; we are the clay, and thou our potter; and we all are the work of thy hand.', 'இப்பொழுதும் கர்த்தாவே, நீர் எங்களுடைய பிதா, நாங்கள் களிமண்; நீர் எங்களை உருவாக்குகிறவர், நாங்கள் அனைவரும் உமது கரத்தின் கிரியை.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JER.1.5', 'JER', 1, 5, 'Before I formed thee in the belly I knew thee; and before thou camest forth out of the womb I sanctified thee, and I ordained thee a prophet unto the nations.', 'நான் உன்னைத் தாயின் வயிற்றில் உருவாக்கு முன்னே உன்னை அறிந்தேன்; நீ கர்ப்பத்திலிருந்து வெளிப்படுமுன்னே நான் உன்னைப் பரிசுத்தம்பண்ணி, உன்னை ஜாதிகளுக்குத் தீர்க்கதரிசியாகக் கட்டளையிட்டேன் என்று சொன்னார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JER.17.7', 'JER', 17, 7, 'Blessed is the man that trusteth in the LORD, and whose hope the LORD is.', 'கர்த்தர்மேல் நம்பிக்கைவைத்து, கர்த்தரைத் தன் நம்பிக்கையாகக் கொண்டிருக்கிற மனுஷன் பாக்கியவான்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JER.29.11', 'JER', 29, 11, 'For I know the thoughts that I think toward you, saith the LORD, thoughts of peace, and not of evil, to give you an expected end.', 'நீங்கள் எதிர்பார்த்திருக்கும் முடிவை உங்களுக்கு கொடுக்கும்படிக்கு நான் உங்கள்பேரில் நினைத்திருக்கிற நினைவுகளை அறிவேன் என்று கர்த்தர் சொல்லுகிறார்; அவைகள் தீமைக்கல்ல, சமாதானத்துக்கேதுவான நினைவுகளே.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JER.29.13', 'JER', 29, 13, 'And ye shall seek me, and find me, when ye shall search for me with all your heart.', 'உங்கள் முழு இருதயத்தோடும் என்னைத் தேடினீர்களானால், என்னைத் தேடுகையில் கண்டுபிடிப்பீர்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JER.31.3', 'JER', 31, 3, 'The LORD hath appeared of old unto me, saying, Yea, I have loved thee with an everlasting love: therefore with lovingkindness have I drawn thee.', 'பூர்வகாலமுதல் கர்த்தர் எங்களுக்குத் தரிசனையானார் என்பாய்; ஆம் அநாதி சிநேகத்தால் உன்னைச் சிநேகித்தேன்; ஆதலால் காருணியத்தால் உன்னை இழுத்துக்கொள்ளுகிறேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JER.32.17', 'JER', 32, 17, 'Ah Lord GOD! behold, thou hast made the heaven and the earth by thy great power and stretched out arm, and there is nothing too hard for thee:', 'ஆ, கர்த்தராகிய ஆண்டவரே, இதோ, தேவரீர் உம்முடைய மகாபலத்தினாலும், நீட்டப்பட்ட உம்முடைய புயத்தினாலும், வானத்தையும் பூமியையும் உண்டாக்கினீர்; உம்மாலே செய்யக் கூடாத அதிசயமான காரியம் ஒன்றுமில்லை.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JER.33.3', 'JER', 33, 3, 'Call unto me, and I will answer thee, and shew thee great and mighty things, which thou knowest not.', 'என்னை நோக்கிக் கூப்பிடு, அப்பொழுது நான் உனக்கு உத்தரவு கொடுத்து, நீ அறியாததும் உனக்கு எட்டாததுமான பெரிய காரியங்களை உனக்கு அறிவிப்பேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('LAM.3.22', 'LAM', 3, 22, 'It is of the LORD’s mercies that we are not consumed, because his compassions fail not.', 'நாம் நிர்மூலமாகாதிருக்கிறது கர்த்தருடைய கிருபையே, அவருடைய இரக்கங்களுக்கு முடிவில்லை.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('LAM.3.23', 'LAM', 3, 23, 'They are new every morning: great is thy faithfulness.', 'அவைகள் காலைதோறும் புதியவைகள்; உமது உண்மை பெரிதாயிருக்கிறது.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('LAM.3.25', 'LAM', 3, 25, 'The LORD is good unto them that wait for him, to the soul that seeketh him.', 'தமக்குக் காத்திருக்கிறவர்களுக்கும் தம்மைத் தேடுகிற ஆத்துமாவுக்கும் கர்த்தர் நல்லவர்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('EZK.36.26', 'EZK', 36, 26, 'A new heart also will I give you, and a new spirit will I put within you: and I will take away the stony heart out of your flesh, and I will give you an heart of flesh.', 'உங்களுக்கு நவமான இருதயத்தைக் கொடுத்து, உங்கள் உள்ளத்திலே புதிதான ஆவியைக் கட்டளையிட்டு, கல்லான இருதயத்தை உங்கள் மாம்சத்திலிருந்து எடுத்துப்போட்டு சதையான இருதயத்தை உங்களுக்குக் கொடுப்பேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('DAN.2.20', 'DAN', 2, 20, 'Daniel answered and said, Blessed be the name of God for ever and ever: for wisdom and might are his:', 'பின்பு தானியேல் சொன்னது: தேவனுடைய நாமத்துக்கு என்றென்றைக்குமுள்ள சதாகாலங்களிலும் ஸ்தோத்திரமுண்டாவதாக; ஞானமும் வல்லமையும் அவருக்கே உரியது.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('DAN.12.3', 'DAN', 12, 3, 'And they that be wise shall shine as the brightness of the firmament; and they that turn many to righteousness as the stars for ever and ever.', 'ஞானவான்கள் ஆகாயமண்டலத்தின் ஒளியைப்போலவும், அநேகரை நீதிக்குட்படுத்துகிறவர்கள் நட்சத்திரங்களைப்போலவும் என்றென்றைக்குமுள்ள சதாகாலங்களிலும் பிரகாசிப்பார்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('HOS.6.3', 'HOS', 6, 3, 'Then shall we know, if we follow on to know the LORD: his going forth is prepared as the morning; and he shall come unto us as the rain, as the latter and former rain unto the earth.', 'அப்பொழுது நாம் அறிவடைந்து, கர்த்தரை அறியும்படி தொடர்ந்து போவோம்; அவருடைய புறப்படுதல் அருணோதயம்போல ஆயத்தமாயிருக்கிறது; அவர் மழையைப்போலவும், பூமியின்மேல் பெய்யும் முன்மாரி பின்மாரியைப்போலவும் நம்மிடத்தில் வருவார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JOL.2.13', 'JOL', 2, 13, 'And rend your heart, and not your garments, and turn unto the LORD your God: for he is gracious and merciful, slow to anger, and of great kindness, and repenteth him of the evil.', 'நீங்கள் உங்கள் வஸ்திரங்களையல்ல, உங்கள் இருதயங்களைக் கிழித்து, உங்கள் தேவனாகிய கர்த்தர் இடத்தில் திரும்புங்கள்; அவர் இரக்கமும், மனஉருக்கமும், நீடிய சாந்தமும், மிகுந்த கிருபையுமுள்ளவர்; அவர் தீங்குக்கு மனஸ்தாபப்படுகிறவருமாயிருக்கிறார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('AMO.5.24', 'AMO', 5, 24, 'But let judgment run down as waters, and righteousness as a mighty stream.', 'நியாயம் தண்ணீரைப்போலவும், நீதி வற்றாத நதியைப்போலவும் புரண்டுவரக்கடவது.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MIC.6.8', 'MIC', 6, 8, 'He hath shewed thee, O man, what is good; and what doth the LORD require of thee, but to do justly, and to love mercy, and to walk humbly with thy God?', 'மனுஷனே, நன்மை இன்னதென்று அவர் உனக்கு அறிவித்திருக்கிறார்; நியாயஞ்செய்து, இரக்கத்தைச் சிநேகித்து, உன் தேவனுக்கு முன்பாக மனத்தாழ்மையாய் நடப்பதை அல்லாமல் வேறே என்னத்தைக் கர்த்தர் உன்னிடத்தில் கேட்கிறார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('NAM.1.7', 'NAM', 1, 7, 'The LORD is good, a strong hold in the day of trouble; and he knoweth them that trust in him.', 'கர்த்தர் நல்லவர், இக்கட்டு நாளிலே அரணான கோட்டை; தம்மை நம்புகிறவர்களை அறிந்திருக்கிறார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('HAB.2.14', 'HAB', 2, 14, 'For the earth shall be filled with the knowledge of the glory of the LORD, as the waters cover the sea.', 'சமுத்திரம் ஜலத்தினால் நிறைந்திருக்கிறதுபோல், பூமி கர்த்தருடைய மகிமையை அறிகிற அறிவினால் நிறைந்திருக்கும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('HAB.3.18', 'HAB', 3, 18, 'Yet I will rejoice in the LORD, I will joy in the God of my salvation.', 'நான் கர்த்தருக்குள் மகிழ்ச்சியாயிருப்பேன், என் இரட்சிப்பின் தேவனுக்குள் களிகூருவேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ZEP.3.17', 'ZEP', 3, 17, 'The LORD thy God in the midst of thee is mighty; he will save, he will rejoice over thee with joy; he will rest in his love, he will joy over thee with singing.', 'உன் தேவனாகிய கர்த்தர் உன் நடுவில் இருக்கிறார்; அவர் வல்லமையுள்ளவர், அவர் இரட்சிப்பார்; அவர் உன்பேரில் சந்தோஷமாய் மகிழ்ந்து தம்முடைய அன்பினிமித்தம் அமர்ந்திருப்பார்; அவர் உன்பேரில் கெம்பீரமாய்க் களிகூருவார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('HAG.2.9', 'HAG', 2, 9, 'The glory of this latter house shall be greater than of the former, saith the LORD of hosts: and in this place will I give peace, saith the LORD of hosts.', 'முந்தின ஆலயத்தின் மகிமையைப் பார்க்கிலும், இந்தப் பிந்தின ஆலயத்தின் மகிமை பெரிதாயிருக்கும் என்று சேனைகளின் கர்த்தர் சொல்லுகிறார்; இவ்விடத்திலே சமாதானத்தைக் கட்டளையிடுவேன் என்று சேனைகளின் கர்த்தர் உரைக்கிறார் என்று சொல் என்றார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ZEC.4.6', 'ZEC', 4, 6, 'Then he answered and spake unto me, saying, This is the word of the LORD unto Zerubbabel, saying, Not by might, nor by power, but by my spirit, saith the LORD of hosts.', 'அப்பொழுது அவர்: செருபாபேலுக்குச் சொல்லப்படுகிற கர்த்தருடைய வார்த்தை என்னவென்றால், பலத்தினாலும் அல்ல, பராக்கிரமத்தினாலும் அல்ல, என்னுடைய ஆவியினாலேயே ஆகும் என்று சேனைகளின் கர்த்தர் சொல்லுகிறார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ZEC.12.1', 'ZEC', 12, 1, 'The burden of the word of the LORD for Israel, saith the LORD, which stretcheth forth the heavens, and layeth the foundation of the earth, and formeth the spirit of man within him.', 'இஸ்ரவேலைக்குறித்துக் கர்த்தர் சொன்ன வார்த்தையின் பாரம்; வானங்களை விரித்து, பூமியை அஸ்திபாரப்படுத்தி, மனுஷனுடைய ஆவியை அவனுக்குள் உண்டாக்குகிற கர்த்தர் சொல்லுகிறது என்னவென்றால்;')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MAL.3.6', 'MAL', 3, 6, 'For I am the LORD, I change not; therefore ye sons of Jacob are not consumed.', 'நான் கர்த்தர் நான் மாறாதவர்; ஆகையால் யாக்கோபின் புத்திரராகிய நீங்கள் நிர்மூலமாகவில்லை.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MAT.4.4', 'MAT', 4, 4, 'But he answered and said, It is written, Man shall not live by bread alone, but by every word that proceedeth out of the mouth of God.', 'அவர் பிரதியுத்தரமாக: மனுஷன் அப்பத்தினாலேமாத்திரமல்ல, தேவனுடைய வாயிலிருந்து புறப்படுகிற ஒவ்வொரு வார்த்தையினாலும் பிழைப்பான் என்று எழுதியிருக்கிறதே என்றார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MAT.4.19', 'MAT', 4, 19, 'And he saith unto them, Follow me, and I will make you fishers of men.', 'என் பின்னே வாருங்கள், உங்களை மனுஷரைப் பிடிக்கிறவர்களாக்குவேன் என்றார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MAT.5.3', 'MAT', 5, 3, 'Blessed are the poor in spirit: for theirs is the kingdom of heaven.', 'ஆவியில் எளிமையுள்ளவர்கள் பாக்கியவான்கள்; பரலோக ராஜ்யம் அவர்களுடையது.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MAT.5.6', 'MAT', 5, 6, 'Blessed are they which do hunger and thirst after righteousness: for they shall be filled.', 'நீதியின்மேல் பசிதாகமுள்ளவர்கள் பாக்கியவான்கள்; அவர்கள் திருப்தியடைவார்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MAT.5.8', 'MAT', 5, 8, 'Blessed are the pure in heart: for they shall see God.', 'இருதயத்தில் சுத்தமுள்ளவர்கள் பாக்கியவான்கள்; அவர்கள் தேவனைத் தரிசிப்பார்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MAT.5.9', 'MAT', 5, 9, 'Blessed are the peacemakers: for they shall be called the children of God.', 'சமாதானம் பண்ணுகிறவர்கள் பாக்கியவான்கள்; அவர்கள் தேவனுடைய புத்திரர் என்னப்படுவார்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MAT.5.14', 'MAT', 5, 14, 'Ye are the light of the world. A city that is set on an hill cannot be hid.', 'நீங்கள் உலகத்துக்கு வெளிச்சமாயிருக்கிறீர்கள்; மலையின் மேல் இருக்கிற பட்டணம் மறைந்திருக்கமாட்டாது.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MAT.5.16', 'MAT', 5, 16, 'Let your light so shine before men, that they may see your good works, and glorify your Father which is in heaven.', 'இவ்விதமாக மனுஷர் உங்கள் நற்கிரியைகளைக்கண்டு, பரலோகத்திலிருக்கிற உங்கள் பிதாவை மகிமைப்படுத்தும்படி, உங்கள் வெளிச்சம் அவர்கள் முன்பாகப் பிரகாசிக்கக்கடவது.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MAT.5.44', 'MAT', 5, 44, 'But I say unto you, Love your enemies, bless them that curse you, do good to them that hate you, and pray for them which despitefully use you, and persecute you;', 'நான் உங்களுக்குச் சொல்லுகிறேன், உங்கள் சத்துருக்களைச் சிநேகியுங்கள்; உங்களைச் சபிக்கிறவர்களை ஆசீர்வதியுங்கள்; உங்களைப் பகைக்கிறவர்களுக்கு நன்மை செய்யுங்கள்; உங்களை நிந்திக்கிறவர்களுக்காகவும் உங்களைத் துன்பப்படுத்துகிறவர்களுக்காகவும் ஜெபம் பண்ணுங்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MAT.6.9', 'MAT', 6, 9, 'After this manner therefore pray ye: Our Father which art in heaven, Hallowed be thy name.', 'நீங்கள் ஜெபம்பண்ணவேண்டிய விதமாவது; பரமண்டலங்களிலிருக்கிற எங்கள் பிதாவே, உம்முடைய நாமம் பரிசுத்தப்படுவதாக;')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MAT.6.21', 'MAT', 6, 21, 'For where your treasure is, there will your heart be also.', 'உங்கள் பொக்கிஷம் எங்கேயிருக்கிறதோ அங்கே உங்கள் இருதயமும் இருக்கும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MAT.6.33', 'MAT', 6, 33, 'But seek ye first the kingdom of God, and his righteousness; and all these things shall be added unto you.', 'முதலாவது தேவனுடைய ராஜ்யத்தையும் அவருடைய நீதியையும் தேடுங்கள்; அப்பொழுது இவைகளெல்லாம் உங்களுக்குக் கூடக் கொடுக்கப்படும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MAT.6.34', 'MAT', 6, 34, 'Take therefore no thought for the morrow: for the morrow shall take thought for the things of itself. Sufficient unto the day is the evil thereof.', 'ஆகையால் நாளைக்காகக் கவலைப்படாதிருங்கள்; நாளையத்தினம் தன்னுடையவைகளுக்காகக் கவலைப்படும். அந்தந்த நாளுக்கு அதினதின் பாடு போதும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MAT.7.7', 'MAT', 7, 7, 'Ask, and it shall be given you; seek, and ye shall find; knock, and it shall be opened unto you:', 'கேளுங்கள், அப்பொழுது உங்களுக்குக் கொடுக்கப்படும்; தேடுங்கள், அப்பொழுது கண்டடைவீர்கள்; தட்டுங்கள் அப்பொழுது உங்களுக்குத் திறக்கப்படும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MAT.7.12', 'MAT', 7, 12, 'Therefore all things whatsoever ye would that men should do to you, do ye even so to them: for this is the law and the prophets.', 'ஆதலால், மனுஷர் உங்களுக்கு எவைகளைச்செய்ய விரும்புகிறீர்களோ, அவைகளை நீங்களும் அவர்களுக்குச் செய்யுங்கள்; இதுவே நியாயப்பிரமாணமும் தீர்க்கதரிசனங்களுமாம்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MAT.9.37', 'MAT', 9, 37, 'Then saith he unto his disciples, The harvest truly is plenteous, but the labourers are few;', 'தம்முடைய சீஷர்களை நோக்கி: அறுப்பு மிகுதி வேலையாட்களோ கொஞ்சம்;')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MAT.11.28', 'MAT', 11, 28, 'Come unto me, all ye that labour and are heavy laden, and I will give you rest.', 'வருத்தப்பட்டுப் பாரஞ்சுமக்கிறவர்களே நீங்கள் எல்லாரும் என்னிடத்தில் வாருங்கள்; நான் உங்களுக்கு இளைப்பாருதல் தருவேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MAT.11.29', 'MAT', 11, 29, 'Take my yoke upon you, and learn of me; for I am meek and lowly in heart: and ye shall find rest unto your souls.', 'நான் சாந்தமும் மனத்தாழ்மையுமாயிருக்கிறேன்; என் நுகத்தை உங்கள்மேல் ஏற்றுக்கொண்டு, என்னிடத்தில் கற்றுக்கொள்ளுங்கள். அப்பொழுது, உங்கள் ஆத்துமாக்களுக்கு இளைப்பாறுதல் கிடைக்கும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MAT.16.24', 'MAT', 16, 24, 'Then said Jesus unto his disciples, If any man will come after me, let him deny himself, and take up his cross, and follow me.', 'அப்பொழுது, இயேசு தம்முடைய சீஷர்களை நோக்கி: ஒருவன் என்னைப் பின்பற்றி வர விரும்பினால், அவன் தன்னைத்தான் வெறுத்து, தன் சிலுவையை எடுத்துக்கொண்டு என்னைப் பின்பற்றக்கடவன்')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MAT.16.26', 'MAT', 16, 26, 'For what is a man profited, if he shall gain the whole world, and lose his own soul? or what shall a man give in exchange for his soul?', 'மனுஷன் உலகம் முழுவதையும் ஆதாயப்படுத்திக்கொண்டாலும், தன் ஜீவனை நஷ்டப்படுத்தினால் அவனுக்கு லாபம் என்ன? மனுஷன் தன் ஜீவனுக்கு ஈடாக என்னத்தைக் கொடுப்பான்?')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MAT.18.20', 'MAT', 18, 20, 'For where two or three are gathered together in my name, there am I in the midst of them.', 'ஏனெனில், இரண்டு பேராவது மூன்று பேராவது என் நாமத்தினாலே எங்கே கூடியிருக்கிறார்களோ, அங்கே அவர்கள் நடுவிலே இருக்கிறேன் என்றார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MAT.19.26', 'MAT', 19, 26, 'But Jesus beheld them, and said unto them, With men this is impossible; but with God all things are possible.', 'இயேசு, அவர்களைப் பார்த்து: மனுஷரால் இது கூடாததுதான்; தேவனாலே எல்லாம் கூடும் என்றார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MAT.22.37', 'MAT', 22, 37, 'Jesus said unto him, Thou shalt love the Lord thy God with all thy heart, and with all thy soul, and with all thy mind.', 'இயேசு அவனை நோக்கி: உன் தேவனாகிய கர்த்தரிடத்தில் உன் முழு இருதயத்தோடும், உன் முழு ஆத்துமாவோடும் உன் முழு மனதோடும் அன்புகூருவாயாக;')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MAT.24.35', 'MAT', 24, 35, 'Heaven and earth shall pass away, but my words shall not pass away.', 'வானமும் பூமியும் ஒழிந்துபோம், என் வார்த்தைகளோ ஒழிந்துபோவதில்லை.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MAT.28.19', 'MAT', 28, 19, 'Go ye therefore, and teach all nations, baptizing them in the name of the Father, and of the Son, and of the Holy Ghost:', 'ஆகையால், நீங்கள் புறப்பட்டுப்போய் சகல ஜாதிகளையும் சீஷராக்கி, பிதா குமாரன் பரிசுத்த ஆவியின் நாமத்திலே அவர்களுக்கு ஞானஸ்நானங்கொடுத்து,')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MAT.28.20', 'MAT', 28, 20, 'Teaching them to observe all things whatsoever I have commanded you: and, lo, I am with you alway, even unto the end of the world. Amen.', 'நான் உங்களுக்குக் கட்டளையிட்ட யாவையும் அவர்கள் கைக்கொள்ளும்படி அவர்களுக்கு உபதேசம் பண்ணுங்கள்; இதோ, உலகத்தின் முடிவுபரியந்தம் சகல நாட்களிலும் நான் உங்களுடனேகூட இருக்கிறேன் என்றார். ஆமென்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MRK.1.17', 'MRK', 1, 17, 'And Jesus said unto them, Come ye after me, and I will make you to become fishers of men.', 'இயேசு அவர்களை நோக்கி: என் பின்னே வாருங்கள், உங்களை மனுஷரைப் பிடிக்கிறவர்களாக்குவேன் என்றார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MRK.9.23', 'MRK', 9, 23, 'Jesus said unto him, If thou canst believe, all things are possible to him that believeth.', 'இயேசு அவனை நோக்கி: நீ விசுவாசிக்கக்கூடுமானால் ஆகும், விசுவாசிக்கிறவனுக்கு எல்லாம் கூடும் என்றார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MRK.10.27', 'MRK', 10, 27, 'And Jesus looking upon them saith, With men it is impossible, but not with God: for with God all things are possible.', 'இயேசு அவர்களைப் பார்த்து: மனுஷரால் இது கூடாததுதான்; தேவனால் இது கூடாததல்ல; தேவனாலே எல்லாம் கூடும் என்றார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MRK.10.45', 'MRK', 10, 45, 'For even the Son of man came not to be ministered unto, but to minister, and to give his life a ransom for many.', 'அப்படியே, மனுஷகுமாரனும் ஊழியங்கொள்ளும்படி வராமல், ஊழியஞ்செய்யுவும், அநேகரை மீட்கும்பொருளாகத் தம்முடைய ஜீவனைக்கொடுக்கவும் வந்தார் என்றார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MRK.11.24', 'MRK', 11, 24, 'Therefore I say unto you, What things soever ye desire, when ye pray, believe that ye receive them, and ye shall have them.', 'ஆதலால், நீங்கள் நின்று ஜெபம்பண்ணும்போது எவைகளை கேட்டுக்கொள்வீர்களோ, அவைகளைப் பெற்றுகொள்வோம் என்று விசுவாசியுங்கள், அப்பொழுது அவைகள் உங்களுக்கு உண்டாகும் என்று சொல்லுகிறேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MRK.12.31', 'MRK', 12, 31, 'And the second is like, namely this, Thou shalt love thy neighbour as thyself. There is none other commandment greater than these.', 'இதற்கு ஒப்பாயிருக்கிற இரண்டாம் கற்பனை என்னவென்றால்: உன்னிடத்தில் நீ அன்புகூருவதுபோல் பிறனிடத்திலும் அன்புகூருவாயாக என்பதே; இவைகளிலும் பெரிய கற்பனை வேறொன்றுமில்லை என்றார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('MRK.16.15', 'MRK', 16, 15, 'And he said unto them, Go ye into all the world, and preach the gospel to every creature.', 'பின்பு, அவர் அவர்களை நோக்கி: நீங்கள் உலகமெங்கும் போய், சர்வ சிருஷ்டிக்கும் சுவிசேஷத்தைப் பிரசங்கியுங்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('LUK.1.37', 'LUK', 1, 37, 'For with God nothing shall be impossible.', 'தேவனாலே கூடாத காரியம் ஒன்றுமில்லை என்றான்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('LUK.2.10', 'LUK', 2, 10, 'And the angel said unto them, Fear not: for, behold, I bring you good tidings of great joy, which shall be to all people.', 'தேவதூதன் அவர்களை நோக்கி: பயப்படாதிருங்கள்; இதோ, எல்லா ஜனத்துக்கும் மிகுந்த சந்தோஷத்தை உண்டாக்கும் நற்செய்தியை உங்களுக்கு அறிவிக்கிறேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('LUK.2.11', 'LUK', 2, 11, 'For unto you is born this day in the city of David a Saviour, which is Christ the Lord.', 'இன்று கர்த்தராகிய கிறிஸ்து என்னும் இரட்சகர் உங்களுக்குத் தாவீதின் ஊரிலே பிறந்திருக்கிறார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('LUK.2.14', 'LUK', 2, 14, 'Glory to God in the highest, and on earth peace, good will toward men.', 'உன்னதத்திலிருக்கிற தேவனுக்கு மகிமையும், பூமியிலே சமாதானமும், மனுஷர்மேல் பிரியமும் உண்டாவதாக என்று சொல்லி, தேவனைத் துதித்தார்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('LUK.6.31', 'LUK', 6, 31, 'And as ye would that men should do to you, do ye also to them likewise.', 'மனுஷர் உங்களுக்கு எப்படிச் செய்யவேண்டுமென்று விரும்புகிறீர்களோ, அப்படியே நீங்களும் அவர்களுக்குச் செய்யுங்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('LUK.9.23', 'LUK', 9, 23, 'And he said to them all, If any man will come after me, let him deny himself, and take up his cross daily, and follow me.', 'பின்பு அவர் எல்லாரையும் நோக்கி: ஒருவன் என் பின்னே வர விரும்பினால், அவன் தன்னைத் தான் வெறுத்து, தன் சிலுவையை அனுதினமும் எடுத்துக்கொண்டு, என்னைப் பின்பற்றக்கடவன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('LUK.11.9', 'LUK', 11, 9, 'And I say unto you, Ask, and it shall be given you; seek, and ye shall find; knock, and it shall be opened unto you.', 'மேலும் நான் உங்களுக்குச் சொல்லுகிறதாவது: கேளுங்கள், அப்பொழுது உங்களுக்குக் கொடுக்கப்படும்; தேடுங்கள், அப்பொழுது கண்டடைவீர்கள்; தட்டுங்கள், அப்பொழுது உங்களுக்குத் திறக்கப்டும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('LUK.12.34', 'LUK', 12, 34, 'For where your treasure is, there will your heart be also.', 'உங்கள் பொக்கிஷம் எங்கே இருக்கிறதோ அங்கே உங்கள் இருதயமும் இருக்கும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('LUK.15.7', 'LUK', 15, 7, 'I say unto you, that likewise joy shall be in heaven over one sinner that repenteth, more than over ninety and nine just persons, which need no repentance.', 'அதுபோல, மனந்திரும்ப அவசியமில்லாத தொண்ணூற்றொன்பது நீதிமான்களைக்குறித்துச் சந்தோஷம் உண்டாகிறதைப் பார்க்கிலும் மனந்திரும்புகிற ஒரே பாவியினிமித்தம் பரலோகத்தில் மிகுந்த சந்தோஷம் உண்டாயிருக்கும் என்று உங்களுக்குச் சொல்லுகிறேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('LUK.19.10', 'LUK', 19, 10, 'For the Son of man is come to seek and to save that which was lost.', 'இழந்துபோனதைத் தேடவும் இரட்சிக்கவுமே மனுஷகுமாரன் வந்திருக்கிறார் என்றார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JHN.1.1', 'JHN', 1, 1, 'In the beginning was the Word, and the Word was with God, and the Word was God.', 'ஆதியிலே வார்த்தை இருந்தது, அந்த வார்த்தை தேவனிடத்திலிருந்தது, அந்த வார்த்தை தேவனாயிருந்தது.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JHN.1.12', 'JHN', 1, 12, 'But as many as received him, to them gave he power to become the sons of God, even to them that believe on his name:', 'அவருடைய நாமத்தின்மேல் விசுவாசமுள்ளவர்களாய் அவரை ஏற்றுக்கொண்டவர்கள் எத்தனைபேர்களோ, அத்தனை பேர்களும் தேவனுடைய பிள்ளைகளாகும்படி, அவர்களுக்கு அதிகாரங்கொடுத்தார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JHN.1.14', 'JHN', 1, 14, 'And the Word was made flesh, and dwelt among us, (and we beheld his glory, the glory as of the only begotten of the Father,) full of grace and truth.', 'அந்த வார்த்தை மாம்சமாகி, கிருபையினாலும் சத்தியத்தினாலும் நிறைந்தவராய், நமக்குள்ளே வாசம்பண்ணினார்; அவருடைய மகிமையைக் கண்டோம்; அது பிதாவுக்கு ஒரே பேறானவருடைய மகிமைக்கு ஏற்ற மகிமையாகவே இருந்தது.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JHN.3.16', 'JHN', 3, 16, 'For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life.', 'தேவன், தம்முடைய ஒரேபேறான குமாரனை விசுவாசிக்கிறவன் எவனோ அவன் கெட்டுப்போகாமல் நித்தியஜீவனை அடையும்படிக்கு, அவரைத் தந்தருளி, இவ்வளவாய் உலகத்தில் அன்புகூர்ந்தார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JHN.3.17', 'JHN', 3, 17, 'For God sent not his Son into the world to condemn the world; but that the world through him might be saved.', 'உலகத்தை ஆக்கினைக்குள்ளாகத் தீர்க்கும்படி தேவன் தம்முடைய குமாரனை உலகத்தில் அனுப்பாமல், அவராலே உலகம் இரட்சிக்கப்படுவதற்காகவே அவரை அனுப்பினார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JHN.4.24', 'JHN', 4, 24, 'God is a Spirit: and they that worship him must worship him in spirit and in truth.', 'தேவன் ஆவியாயிருக்கிறார், அவரைத் தொழுதுகொள்ளுகிறவர்கள் ஆவியோடும் உண்மையோடும் அவரைத் தொழுதுகொள்ளவேண்டும் என்றார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JHN.6.35', 'JHN', 6, 35, 'And Jesus said unto them, I am the bread of life: he that cometh to me shall never hunger; and he that believeth on me shall never thirst.', 'இயேசு அவர்களை நோக்கி: ஜீவ அப்பம் நானே, என்னிடத்தில் வருகிறவன் ஒருக்காலும் பசியடையான், என்னிடத்தில் விசுவாசமாயிருக்கிறவன் ஒருக்காலும் தாகமடையான்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JHN.8.12', 'JHN', 8, 12, 'Then spake Jesus again unto them, saying, I am the light of the world: he that followeth me shall not walk in darkness, but shall have the light of life.', 'மறுபடியும் இயேசு ஜனங்களை நோக்கி: நான் உலகத்திற்கு ஒளியாயிருக்கிறேன், என்னைப் பின்பற்றுகிறவன் இருளிலே நடவாமல் ஜீவஒளியை அடைந்திருப்பான் என்றார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JHN.8.32', 'JHN', 8, 32, 'And ye shall know the truth, and the truth shall make you free.', 'சத்தியத்தையும் அறிவீர்கள், சத்தியம் உங்களை விடுதலையாக்கும் என்றார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JHN.10.10', 'JHN', 10, 10, 'The thief cometh not, but for to steal, and to kill, and to destroy: I am come that they might have life, and that they might have it more abundantly.', 'திருடன் திருடவும் கொல்லவும் அழிக்கவும் வருகிறானேயன்றி வேறொன்றுக்கும் வரான். நானோ அவைகளுக்கு ஜீவன் உண்டாயிருக்கவும், அது பரிபூரணப்படவும் வந்தேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JHN.10.11', 'JHN', 10, 11, 'I am the good shepherd: the good shepherd giveth his life for the sheep.', 'நானே நல்ல மேய்ப்பன்: நல்லமேய்ப்பன் ஆடுகளுக்குக்காகத் தன் ஜீவனைக் கொடுக்கிறான்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JHN.10.28', 'JHN', 10, 28, 'And I give unto them eternal life; and they shall never perish, neither shall any man pluck them out of my hand.', 'நான் அவைகளுக்கு நித்தியஜீவனைக் கொடுக்கிறேன்; அவைகள் ஒருக்காலும் கெட்டுப்போவதில்லை, ஒருவனும் அவைகளை என் கையிலிருந்து பறித்துக்கொள்வதுமில்லை.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JHN.11.25', 'JHN', 11, 25, 'Jesus said unto her, I am the resurrection, and the life: he that believeth in me, though he were dead, yet shall he live:', 'இயேசு அவளை நோக்கி: நானே உயிர்த்தெழுதலும் ஜீவனுமாயிருக்கிறேன், என்னை விசுவாசிக்கிறவன் மரித்தாலும் பிழைப்பான்;')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JHN.11.35', 'JHN', 11, 35, 'Jesus wept.', 'இயேசு கண்ணீர் விட்டார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JHN.13.34', 'JHN', 13, 34, 'A new commandment I give unto you, That ye love one another; as I have loved you, that ye also love one another.', 'நீங்கள் ஒருவரிலொருவர் அன்பாயிருங்கள்; நான் உங்களில் அன்பாயிருந்ததுபோல நீங்களும் ஒருவரிலொருவர் அன்பாயிருங்கள் என்கிற புதிதான கட்டளையை உங்களுக்குக் கொடுக்கிறேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JHN.13.35', 'JHN', 13, 35, 'By this shall all men know that ye are my disciples, if ye have love one to another.', 'நீங்கள் ஒருவரிலொருவர் அன்புள்ளவர்களாயிருந்தால், அதினால் நீங்கள் என்னுடைய சீஷர்களென்று எல்லாரும் அறிந்துகொள்வார்கள் என்றார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JHN.14.1', 'JHN', 14, 1, 'Let not your heart be troubled: ye believe in God, believe also in me.', 'உங்கள் இருதயம் கலங்காதிருப்பதாக; தேவனிடத்தில் விசுவாசமாயிருங்கள், என்னிடத்திலும் விசுவாசமாயிருங்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JHN.14.6', 'JHN', 14, 6, 'Jesus saith unto him, I am the way, the truth, and the life: no man cometh unto the Father, but by me.', 'அதற்கு இயேசு: நானே வழியும் சத்தியமும் ஜீவனுமாயிருக்கிறேன்; என்னாலேயல்லாமல் ஒருவனும் பிதாவினிடத்தில் வரான்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JHN.14.15', 'JHN', 14, 15, 'If ye love me, keep my commandments.', 'நீங்கள் என்னிடத்தில் அன்பாயிருந்தால் என் கற்பனைகளைக் கைக்கொள்ளுங்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JHN.14.27', 'JHN', 14, 27, 'Peace I leave with you, my peace I give unto you: not as the world giveth, give I unto you. Let not your heart be troubled, neither let it be afraid.', 'சமாதானத்தை உங்களுக்கு வைத்துப்போகிறேன், என்னுடைய சமாதானத்தையே உங்களுக்குக் கொடுக்கிறேன்; உலகம் கொடுக்கிறபிரகாரம் நான் உங்களுக்குக் கொடுக்கிறதில்லை. உங்கள் இருதயம் கலங்காமலும் பயப்படாமலுமிருப்பதாக.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JHN.15.5', 'JHN', 15, 5, 'I am the vine, ye are the branches: He that abideth in me, and I in him, the same bringeth forth much fruit: for without me ye can do nothing.', 'நானே திராட்சச்செடி, நீங்கள் கொடிகள். ஒருவன் என்னிலும் நான் அவனிலும் நிலைத்திருந்தால், அவன் மிகுந்த கனிகளைக் கொடுப்பான்; என்னையல்லாமல் உங்களால் ஒன்றும் செய்யக்கூடாது.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JHN.15.12', 'JHN', 15, 12, 'This is my commandment, That ye love one another, as I have loved you.', 'நான் உங்களில் அன்பாயிருக்கிறதுபோல நீங்களும் ஒருவரிலொருவர் அன்பாயிருக்கவேண்டுமென்பதே என்னுடைய கற்பனையாயிருக்கிறது.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JHN.15.13', 'JHN', 15, 13, 'Greater love hath no man than this, that a man lay down his life for his friends.', 'ஒருவன் தன் சிநேகிதருக்காகத் தன் ஜீவனைக் கொடுக்கிற அன்பிலும் அதிகமான அன்பு ஒருவரிடத்திலுமில்லை.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JHN.16.33', 'JHN', 16, 33, 'These things I have spoken unto you, that in me ye might have peace. In the world ye shall have tribulation: but be of good cheer; I have overcome the world.', 'என்னிடத்தில் உங்களுக்குச் சமாதானம் உண்டாயிருக்கும் பொருட்டு இவைகளை உங்களுக்குச் சொன்னேன். உலகத்தில் உங்களுக்கு உபத்திரவம் உண்டு, ஆனாலும் திடன்கொள்ளுங்கள்; நான் உலகத்தை ஜெயித்தேன் என்றார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JHN.20.29', 'JHN', 20, 29, 'Jesus saith unto him, Thomas, because thou hast seen me, thou hast believed: blessed are they that have not seen, and yet have believed.', 'அதற்கு இயேசு: தோமாவே, நீ என்னைக் கண்டதினாலே விசுவாசித்தாய், காணாதிருந்தும் விசுவாசிக்கிறவர்கள் பாக்கியவான்கள் என்றார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ACT.2.38', 'ACT', 2, 38, 'Then Peter said unto them, Repent, and be baptized every one of you in the name of Jesus Christ for the remission of sins, and ye shall receive the gift of the Holy Ghost.', 'பேதுரு அவர்களை நோக்கி: நீங்கள் மனந்திரும்பி, ஒவ்வொருவரும் பாவமன்னிப்புக்கென்று இயேசுகிறிஸ்துவின் நாமத்தினாலே ஞானஸ்நானம் பெற்றுக்கொள்ளுங்கள், அப்பொழுது பரிசுத்த ஆவியின் வரத்தைப் பெறுவீர்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ACT.4.12', 'ACT', 4, 12, 'Neither is there salvation in any other: for there is none other name under heaven given among men, whereby we must be saved.', 'அவராலேயன்றி வேறொருவராலும் இரட்சிப்பு இல்லை; நாம் இரட்சிக்கப்படும்படிக்கு வானத்தின் கீழெங்கும், மனுஷர்களுக்குள்ளே அவருடைய நாமமேயல்லாமல் வேறொரு நாமம் கட்டளையிடப்படவும் இல்லை என்றான்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ACT.16.31', 'ACT', 16, 31, 'And they said, Believe on the Lord Jesus Christ, and thou shalt be saved, and thy house.', 'அதற்கு அவர்கள்: கர்த்தராகிய இயேசுகிறிஸ்துவை விசுவாசி, அப்பொழுது நீயும் உன் வீட்டாரும் இரட்சிக்கப்படுவீர்கள் என்று சொல்லி,')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ACT.17.28', 'ACT', 17, 28, 'For in him we live, and move, and have our being; as certain also of your own poets have said, For we are also his offspring.', 'ஏனெனில் அவருக்குள் நாம் பிழைக்கிறோம், அசைகிறோம், இருக்கிறோம்; அப்படியே உங்கள் புலவர்களிலும் சிலர்: நாம் அவருடைய சந்ததியார் என்று சொல்லியிருக்கிறார்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ACT.20.35', 'ACT', 20, 35, 'I have shewed you all things, how that so labouring ye ought to support the weak, and to remember the words of the Lord Jesus, how he said, It is more blessed to give than to receive.', 'இப்படிப் பிரயாசப்பட்டு, பலவீனரைத் தாங்கவும், வாங்குகிறதைப்பார்க்கிலும் கொடுக்கிறதே பாக்கியம் என்று கர்த்தராகிய இயேசு சொன்ன வார்த்தைகளை நினைக்கவும் வேண்டுமென்று எல்லாவிதத்திலேயும் உங்களுக்குக் காண்பித்தேன் என்றான்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ROM.1.16', 'ROM', 1, 16, 'For I am not ashamed of the gospel of Christ: for it is the power of God unto salvation to every one that believeth; to the Jew first, and also to the Greek.', 'கிறிஸ்துவின் சுவிசேஷத்தைக் குறித்து நான் வெட்கப்படேன்; முன்பு யூதரிலும் பின்பு கிரேக்கரிலும் விசுவாசிக்கிறவனெவனோ அவனுக்கு இரட்சிப்பு உண்டாவதற்கு அது தேவபெலனாயிருக்கிறது.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ROM.1.20', 'ROM', 1, 20, 'For the invisible things of him from the creation of the world are clearly seen, being understood by the things that are made, even his eternal power and Godhead; so that they are without excuse:', 'எப்படியென்றால், காணப்படாதவைகளாகிய அவருடைய நித்திய வல்லமை தேவத்துவம் என்பவைகள், உண்டாக்கப்பட்டிருக்கிறவைகளினாலே, உலகமுண்டானதுமுதற்கொண்டு, தெளிவாய்க் காணப்படும்; ஆதலால் அவர்கள் போக்குச்சொல்ல இடமில்லை.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ROM.3.23', 'ROM', 3, 23, 'For all have sinned, and come short of the glory of God;', 'எல்லாரும் பாவஞ்செய்து, தேவமகிமையற்றவர்களாகி,')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ROM.5.1', 'ROM', 5, 1, 'Therefore being justified by faith, we have peace with God through our Lord Jesus Christ:', 'இவ்விதமாக, நாம் விசுவாசத்தினாலே நீதிமான்களாக்கப்பட்டிருக்கிறபடியால், நம்முடைய கர்த்தராகிய இயேசுகிறிஸ்துமூலமாய் தேவனிடத்தில் சமாதானம் பெற்றிருக்கிறோம்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ROM.5.8', 'ROM', 5, 8, 'But God commendeth his love toward us, in that, while we were yet sinners, Christ died for us.', 'நாம் பாவிகளாயிருக்கையில் கிறிஸ்து நமக்காக மரித்ததினாலே, தேவன் நம்மேல் வைத்த தமது அன்பை விளங்கப்பண்ணுகிறார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ROM.6.23', 'ROM', 6, 23, 'For the wages of sin is death; but the gift of God is eternal life through Jesus Christ our Lord.', 'பாவத்தின் சம்பளம் மரணம்; தேவனுடைய கிருபைவரமோ நம்முடைய கர்த்தராகிய இயேசுகிறிஸ்துவினால் உண்டான நித்தியஜீவன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ROM.8.1', 'ROM', 8, 1, 'There is therefore now no condemnation to them which are in Christ Jesus, who walk not after the flesh, but after the Spirit.', 'ஆனபடியால், கிறிஸ்து இயேசுவுக்குட்பட்டவர்களாயிருந்து, மாம்சத்தின்படி நடவாமல் ஆவியின்படியே நடக்கிறவர்களுக்கு ஆக்கினைத்தீர்ப்பில்லை.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ROM.8.18', 'ROM', 8, 18, 'For I reckon that the sufferings of this present time are not worthy to be compared with the glory which shall be revealed in us.', 'ஆதலால் இக்காலத்துப் பாடுகள் இனி நம்மிடத்தில் வெளிப்படும் மகிமைக்கு ஒப்பிடத்தக்கவைகள் அல்லவென்று எண்ணுகிறேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ROM.8.28', 'ROM', 8, 28, 'And we know that all things work together for good to them that love God, to them who are the called according to his purpose.', 'அன்றியும், அவருடைய தீர்மானத்தின்படி அழைக்கப்பட்டவர்களாய் தேவனிடத்தில் அன்புகூருகிறவர்களுக்குச் சகலமும் நன்மைக்கு ஏதுவாக நடக்கிறதென்று அறிந்திருக்கிறோம்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ROM.8.31', 'ROM', 8, 31, 'What shall we then say to these things? If God be for us, who can be against us?', 'இவைகளைக்குறித்து நாம் என்னசொல்லுவோம்? தேவன் நம்முடைய பட்சத்திலிருந்தால் நமக்கு விரோதமாயிருப்பவன் யார்?')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ROM.8.38', 'ROM', 8, 38, 'For I am persuaded, that neither death, nor life, nor angels, nor principalities, nor powers, nor things present, nor things to come,', 'மரணமானாலும், ஜீவனானாலும், தேவதூதர்களானாலும், அதிகாரங்களானாலும், வல்லமைகளானாலும், நிகழ்காரியங்களானாலும், வருங்காரியங்களானாலும்,')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ROM.10.9', 'ROM', 10, 9, 'That if thou shalt confess with thy mouth the Lord Jesus, and shalt believe in thine heart that God hath raised him from the dead, thou shalt be saved.', 'என்னவென்றால், கர்த்தராகிய இயேசுவை நீ உன் வாயினாலே அறிக்கையிட்டு, தேவன் அவரை மரித்தோரிலிருந்து எழுப்பினாரென்று உன் இருதயத்திலே விசுவாசித்தால் இரட்சிக்கப்படுவாய்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ROM.10.13', 'ROM', 10, 13, 'For whosoever shall call upon the name of the Lord shall be saved.', 'ஆதலால் கர்த்தருடைய நாமத்தைத் தொழுதுகொள்ளுகிற எவனும் இரட்சிக்கப்படுவான்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ROM.10.17', 'ROM', 10, 17, 'So then faith cometh by hearing, and hearing by the word of God.', 'ஆதலால் விசுவாசம் கேள்வியினாலே வரும், கேள்வி தேவனுடைய வசனத்தினாலே வரும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ROM.12.1', 'ROM', 12, 1, 'I beseech you therefore, brethren, by the mercies of God, that ye present your bodies a living sacrifice, holy, acceptable unto God, which is your reasonable service.', 'அப்படியிருக்க, சகோதரரே, நீங்கள் உங்கள் சரீரங்களைப் பரிசுத்தமும் தேவனுக்குப் பிரியமுமான ஜீவபலியாக ஒப்புக்கொடுக்கவேண்டுமென்று, தேவனுடைய இரக்கங்களை முன்னிட்டு உங்களை வேண்டிக்கொள்ளுகிறேன்; இதுவே நீங்கள் செய்யத்தக்க புத்தியுள்ள ஆராதனை.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ROM.12.2', 'ROM', 12, 2, 'And be not conformed to this world: but be ye transformed by the renewing of your mind, that ye may prove what is that good, and acceptable, and perfect, will of God.', 'நீங்கள் இந்தப் பிரபஞ்சத்திற்கு ஒத்த வேஷந்தரியாமல், தேவனுடைய நன்மையும் பிரியமும் பரிபூரணமுமான சித்தம் இன்னதென்று பகுத்தறியத்தக்கதாக, உங்கள் மனம் புதிதாகிறதினாலே மறுரூபமாகுங்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ROM.12.12', 'ROM', 12, 12, 'Rejoicing in hope; patient in tribulation; continuing instant in prayer;', 'நம்பிக்கையிலே சந்தோஷமாயிருங்கள்; உபத்திரவத்திலே பொறுமையாயிருங்கள்; ஜெபத்திலே உறுதியாய்த் தரித்திருங்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ROM.12.21', 'ROM', 12, 21, 'Be not overcome of evil, but overcome evil with good.', 'நீ தீமையினாலே வெல்லப்படாமல், தீமையை நன்மையினாலே வெல்லு.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('ROM.15.13', 'ROM', 15, 13, 'Now the God of hope fill you with all joy and peace in believing, that ye may abound in hope, through the power of the Holy Ghost.', 'பரிசுத்த ஆவியின் பலத்தினாலே உங்களுக்கு நம்பிக்கை பெருகும்படிக்கு, நம்பிக்கையின் தேவன் விசுவாசத்தினால் உண்டாகும் எல்லாவித சந்தோஷத்தினாலும் சமாதானத்தினாலும் உங்களை நிரப்புவாராக.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('1CO.2.9', '1CO', 2, 9, 'But as it is written, Eye hath not seen, nor ear heard, neither have entered into the heart of man, the things which God hath prepared for them that love him.', 'எழுதியிருக்கிறபடி: தேவன் தம்மில் அன்புகூருகிறவர்களுக்கு ஆயத்தம்பண்ணினவைகளைக் கண் காணவுமில்லை, காதுகேட்கவுமில்லை, அவைகள் மனுஷனுடைய இருதயத்தில் தோன்றவுமில்லை;')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('1CO.6.19', '1CO', 6, 19, 'What? know ye not that your body is the temple of the Holy Ghost which is in you, which ye have of God, and ye are not your own?', 'உங்கள் சரீரமானது நீங்கள் தேவனாலே பெற்றும் உங்களில் தங்கியும் இருக்கிற பரிசுத்த ஆவியினுடைய ஆலயமாயிருக்கிறதென்றும், நீங்கள் உங்களுடையவர்களல்லவென்றும் அறியீர்களா?')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('1CO.10.31', '1CO', 10, 31, 'Whether therefore ye eat, or drink, or whatsoever ye do, do all to the glory of God.', 'ஆகையால் நீங்கள் புசித்தாலும், குடித்தாலும், எதைச் செய்தாலும், எல்லாவற்றையும் தேவனுடைய மகிமைக்கென்று செய்யுங்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('1CO.13.4', '1CO', 13, 4, 'Charity suffereth long, and is kind; charity envieth not; charity vaunteth not itself, is not puffed up,', 'அன்பு நீடிய சாந்தமும் தயவுமுள்ளது; அன்புக்குப் பொறாமையில்லை; அன்பு தன்னைப் புகழாது, இறுமாப்பாயிராது,')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('1CO.13.13', '1CO', 13, 13, 'And now abideth faith, hope, charity, these three; but the greatest of these is charity.', 'இப்பொழுது விசுவாசம், நம்பிக்கை, அன்பு இம்மூன்றும் நிலைத்திருக்கிறது; இவைகளில் அன்பே பெரியது.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('1CO.15.45', '1CO', 15, 45, 'And so it is written, The first man Adam was made a living soul; the last Adam was made a quickening spirit.', 'அந்தப்படியே முந்தின மனுஷனாகிய ஆதாம் ஜீவாத்துமாவானான் என்றெழுதியிருக்கிறது, பிந்தின ஆதாம் உயிர்ப்பிக்கிற ஆவியானார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('1CO.15.57', '1CO', 15, 57, 'But thanks be to God, which giveth us the victory through our Lord Jesus Christ.', 'நம்முடைய கர்த்தராகிய இயேசுகிறிஸ்துவினாலே நமக்கு ஜெயங்கொடுக்கிற தேவனுக்கு ஸ்தோத்திரம்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('1CO.15.58', '1CO', 15, 58, 'Therefore, my beloved brethren, be ye stedfast, unmoveable, always abounding in the work of the Lord, forasmuch as ye know that your labour is not in vain in the Lord.', 'ஆகையால், எனக்குப் பிரியமான சகோதரரே, கர்த்தருக்குள் நீங்கள் படுகிற பிரயாசம் விருதாவாயிராதென்று அறிந்து, நீங்கள் உறுதிப்பட்டவர்களாயும், அசையாதவர்களாயும், கர்த்தருடைய கிரியையிலே எப்பொழுதும் பெருகுகிறவர்களாயும் இருப்பீர்களாக.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('1CO.16.14', '1CO', 16, 14, 'Let all your things be done with charity.', 'உங்கள் காரியங்களெல்லாம் அன்போடே செய்யப்படக்கடவது.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('2CO.4.16', '2CO', 4, 16, 'For which cause we faint not; but though our outward man perish, yet the inward man is renewed day by day.', 'ஆனபடியினாலே நாங்கள் சோர்ந்துபோகிறதில்லை; எங்கள் புறம்பான மனுஷனானது அழிந்தும், உள்ளான மனுஷனானது நாளுக்குநாள் புதிதாக்கப்படுகிறது.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('2CO.4.18', '2CO', 4, 18, 'While we look not at the things which are seen, but at the things which are not seen: for the things which are seen are temporal; but the things which are not seen are eternal.', 'ஏனெனில், காணப்படுகிறவைகள் அநித்தியமானவைகள், காணப்படாதவைகளோ நித்தியமானவைகள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('2CO.5.7', '2CO', 5, 7, '(For we walk by faith, not by sight:)', 'இந்தத் தேகத்தில் குடியிருக்கையில் கர்த்தரிடத்தில் குடியிராதவர்களாயிருக்கிறோமென்று அறிந்தும், எப்பொழுதும் தைரியமாயிருக்கிறோம்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('2CO.5.17', '2CO', 5, 17, 'Therefore if any man be in Christ, he is a new creature: old things are passed away; behold, all things are become new.', 'இப்படியிருக்க, ஒருவன் கிறிஸ்துவுக்குள்ளிருந்தால் புதுச்சிருஷ்டியாயிருக்கிறான்; பழையவைகள் ஒழிந்துபோயின, எல்லாம் புதிதாயின.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('2CO.9.7', '2CO', 9, 7, 'Every man according as he purposeth in his heart, so let him give; not grudgingly, or of necessity: for God loveth a cheerful giver.', 'அவனவன் விசனமாயுமல்ல, கட்டாயமாயுமல்ல, தன் மனதில் நியமித்தபடியே கொடுக்கக்கடவன்; உற்சாகமாய்க் கொடுக்கிறவனிடத்தில் தேவன் பிரியமாயிருக்கிறார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('GAL.5.1', 'GAL', 5, 1, 'Stand fast therefore in the liberty wherewith Christ hath made us free, and be not entangled again with the yoke of bondage.', 'ஆனபடியினாலே, நீங்கள் மறுபடியும் அடிமைத்தனத்தின் நுகத்துக்குட்படாமல், கிறிஸ்து நமக்கு உண்டாக்கின சுயாதீன நிலைமையிலே நிலைகொண்டிருங்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('GAL.5.22', 'GAL', 5, 22, 'But the fruit of the Spirit is love, joy, peace, longsuffering, gentleness, goodness, faith,', 'ஆவியின் கனியோ, அன்பு, சந்தோஷம், சமாதானம், நீடியபொறுமை, தயவு, நற்குணம், விசுவாசம்,')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('GAL.6.2', 'GAL', 6, 2, 'Bear ye one another’s burdens, and so fulfil the law of Christ.', 'ஒருவர் பாரத்தை ஒருவர் சுமந்து, அப்படியே கிறிஸ்துவினுடைய பிரமாணத்தை நிறைவேற்றுங்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('GAL.6.9', 'GAL', 6, 9, 'And let us not be weary in well doing: for in due season we shall reap, if we faint not.', 'நன்மைசெய்கிறதில் சோர்ந்துபோகாமல் இருப்போமாக; நாம் தளர்ந்துபோகாதிருந்தால் ஏற்றகாலத்தில் அறுப்போம்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('EPH.2.8', 'EPH', 2, 8, 'For by grace are ye saved through faith; and that not of yourselves: it is the gift of God:', 'கிருபையினாலே விசுவாசத்தைக்கொண்டு இரட்சிக்கப்பட்டீர்கள்; இது உங்களால் உண்டானதல்ல, இது தேவனுடைய ஈவு;')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('EPH.2.10', 'EPH', 2, 10, 'For we are his workmanship, created in Christ Jesus unto good works, which God hath before ordained that we should walk in them.', 'ஏனெனில், நற்கிரியைகளைச் செய்கிறதற்கு நாம் கிறிஸ்து இயேசுவுக்குள் சிருஷ்டிக்கப்பட்டு, தேவனுடைய செய்கையாயிருக்கிறோம்; அவைகளில் நாம் நடக்கும்படி அவர் முன்னதாக அவைகளை ஆயத்தம்பண்ணியிருக்கிறார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('EPH.3.20', 'EPH', 3, 20, 'Now unto him that is able to do exceeding abundantly above all that we ask or think, according to the power that worketh in us,', 'நாம் வேண்டிக்கொள்ளுகிறதற்கும் நினைக்கிறதற்கும் மிகவும் அதிகமாய் நமக்குள்ளே கிரியைசெய்கிற வல்லமையின்படியே, நமக்குச் செய்ய வல்லவராகிய அவருக்கு,')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('EPH.4.2', 'EPH', 4, 2, 'With all lowliness and meekness, with longsuffering, forbearing one another in love;', 'மிகுந்த மனத்தாழ்மையும் சாந்தமும் நீடிய பொறுமையும் உடையவர்களாய், அன்பினால் ஒருவரையொருவர் தாங்கி,')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('EPH.4.32', 'EPH', 4, 32, 'And be ye kind one to another, tenderhearted, forgiving one another, even as God for Christ’s sake hath forgiven you.', 'ஒருவருக்கொருவர் தயவாயும் மனஉருக்கமாயும் இருந்து, கிறிஸ்துவுக்குள் தேவன் உங்களுக்கு மன்னித்ததுபோல, நீங்களும் ஒருவருக்காருவர் மன்னியுங்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('EPH.6.10', 'EPH', 6, 10, 'Finally, my brethren, be strong in the Lord, and in the power of his might.', 'கடைசியாக, என் சகோதரரே, கர்த்தரிலும் அவருடைய சத்துவத்தின் வல்லமையிலும் பலப்படுங்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('EPH.6.11', 'EPH', 6, 11, 'Put on the whole armour of God, that ye may be able to stand against the wiles of the devil.', 'நீங்கள் பிசாசின் தந்திரங்களோடு எதிர்த்துநிற்கத் திராணியுள்ளவர்களாகும்படி, தேவனுடைய சர்வாயுதவர்க்கத்தையும் தரித்துக்கொள்ளுங்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PHP.1.6', 'PHP', 1, 6, 'Being confident of this very thing, that he which hath begun a good work in you will perform it until the day of Jesus Christ:', 'நான் உங்களை நினைக்கிறபொழுது என் தேவனை ஸ்தோத்திரிக்கிறேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PHP.1.21', 'PHP', 1, 21, 'For to me to live is Christ, and to die is gain.', 'கிறிஸ்து எனக்கு ஜீவன், சாவு எனக்கு ஆதாயம்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PHP.2.3', 'PHP', 2, 3, 'Let nothing be done through strife or vainglory; but in lowliness of mind let each esteem other better than themselves.', 'ஒன்றையும் வாதினாலாவது வீண்பெருமையினாலாவது செய்யாமல், மனத்தாழ்மையினாலே ஒருவரையொருவர் தங்களிலும் மேன்மையானவர்களாக எண்ணக்கடவீர்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PHP.3.14', 'PHP', 3, 14, 'I press toward the mark for the prize of the high calling of God in Christ Jesus.', 'கிறிஸ்து இயேசுவுக்குள் தேவன் அழைத்த பரம அழைப்பின் பந்தயப்பொருளுக்காக இலக்கை நோக்கித் தொடருகிறேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PHP.4.4', 'PHP', 4, 4, 'Rejoice in the Lord alway: and again I say, Rejoice.', 'கர்த்தருக்குள் எப்பொழுதும் சந்தோஷமாயிருங்கள்; சந்தோஷமாயிருங்கள் என்று மறுபடியும் சொல்லுகிறேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PHP.4.6', 'PHP', 4, 6, 'Be careful for nothing; but in every thing by prayer and supplication with thanksgiving let your requests be made known unto God.', 'நீங்கள் ஒன்றுக்குங் கவலைப்படாமல், எல்லாவற்றையுங்குறித்து உங்கள் விண்ணப்பங்களை ஸ்தோத்திரத்தோடே கூடிய ஜெபத்தினாலும் வேண்டுதலினாலும் தேவனுக்குத் தெரியப்படுத்துங்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PHP.4.7', 'PHP', 4, 7, 'And the peace of God, which passeth all understanding, shall keep your hearts and minds through Christ Jesus.', 'அப்பொழுது, எல்லாப் புத்திக்கும்மேலான தேவசமாதானம் உங்கள் இருதயங்களையும் உங்கள் சிந்தைகளையும் கிறிஸ்து இயேசுவுக்குள்ளாகக் காத்துக்கொள்ளும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PHP.4.13', 'PHP', 4, 13, 'I can do all things through Christ which strengtheneth me.', 'என்னைப் பெலப்படுத்துகிற கிறிஸ்துவினாலே எல்லாவற்றையுஞ்செய்ய எனக்குப் பெலனுண்டு.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PHP.4.19', 'PHP', 4, 19, 'But my God shall supply all your need according to his riches in glory by Christ Jesus.', 'என் தேவன் தம்முடைய ஐசுவரியத்தின்படி உங்கள் குறைவையெல்லாங் கிறிஸ்து இயேசுவுக்குள் மகிமையிலே நிறைவாக்குவார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('COL.3.2', 'COL', 3, 2, 'Set your affection on things above, not on things on the earth.', 'பூமியிலுள்ளவைகளையல்ல, மேலானவைகளையே நாடுங்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('COL.3.13', 'COL', 3, 13, 'Forbearing one another, and forgiving one another, if any man have a quarrel against any: even as Christ forgave you, so also do ye.', 'ஒருவரையொருவர் தாங்கி, ஒருவர்பேரில் ஒருவருக்குக் குறைபாடு உண்டானால், கிறிஸ்து உங்களுக்கு மன்னித்ததுபோல, ஒருவருக்கொருவர் மன்னியுங்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('COL.3.15', 'COL', 3, 15, 'And let the peace of God rule in your hearts, to the which also ye are called in one body; and be ye thankful.', 'தேவசமாதானம் உங்கள் இருதயங்களில் ஆளக்கடவது, இதற்கென்றே நீங்கள் ஒரே சரீரமாக அழைக்கப்பட்டீர்கள்; நன்றியறிதலுள்ளவர்களாயுமிருங்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('COL.3.23', 'COL', 3, 23, 'And whatsoever ye do, do it heartily, as to the Lord, and not unto men;', 'நீங்கள் கர்த்தராகிய கிறிஸ்துவைச் சேவிக்கிறதினாலே, சுதந்தரமாகிய பலனைக் கர்த்தராலே பெறுவீர்களென்று அறிந்து,')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('1TH.5.16', '1TH', 5, 16, 'Rejoice evermore.', 'எப்பொழுதும் சந்தோஷமாயிருங்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('1TH.5.17', '1TH', 5, 17, 'Pray without ceasing.', 'இடைவிடாமல் ஜெபம்பண்ணுங்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('1TH.5.18', '1TH', 5, 18, 'In every thing give thanks: for this is the will of God in Christ Jesus concerning you.', 'எல்லாவற்றிலேயும் ஸ்தோத்திரஞ்செய்யுங்கள்; அப்படிச் செய்வதே கிறிஸ்து இயேசுவுக்குள் உங்களைக்குறித்துத் தேவனுடைய சித்தமாயிருக்கிறது.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('2TH.3.3', '2TH', 3, 3, 'But the Lord is faithful, who shall stablish you, and keep you from evil.', 'கர்த்தரோ உண்மையுள்ளவர், அவர் உங்களை ஸ்திரப்படுத்தி, தீமையினின்று விலக்கிக் காத்துக்கொள்ளுவார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('1TI.4.12', '1TI', 4, 12, 'Let no man despise thy youth; but be thou an example of the believers, in word, in conversation, in charity, in spirit, in faith, in purity.', 'உன் இளமையைக்குறித்து ஒருவனும் உன்னை அசட்டைபண்ணாதபடிக்கு, நீ வார்த்தையிலும், நடக்கையிலும், அன்பிலும், ஆவியிலும், விசுவாசத்திலும், கற்பிலும், விசுவாசிகளுக்கு மாதிரியாயிரு.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('1TI.6.6', '1TI', 6, 6, 'But godliness with contentment is great gain.', 'போதுமென்கிற மனதுடனே கூடிய தேவபக்தியே மிகுந்த ஆதாயம்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('2TI.1.7', '2TI', 1, 7, 'For God hath not given us the spirit of fear; but of power, and of love, and of a sound mind.', 'தேவன் நமக்குப் பயமுள்ள ஆவியைக் கொடாமல், பலமும் அன்பும் தெளிந்த புத்தியுமுள்ள ஆவியையே கொடுத்திருக்கிறார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('2TI.2.15', '2TI', 2, 15, 'Study to shew thyself approved unto God, a workman that needeth not to be ashamed, rightly dividing the word of truth.', 'சீர்கேடான வீண்பேச்சுகளுக்கு விலகியிரு; அவைகளால் (கள்ளப்போதகர்களான) அவர்கள் அதிக அவபக்தியுள்ளவர்களாவார்கள்;')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('2TI.3.16', '2TI', 3, 16, 'All scripture is given by inspiration of God, and is profitable for doctrine, for reproof, for correction, for instruction in righteousness:', 'வேதவாக்கியங்களெல்லாம் தேவஆவியினால் அருளப்பட்டிருக்கிறது; தேவனுடைய மனுஷன் தேறினவனாகவும், எந்த நற்கிரியையுஞ் செய்யத் தகுதியுள்ளவனாகவும் இருக்கும்படி,')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('2TI.4.7', '2TI', 4, 7, 'I have fought a good fight, I have finished my course, I have kept the faith:', 'நல்ல போராட்டத்தைப் போராடினேன், ஓட்டத்தை முடித்தேன், விசுவாசத்தைக் காத்துக்கொண்டேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('TIT.2.11', 'TIT', 2, 11, 'For the grace of God that bringeth salvation hath appeared to all men,', 'ஏனெனில் எல்லா மனுஷருக்கும் இரட்சிப்பை அளிக்கத்தக்க தேவகிருபையானது பிரசன்னமாகி,')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('PHM.1.6', 'PHM', 1, 6, 'That the communication of thy faith may become effectual by the acknowledging of every good thing which is in you in Christ Jesus.', 'உங்களிலுள்ள சகல நன்மைகளும் தெரியப்படுகிறதினாலே உம்முடைய விசுவாசத்தின் அந்நியோந்நியம் கிறிஸ்து இயேசுவுக்காகப் பயன்படவேண்டுமென்று வேண்டுதல் செய்கிறேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('HEB.4.16', 'HEB', 4, 16, 'Let us therefore come boldly unto the throne of grace, that we may obtain mercy, and find grace to help in time of need.', 'ஆதலால், நாம் இரக்கத்தைப் பெறவும், ஏற்ற சமயத்தில் சகாயஞ்செய்யுங்கிருபையை அடையவும், தைரியமாய்க் கிருபாசனத்தண்டையிலே சேரக்கடவோம்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('HEB.10.23', 'HEB', 10, 23, 'Let us hold fast the profession of our faith without wavering; (for he is faithful that promised;)', 'அல்லாமலும், நம்முடைய நம்பிக்கையை அறிக்கையிடுகிறதில் அசைவில்லாமல் உறுதியாயிருக்கக்கடவோம்; வாக்குத்தத்தம்பண்ணினவர் உண்மையுள்ளவராயிருக்கிறாரே.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('HEB.11.1', 'HEB', 11, 1, 'Now faith is the substance of things hoped for, the evidence of things not seen.', 'விசுவாசமானது நம்பப்படுகிறவைகளின் உறுதியும், காணப்படாதவைகளின் நிச்சயமுமாயிருக்கிறது.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('HEB.11.6', 'HEB', 11, 6, 'But without faith it is impossible to please him: for he that cometh to God must believe that he is, and that he is a rewarder of them that diligently seek him.', 'விசுவாசமில்லாமல் தேவனுக்குப் பிரியமாயிருப்பது கூடாதகாரியம்; ஏனென்றால், தேவனிடத்தில் சேருகிறவன் அவர் உண்டென்றும், அவர் தம்மைத்தேடுகிறவர்களுக்குப் பலன் அளிக்கிறவரென்றும் விசுவாசிக்கவேண்டும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('HEB.13.5', 'HEB', 13, 5, 'Let your conversation be without covetousness; and be content with such things as ye have: for he hath said, I will never leave thee, nor forsake thee.', 'நீங்கள் பண ஆசையில்லாதவர்களாய் நடந்து, உங்களுக்கு இருக்கிறவைகள் போதுமென்று எண்ணுங்கள்; நான் உன்னைவிட்டு விலகுவதுமில்லை, உன்னைக் கைவிடுவதுமில்லை என்று அவர் சொல்லியிருக்கிறாரே.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('HEB.13.8', 'HEB', 13, 8, 'Jesus Christ the same yesterday, and to day, and for ever.', 'இயேசுகிறிஸ்து நேற்றும் இன்றும் என்றும் மாறாதவராயிருக்கிறார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JAS.1.2', 'JAS', 1, 2, 'My brethren, count it all joy when ye fall into divers temptations;', 'என் சகோதரரே, நீங்கள் பலவிதமான சோதனைகளில் அகப்படும்போது,')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JAS.1.5', 'JAS', 1, 5, 'If any of you lack wisdom, let him ask of God, that giveth to all men liberally, and upbraideth not; and it shall be given him.', 'உங்களில் ஒருவன் ஞானத்தில் குறைவுள்ளவனாயிருந்தால், யாவருக்கும் சம்பூரணமாய்க் கொடுக்கிறவரும் ஒருவரையும் கடிந்துகொள்ளாதவருமாகிய தேவனிடத்தில் கேட்கக்கடவன், அப்பொழுது அவனுக்குக் கொடுக்கப்படும்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JAS.1.17', 'JAS', 1, 17, 'Every good gift and every perfect gift is from above, and cometh down from the Father of lights, with whom is no variableness, neither shadow of turning.', 'நன்மையான எந்த ஈவும் பூரணமான எந்த வரமும் பரத்திலிருந்துண்டாகி, சோதிகளின் பிதாவினிடத்திலிருந்து இறங்கிவருகிறது; அவரிடத்தில் யாதொரு மாறுதலும் யாதொரு வேற்றுமையின் நிழலுமில்லை.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JAS.1.22', 'JAS', 1, 22, 'But be ye doers of the word, and not hearers only, deceiving your own selves.', 'அல்லாமலும், நீங்கள் உங்களை வஞ்சியாதபடிக்குத் திருவசனத்தைக் கேட்கிறவர்களாய் மாத்திரமல்ல, அதின்படி செய்கிறவர்களாயும் இருங்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JAS.4.7', 'JAS', 4, 7, 'Submit yourselves therefore to God. Resist the devil, and he will flee from you.', 'ஆகையால், தேவனுக்குக் கீழ்ப்படிந்திருங்கள்; பிசாசுக்கு எதிர்த்து நில்லுங்கள், அப்பொழுது அவன் உங்களைவிட்டு ஓடிப்போவான்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JAS.4.8', 'JAS', 4, 8, 'Draw nigh to God, and he will draw nigh to you. Cleanse your hands, ye sinners; and purify your hearts, ye double minded.', 'தேவனிடத்தில் சேருங்கள், அப்பொழுது அவர் உங்களிடத்தில் சேருவார். பாவிகளே, உங்கள் கைகளைச் சுத்திகரியுங்கள்; இருமனமுள்ளவர்களே, உங்கள் இருதயங்களைப் பரிசுத்தமாக்குங்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JAS.5.16', 'JAS', 5, 16, 'Confess your faults one to another, and pray one for another, that ye may be healed. The effectual fervent prayer of a righteous man availeth much.', 'நீங்கள் சொஸ்தமடையும்படிக்கு, உங்கள் குற்றங்களை ஒருவருக்கொருவர் அறிக்கையிட்டு, ஒருவருக்காக ஒருவர் ஜெபம்பண்ணுங்கள். நீதிமான் செய்யும் ஊக்கமான வேண்டுதல் மிகவும் பெலனுள்ளதாயிருக்கிறது.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('1PE.3.15', '1PE', 3, 15, 'But sanctify the Lord God in your hearts: and be ready always to give an answer to every man that asketh you a reason of the hope that is in you with meekness and fear:', 'கர்த்தராகிய தேவனை உங்கள் இருதயங்களில் பரிசுத்தம்பண்ணுங்கள்; உங்களிலிருக்கிற நம்பிக்கையைக்குறித்து உங்களிடத்தில் விசாரித்துக் கேட்கிற யாவருக்கும் சாந்தத்தோடும் வணக்கத்தோடும் உத்தரவுசொல்ல எப்பொழுதும் ஆயத்தமாயிருங்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('1PE.5.7', '1PE', 5, 7, 'Casting all your care upon him; for he careth for you.', 'அவர் உங்களை விசாரிக்கிறவரானபடியால், உங்கள் கவலைகளையெல்லாம் அவர்மேல் வைத்துவிடுங்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('2PE.3.9', '2PE', 3, 9, 'The Lord is not slack concerning his promise, as some men count slackness; but is longsuffering to us-ward, not willing that any should perish, but that all should come to repentance.', 'தாமதிக்கிறார் என்று சிலர் எண்ணுகிறபடி கர்த்தர் தமது வாக்குத்தத்தத்தைக்குறித்துத் தாமதமாயிராமல்; ஒருவரும் கெட்டுப்போகாமல் எல்லாரும் மனந்திரும்பவேண்டுமென்று விரும்பி, நம்மேல் நீடிய பொறுமையுள்ளவராயிருக்கிறார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('2PE.3.18', '2PE', 3, 18, 'But grow in grace, and in the knowledge of our Lord and Saviour Jesus Christ. To him be glory both now and for ever. Amen.', 'நம்முடைய கர்த்தரும் இரட்சகருமாகிய இயேசுகிறிஸ்துவின் கிருபையிலும் அவரை அறிகிற அறிவிலும் வளருங்கள். அவருக்கு இப்பொழுதும் என்றென்றைக்கும் மகிமையுண்டாவதாக. ஆமென்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('1JN.1.9', '1JN', 1, 9, 'If we confess our sins, he is faithful and just to forgive us our sins, and to cleanse us from all unrighteousness.', 'நம்முடைய பாவங்களை நாம் அறிக்கையிட்டால், பாவங்களை நமக்கு மன்னித்து எல்லா அநியாயத்தையும் நீக்கி நம்மைச் சுத்திகரிப்பதற்கு அவர் உண்மையும் நீதியும் உள்ளவராயிருக்கிறார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('1JN.3.1', '1JN', 3, 1, 'Behold, what manner of love the Father hath bestowed upon us, that we should be called the sons of God: therefore the world knoweth us not, because it knew him not.', 'நாம் தேவனுடைய பிள்ளைகளென்று அழைக்கப்படுவதினாலே பிதாவானவர் நமக்குப் பாராட்டின அன்பு எவ்வளவு பெரிதென்று பாருங்கள்; உலகம் அவரை அறியாதபடியினாலே நம்மையும் அறியவில்லை.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('1JN.3.18', '1JN', 3, 18, 'My little children, let us not love in word, neither in tongue; but in deed and in truth.', 'என் பிள்ளைகளே, வசனத்தினாலும், நாவினாலுமல்ல, கிரியையினாலும் உண்மையினாலும் அன்புகூரக்கடவோம்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('1JN.4.4', '1JN', 4, 4, 'Ye are of God, little children, and have overcome them: because greater is he that is in you, than he that is in the world.', 'பிள்ளைகளே, நீங்கள் தேவனாலுண்டாயிருந்து, அவர்களை ஜெயித்தீர்கள்; ஏனெனில் உலகத்திலிருக்கிறவனிலும் உங்களிலிருக்கிறவர் பெரியவர்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('1JN.4.8', '1JN', 4, 8, 'He that loveth not knoweth not God; for God is love.', 'அன்பில்லாதவன் தேவனை அறியான், தேவன் அன்பாகவே இருக்கிறார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('1JN.4.18', '1JN', 4, 18, 'There is no fear in love; but perfect love casteth out fear: because fear hath torment. He that feareth is not made perfect in love.', 'அன்பிலே பயமில்லை; பூரண அன்பு பயத்தைப் புறம்பே தள்ளும்; பயமானது வேதனையுள்ளது, பயப்படுகிறவன் அன்பில் பூரணப்பட்டவன் அல்ல.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('1JN.4.19', '1JN', 4, 19, 'We love him, because he first loved us.', 'அவர் முந்தி நம்மிடத்தில் அன்புகூர்ந்தபடியால் நாமும் அவரிடத்தில் அன்புகூருகிறோம்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('1JN.5.14', '1JN', 5, 14, 'And this is the confidence that we have in him, that, if we ask any thing according to his will, he heareth us:', 'நாம் எதையாகிலும் அவருடைய சித்தத்தின்படிகேட்டால், அவர் நமக்குச் செவிகொடுக்கிறாரென்பதே அவரைப் பற்றி நாம் கொண்டிருக்கிற தைரியம்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('3JN.1.2', '3JN', 1, 2, 'Beloved, I wish above all things that thou mayest prosper and be in health, even as thy soul prospereth.', 'பிரியமானவனே, உன் ஆத்துமா வாழ்கிறதுபோல நீ எல்லாவற்றிலும் வாழ்ந்து சுகமாயிருக்கும்படி வேண்டுகிறேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('JUD.1.24', 'JUD', 1, 24, 'Now unto him that is able to keep you from falling, and to present you faultless before the presence of his glory with exceeding joy,', 'வழுவாதபடி உங்களைக் காக்கவும், தமது மகிமையுள்ள சந்நிதானத்திலே மிகுந்த மகிழ்ச்சியோடே உங்களை மாசற்றவர்களாய் நிறுத்தவும் வல்லமையுள்ளவரும்,')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('REV.1.8', 'REV', 1, 8, 'I am Alpha and Omega, the beginning and the ending, saith the Lord, which is, and which was, and which is to come, the Almighty.', 'இருக்கிறவரும் இருந்தவரும் இனிவருகிறவருமாகிய சர்வவல்லமையுள்ள கர்த்தர்: நான் அல்பாவும், ஓமெகாவும் ஆதியும் அந்தமுமாயிருக்கிறேன் என்று திருவுளம்பற்றுகிறார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('REV.3.20', 'REV', 3, 20, 'Behold, I stand at the door, and knock: if any man hear my voice, and open the door, I will come in to him, and will sup with him, and he with me.', 'இதோ, வாசற்படியிலே நின்று தட்டுகிறேன்; ஒருவன் என் சத்தத்தைக்கேட்டு, கதவைத் திறந்தால், அவனிடத்தில் நான் பிரவேசித்து, அவனோடே போஜனம்பண்ணுவேன், அவனும் என்னோடே போஜனம்பண்ணுவான்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('REV.4.11', 'REV', 4, 11, 'Thou art worthy, O Lord, to receive glory and honour and power: for thou hast created all things, and for thy pleasure they are and were created.', 'கர்த்தாவே, தேவரீர், மகிமையையும் கனத்தையும் வல்லமையையும் பெற்றுக்கொள்ளுகிறதற்குப் பாத்திரராயிருக்கிறீர், நீரே சகலத்தையும் சிருஷ்டித்தீர், உம்முடைய சித்தத்தினாலே அவைகள் உண்டாயிருக்கிறவைகளும் சிருஷ்டிக்கப்பட்டவைகளுமாயிருக்கிறது என்றார்கள்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('REV.21.4', 'REV', 21, 4, 'And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away.', 'அவர்களுடைய கண்ணீர் யாவையும் தேவன் துடைப்பார்; இனி மரணமுமில்லை, துக்கமுமில்லை, அலறுதலுமில்லை, வருத்தமுமில்லை; முந்தினவைகள் ஒழிந்துபோயின என்று விளம்பினது.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('REV.21.5', 'REV', 21, 5, 'And he that sat upon the throne said, Behold, I make all things new. And he said unto me, Write: for these words are true and faithful.', 'சிங்காசனத்தின்மேல் வீற்றிருந்தவர்: இதோ, நான் சகலத்தையும் புதிதாக்குகிறேன் என்றார். பின்னும், அவர்: இந்த வசனங்கள் சத்தியமும் உண்மையுமானவைகள், இவைகளை எழுது என்றார்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();
insert into verses (id, book_code, chapter, verse, en, ta) values ('REV.22.13', 'REV', 22, 13, 'I am Alpha and Omega, the beginning and the end, the first and the last.', 'நான் அல்பாவும் ஓமெகாவும், ஆதியும் அந்தமும், முந்தினவரும் பிந்தினவருமாயிருக்கிறேன்.')
  on conflict (id) do update set en = excluded.en, ta = excluded.ta, updated_at = now();

-- reading sources
insert into reading_sources (id, author, title) values ('mystery', '{"en":"Witness Lee","ta":"விட்னஸ் லீ"}'::jsonb, 'The Mystery of Human Life') on conflict (id) do update set author = excluded.author, title = excluded.title;
insert into reading_sources (id, author, title) values ('economy', '{"en":"Witness Lee","ta":"விட்னஸ் லீ"}'::jsonb, 'The Economy of God') on conflict (id) do update set author = excluded.author, title = excluded.title;
insert into reading_sources (id, author, title) values ('gospel-of-god', '{"en":"Watchman Nee","ta":"வாட்ச்மேன் நீ"}'::jsonb, 'The Gospel of God') on conflict (id) do update set author = excluded.author, title = excluded.title;
insert into reading_sources (id, author, title) values ('normal', '{"en":"Watchman Nee","ta":"வாட்ச்மேன் நீ"}'::jsonb, 'The Normal Christian Life') on conflict (id) do update set author = excluded.author, title = excluded.title;
insert into reading_sources (id, author, title) values ('new-believers', '{"en":"Watchman Nee","ta":"வாட்ச்மேன் நீ"}'::jsonb, 'Messages for Building Up New Believers') on conflict (id) do update set author = excluded.author, title = excluded.title;

-- gospel steps (positions cleared first so re-ordering works)
update gospel_steps set position = position + 1000;
insert into gospel_steps (id, position, icon, horse, title, body, prayer, next, verse_ids) values ('purpose', 1, 'compass', 'white', '{"en":"Human life has a purpose","ta":"மனித வாழ்க்கைக்கு ஒரு நோக்கம் உண்டு"}'::jsonb, '{"en":"Everyone asks, “Why am I here?” The universe is not an accident, and neither are you. The Bible says God has placed something in the human heart that this world can never fill.","ta":"“நான் ஏன் இங்கே இருக்கிறேன்?” என்று ஒவ்வொருவரும் கேட்கிறோம். இந்த அண்டமும் நீங்களும் தற்செயலாக உண்டானவர்கள் அல்ல. இந்த உலகத்தால் ஒருபோதும் நிரப்ப முடியாத ஒன்றை தேவன் மனித இருதயத்தில் வைத்திருக்கிறார் என்று வேதம் சொல்லுகிறது."}'::jsonb, null, null, array['ECC.3.11']::text[])
  on conflict (id) do update set position = excluded.position, icon = excluded.icon, horse = excluded.horse, title = excluded.title, body = excluded.body, prayer = excluded.prayer, next = excluded.next, verse_ids = excluded.verse_ids;
insert into gospel_steps (id, position, icon, horse, title, body, prayer, next, verse_ids) values ('god', 2, 'globe', 'white', '{"en":"There is a God","ta":"தேவன் இருக்கிறார்"}'::jsonb, '{"en":"A watch points to a watchmaker. In the same way, the order of the heavens, the earth and life itself point to a Creator — to God''s eternal power and divine nature.","ta":"ஒரு கடிகாரம் அதைச் செய்தவரைக் காட்டுகிறது. அதுபோலவே, வானம், பூமி, ஜீவன் இவைகளின் ஒழுங்கு ஒரு படைப்பாளரைக் காட்டுகிறது — தேவனுடைய நித்திய வல்லமையையும் தேவத்துவத்தையும் காட்டுகிறது."}'::jsonb, null, null, array['ROM.1.20']::text[])
  on conflict (id) do update set position = excluded.position, icon = excluded.icon, horse = excluded.horse, title = excluded.title, body = excluded.body, prayer = excluded.prayer, next = excluded.next, verse_ids = excluded.verse_ids;
insert into gospel_steps (id, position, icon, horse, title, body, prayer, next, verse_ids) values ('spirit', 3, 'hand', 'pale', '{"en":"You were made to contain God","ta":"தேவனைக் கொள்ளும்படி நீங்கள் உண்டாக்கப்பட்டீர்கள்"}'::jsonb, '{"en":"God made man in His image with three parts: a body to contact the world, a soul to be himself, and a deep human spirit to contact and receive God. Like a glove made for a hand, we were made to hold God. Without Him there is an empty place inside that nothing else fits.","ta":"தேவன் மனுஷனைத் தம்முடைய சாயலாக மூன்று பகுதிகளோடு உண்டாக்கினார்: உலகத்தைத் தொடர்புகொள்ள ஒரு சரீரம், தானாக இருக்க ஒரு ஆத்துமா, தேவனைத் தொடர்புகொண்டு ஏற்றுக்கொள்ள ஒரு ஆழமான மனித ஆவி. கைக்காகச் செய்யப்பட்ட கையுறையைப்போல, தேவனைக் கொள்ளும்படியே நாம் உண்டாக்கப்பட்டோம். அவர் இல்லாமல், வேறெதுவும் பொருந்தாத ஒரு வெறுமை நமக்குள் இருக்கிறது."}'::jsonb, null, null, array['GEN.1.26','ZEC.12.1','PRO.20.27','JHN.4.24']::text[])
  on conflict (id) do update set position = excluded.position, icon = excluded.icon, horse = excluded.horse, title = excluded.title, body = excluded.body, prayer = excluded.prayer, next = excluded.next, verse_ids = excluded.verse_ids;
insert into gospel_steps (id, position, icon, horse, title, body, prayer, next, verse_ids) values ('fall', 4, 'unlink', 'red', '{"en":"Sin came in","ta":"பாவம் உள்ளே வந்தது"}'::jsonb, '{"en":"Instead of receiving God, man listened to Satan, and sin entered. Sin separated us from God, deadened our spirit and brought death. Every one of us has sinned and falls short of the glory of God.","ta":"தேவனை ஏற்றுக்கொள்வதற்குப் பதிலாக, மனுஷன் சாத்தானுக்குச் செவிகொடுத்தான்; பாவம் உள்ளே வந்தது. பாவம் நம்மை தேவனிடமிருந்து பிரித்து, நம்முடைய ஆவியைச் செத்ததாக்கி, மரணத்தைக் கொண்டுவந்தது. நாம் ஒவ்வொருவரும் பாவஞ்செய்து தேவமகிமையற்றவர்களானோம்."}'::jsonb, null, null, array['ROM.3.23','ROM.6.23']::text[])
  on conflict (id) do update set position = excluded.position, icon = excluded.icon, horse = excluded.horse, title = excluded.title, body = excluded.body, prayer = excluded.prayer, next = excluded.next, verse_ids = excluded.verse_ids;
insert into gospel_steps (id, position, icon, horse, title, body, prayer, next, verse_ids) values ('incarnation', 5, 'baby', 'white', '{"en":"God became a man","ta":"தேவன் மனுஷனானார்"}'::jsonb, '{"en":"God did not give up on us. He Himself became a man — Jesus Christ — and lived among us a perfect human life, full of grace and truth.","ta":"தேவன் நம்மைக் கைவிடவில்லை. அவரே ஒரு மனுஷனானார் — இயேசு கிறிஸ்து — கிருபையினாலும் சத்தியத்தினாலும் நிறைந்தவராய் நம் நடுவே பரிபூரணமான மனித வாழ்க்கை வாழ்ந்தார்."}'::jsonb, null, null, array['JHN.1.14']::text[])
  on conflict (id) do update set position = excluded.position, icon = excluded.icon, horse = excluded.horse, title = excluded.title, body = excluded.body, prayer = excluded.prayer, next = excluded.next, verse_ids = excluded.verse_ids;
insert into gospel_steps (id, position, icon, horse, title, body, prayer, next, verse_ids) values ('cross', 6, 'cross', 'red', '{"en":"He died for us and rose again","ta":"அவர் நமக்காக மரித்து உயிர்த்தெழுந்தார்"}'::jsonb, '{"en":"On the cross Jesus died in our place, bearing the penalty of our sins. On the third day He rose, and in resurrection He became the life-giving Spirit — so now He can come into everyone who receives Him.","ta":"சிலுவையில் இயேசு நமக்குப் பதிலாக மரித்து, நம்முடைய பாவங்களின் தண்டனையைச் சுமந்தார். மூன்றாம் நாளில் அவர் உயிர்த்தெழுந்தார்; உயிர்த்தெழுதலில் உயிர்ப்பிக்கிற ஆவியானார் — ஆகையால் இப்பொழுது அவரை ஏற்றுக்கொள்ளுகிற ஒவ்வொருவருக்குள்ளும் அவர் வர முடியும்."}'::jsonb, null, null, array['JHN.3.16','1CO.15.45']::text[])
  on conflict (id) do update set position = excluded.position, icon = excluded.icon, horse = excluded.horse, title = excluded.title, body = excluded.body, prayer = excluded.prayer, next = excluded.next, verse_ids = excluded.verse_ids;
insert into gospel_steps (id, position, icon, horse, title, body, prayer, next, verse_ids) values ('receive', 7, 'door', 'pale', '{"en":"Receive Him by calling on His name","ta":"அவருடைய நாமத்தைத் தொழுதுகொண்டு அவரை ஏற்றுக்கொள்ளுங்கள்"}'::jsonb, '{"en":"Salvation is a free gift, not a reward for good works. Turn your heart to Him, believe that He died and rose for you, and call on His name: “O Lord Jesus!” Whoever calls on the name of the Lord shall be saved.","ta":"இரட்சிப்பு இலவசமான ஈவு; நற்கிரியைகளுக்கான கூலி அல்ல. உங்கள் இருதயத்தை அவரிடம் திருப்புங்கள்; அவர் உங்களுக்காக மரித்து உயிர்த்தெழுந்தார் என்று விசுவாசியுங்கள்; “ஓ கர்த்தராகிய இயேசுவே!” என்று அவருடைய நாமத்தைத் தொழுதுகொள்ளுங்கள். கர்த்தருடைய நாமத்தைத் தொழுதுகொள்ளுகிறவன் எவனோ அவன் இரட்சிக்கப்படுவான்."}'::jsonb, null, null, array['ROM.10.13','JHN.1.12','REV.3.20']::text[])
  on conflict (id) do update set position = excluded.position, icon = excluded.icon, horse = excluded.horse, title = excluded.title, body = excluded.body, prayer = excluded.prayer, next = excluded.next, verse_ids = excluded.verse_ids;
insert into gospel_steps (id, position, icon, horse, title, body, prayer, next, verse_ids) values ('pray', 8, 'heart-handshake', 'pale', '{"en":"A simple prayer","ta":"ஒரு எளிய ஜெபம்"}'::jsonb, '{"en":"You can pray simply, in your own words. For example:","ta":"உங்கள் சொந்த வார்த்தைகளில் எளிமையாக ஜெபிக்கலாம். உதாரணமாக:"}'::jsonb, '{"en":"Lord Jesus, I need You. I am a sinner. Thank You for dying on the cross for me and rising again. I open my heart and receive You as my Saviour and my life. Come into me now. O Lord Jesus! Amen.","ta":"கர்த்தராகிய இயேசுவே, எனக்கு நீர் தேவை. நான் ஒரு பாவி. எனக்காகச் சிலுவையில் மரித்து உயிர்த்தெழுந்ததற்காக உமக்கு நன்றி. என் இருதயத்தைத் திறந்து, உம்மை என் இரட்சகராகவும் என் ஜீவனாகவும் ஏற்றுக்கொள்ளுகிறேன். இப்பொழுதே எனக்குள் வாரும். ஓ கர்த்தராகிய இயேசுவே! ஆமென்."}'::jsonb, '{"en":"Tell a Christian friend, read the Gospel of John, and keep calling on His name every day.","ta":"ஒரு கிறிஸ்தவ நண்பரிடம் சொல்லுங்கள், யோவான் சுவிசேஷத்தை வாசியுங்கள், ஒவ்வொரு நாளும் அவருடைய நாமத்தைத் தொழுதுகொள்ளுங்கள்."}'::jsonb, array['EPH.2.8']::text[])
  on conflict (id) do update set position = excluded.position, icon = excluded.icon, horse = excluded.horse, title = excluded.title, body = excluded.body, prayer = excluded.prayer, next = excluded.next, verse_ids = excluded.verse_ids;

-- faqs
update faqs set position = position + 1000;
insert into faqs (id, position, q, a, verse_ids, reading_ids) values ('exists', 1, '{"en":"Does God really exist?","ta":"தேவன் உண்மையிலேயே இருக்கிறாரா?"}'::jsonb, '{"en":"Look at the universe, at your own body, at your conscience. Things this ordered and purposeful do not come from nothing. The Bible says God''s invisible power and divine nature are clearly seen through what He has made — and your human spirit, deep within, already senses that He is there.","ta":"அண்டத்தையும், உங்கள் சொந்த சரீரத்தையும், உங்கள் மனசாட்சியையும் பாருங்கள். இவ்வளவு ஒழுங்கும் நோக்கமும் உள்ளவை ஒன்றுமில்லாமையிலிருந்து வருவதில்லை. தேவனுடைய காணப்படாத வல்லமையும் தேவத்துவமும் அவர் உண்டாக்கினவைகளினாலே தெளிவாய்க் காணப்படும் என்று வேதம் சொல்லுகிறது — உங்களுக்குள் ஆழத்திலுள்ள மனித ஆவியும் அவர் இருக்கிறார் என்று ஏற்கனவே உணருகிறது."}'::jsonb, array['ROM.1.20']::text[], array['gospel-of-god','mystery']::text[])
  on conflict (id) do update set position = excluded.position, q = excluded.q, a = excluded.a, verse_ids = excluded.verse_ids, reading_ids = excluded.reading_ids;
insert into faqs (id, position, q, a, verse_ids, reading_ids) values ('meaning', 2, '{"en":"What is the meaning of my life?","ta":"என் வாழ்க்கையின் அர்த்தம் என்ன?"}'::jsonb, '{"en":"You were made by God and for God. Money, study, career and family are good, but none of them can fill the deepest part of you — your spirit — because it was made to hold God Himself. Life finds its meaning when God comes into you as your life.","ta":"நீங்கள் தேவனால், தேவனுக்காகவே உண்டாக்கப்பட்டீர்கள். பணம், படிப்பு, வேலை, குடும்பம் இவை நல்லவை; ஆனால் இவற்றில் எதுவும் உங்கள் உள்ளத்தின் ஆழமான பகுதியாகிய ஆவியை நிரப்ப முடியாது, ஏனெனில் அது தேவனையே கொள்ளும்படி உண்டாக்கப்பட்டது. தேவன் உங்களுக்குள் ஜீவனாக வரும்போது வாழ்க்கை அதன் அர்த்தத்தைக் கண்டடைகிறது."}'::jsonb, array['GEN.1.26','ZEC.12.1','JHN.4.24']::text[], array['mystery','economy']::text[])
  on conflict (id) do update set position = excluded.position, q = excluded.q, a = excluded.a, verse_ids = excluded.verse_ids, reading_ids = excluded.reading_ids;
insert into faqs (id, position, q, a, verse_ids, reading_ids) values ('suffering', 3, '{"en":"If God is good, why is there so much suffering?","ta":"தேவன் நல்லவரானால், ஏன் இவ்வளவு துன்பம்?"}'::jsonb, '{"en":"Suffering came into the world through sin, not from God''s heart. God did not stay distant from our pain: in Christ He entered it and suffered on the cross. For those who love Him He works all things together for good, and He promises a day with no more death, sorrow or pain.","ta":"துன்பம் பாவத்தின் மூலமாக உலகத்தில் வந்தது; தேவனுடைய இருதயத்திலிருந்து அல்ல. தேவன் நம்முடைய வேதனைக்குத் தூரமாக நிற்கவில்லை; கிறிஸ்துவில் அவர் அதற்குள் வந்து சிலுவையில் பாடுபட்டார். அவரில் அன்புகூருகிறவர்களுக்குச் சகலமும் நன்மைக்கு ஏதுவாக நடக்கும்படி செய்கிறார்; மரணமும் துக்கமும் வருத்தமும் இல்லாத ஒரு நாளையும் வாக்குப்பண்ணியிருக்கிறார்."}'::jsonb, array['ROM.8.28','REV.21.4']::text[], array['gospel-of-god']::text[])
  on conflict (id) do update set position = excluded.position, q = excluded.q, a = excluded.a, verse_ids = excluded.verse_ids, reading_ids = excluded.reading_ids;
insert into faqs (id, position, q, a, verse_ids, reading_ids) values ('good-person', 4, '{"en":"I am a good person. Why do I need to be saved?","ta":"நான் நல்லவன்தான். எனக்கு ஏன் இரட்சிப்பு தேவை?"}'::jsonb, '{"en":"Compared with others we may look good, but God''s standard is His own glory. Our conscience tells us we have fallen short in thought, word and deed. The problem is not only the sins we do but the sinful nature within us. Good behaviour today cannot cancel yesterday''s debt — and good works cannot pay for sin.","ta":"மற்றவர்களோடு ஒப்பிடும்போது நாம் நல்லவர்களாகத் தோன்றலாம்; ஆனால் தேவனுடைய அளவுகோல் அவருடைய மகிமையே. எண்ணங்களிலும் வார்த்தைகளிலும் செயல்களிலும் நாம் குறைவுபட்டிருக்கிறோம் என்று நம் மனசாட்சியே சொல்லுகிறது. நாம் செய்யும் பாவங்கள் மட்டுமல்ல, நமக்குள் இருக்கும் பாவ சுபாவமும் பிரச்சனை. இன்றைய நல்ல நடத்தை நேற்றைய கடனை ரத்துசெய்யாது — நற்கிரியைகள் பாவத்திற்கு ஈடுசெய்ய முடியாது."}'::jsonb, array['ROM.3.23','ROM.6.23']::text[], array['gospel-of-god']::text[])
  on conflict (id) do update set position = excluded.position, q = excluded.q, a = excluded.a, verse_ids = excluded.verse_ids, reading_ids = excluded.reading_ids;
insert into faqs (id, position, q, a, verse_ids, reading_ids) values ('why-cross', 5, '{"en":"Why did Jesus have to die?","ta":"இயேசு ஏன் மரிக்க வேண்டியிருந்தது?"}'::jsonb, '{"en":"God is love, and He is also righteous. The wages of sin is death, so sin''s penalty had to be paid. Jesus, who had no sin, died in our place to pay it in full. Because God''s righteousness is satisfied, He can now forgive us justly and give us His life freely.","ta":"தேவன் அன்பாயிருக்கிறார்; அவர் நீதியுள்ளவருமாயிருக்கிறார். பாவத்தின் சம்பளம் மரணம்; ஆகையால் பாவத்தின் தண்டனை செலுத்தப்பட வேண்டியிருந்தது. பாவமில்லாத இயேசு அதை முழுமையாகச் செலுத்தும்படி நமக்குப் பதிலாக மரித்தார். தேவனுடைய நீதி திருப்தியானதால், இப்பொழுது அவர் நீதியாக நம்மை மன்னித்து, தம்முடைய ஜீவனை இலவசமாகக் கொடுக்க முடியும்."}'::jsonb, array['ROM.6.23','JHN.3.16']::text[], array['normal','gospel-of-god']::text[])
  on conflict (id) do update set position = excluded.position, q = excluded.q, a = excluded.a, verse_ids = excluded.verse_ids, reading_ids = excluded.reading_ids;
insert into faqs (id, position, q, a, verse_ids, reading_ids) values ('religions', 6, '{"en":"Aren''t all religions the same?","ta":"எல்லா மதங்களும் ஒன்றுதானே?"}'::jsonb, '{"en":"Most religions teach people to improve themselves and climb up to God. The gospel is the opposite: God came down to man. Christ does not only give a teaching; He gives Himself as life. That is why He could say, “I am the way, the truth, and the life.”","ta":"பெரும்பாலான மதங்கள் மனிதன் தன்னைத் திருத்திக்கொண்டு தேவனிடம் ஏறிச்செல்லப் போதிக்கின்றன. சுவிசேஷம் அதற்கு எதிரானது: தேவன் மனிதனிடம் இறங்கி வந்தார். கிறிஸ்து ஒரு போதனையை மட்டும் கொடுக்கவில்லை; தம்மையே ஜீவனாகக் கொடுக்கிறார். ஆகையால்தான் “நானே வழியும் சத்தியமும் ஜீவனுமாயிருக்கிறேன்” என்று அவர் சொல்ல முடிந்தது."}'::jsonb, array['JHN.14.6']::text[], array['mystery']::text[])
  on conflict (id) do update set position = excluded.position, q = excluded.q, a = excluded.a, verse_ids = excluded.verse_ids, reading_ids = excluded.reading_ids;
insert into faqs (id, position, q, a, verse_ids, reading_ids) values ('how-saved', 7, '{"en":"What must I do to be saved?","ta":"இரட்சிக்கப்பட நான் என்ன செய்ய வேண்டும்?"}'::jsonb, '{"en":"Nothing to earn it — only receive it. Repent, turning your heart to God; believe that Jesus died for your sins and rose again; and call on His name from your spirit. Everyone who receives Him is given the right to become a child of God.","ta":"அதைச் சம்பாதிக்க ஒன்றும் செய்ய வேண்டியதில்லை; ஏற்றுக்கொண்டால் போதும். மனந்திரும்பி உங்கள் இருதயத்தை தேவனிடம் திருப்புங்கள்; இயேசு உங்கள் பாவங்களுக்காக மரித்து உயிர்த்தெழுந்தார் என்று விசுவாசியுங்கள்; உங்கள் ஆவியிலிருந்து அவருடைய நாமத்தைத் தொழுதுகொள்ளுங்கள். அவரை ஏற்றுக்கொள்ளுகிற ஒவ்வொருவருக்கும் தேவனுடைய பிள்ளைகளாகும்படி அதிகாரம் கொடுக்கப்படுகிறது."}'::jsonb, array['ROM.10.13','JHN.1.12','EPH.2.8']::text[], array['gospel-of-god']::text[])
  on conflict (id) do update set position = excluded.position, q = excluded.q, a = excluded.a, verse_ids = excluded.verse_ids, reading_ids = excluded.reading_ids;
insert into faqs (id, position, q, a, verse_ids, reading_ids) values ('too-sinful', 8, '{"en":"What if I have sinned too much to be forgiven?","ta":"என் பாவங்கள் மன்னிக்க முடியாத அளவுக்கு அதிகமானால்?"}'::jsonb, '{"en":"No sin is greater than the blood of Jesus. The Lord invites all who are weary and heavy laden to come to Him. If we confess our sins, He is faithful and righteous to forgive us and cleanse us — not because we deserve it, but because of what He has done.","ta":"இயேசுவின் இரத்தத்தைவிடப் பெரிய பாவம் ஒன்றுமில்லை. வருத்தப்பட்டுப் பாரஞ்சுமக்கிற யாவரையும் கர்த்தர் தம்மிடம் வரும்படி அழைக்கிறார். நம்முடைய பாவங்களை நாம் அறிக்கையிட்டால், அவர் நம்மை மன்னித்துச் சுத்திகரிக்க உண்மையும் நீதியும் உள்ளவராயிருக்கிறார் — நாம் தகுதியானவர்கள் என்பதால் அல்ல, அவர் செய்து முடித்ததினால்."}'::jsonb, array['MAT.11.28','1JN.1.9']::text[], array['normal']::text[])
  on conflict (id) do update set position = excluded.position, q = excluded.q, a = excluded.a, verse_ids = excluded.verse_ids, reading_ids = excluded.reading_ids;
insert into faqs (id, position, q, a, verse_ids, reading_ids) values ('family', 9, '{"en":"My family follows another faith. Can I still believe?","ta":"என் குடும்பத்தினர் வேறொரு மார்க்கத்தைப் பின்பற்றுகிறார்கள். நான் விசுவாசிக்கலாமா?"}'::jsonb, '{"en":"Yes. Believing in Christ is a personal matter between you and God, and it does not mean rejecting or dishonouring your family. Keep loving and respecting them. God''s heart is for whole households, and your changed life may be the way they meet Him too.","ta":"ஆம். கிறிஸ்துவை விசுவாசிப்பது உங்களுக்கும் தேவனுக்கும் இடையிலான தனிப்பட்ட காரியம்; அது உங்கள் குடும்பத்தைப் புறக்கணிப்பதோ அவமதிப்பதோ அல்ல. அவர்களைத் தொடர்ந்து நேசித்து மதியுங்கள். தேவனுடைய இருதயம் முழு குடும்பங்களுக்காகவும் இருக்கிறது; உங்கள் மாறின வாழ்க்கை அவர்களும் அவரைச் சந்திக்கும் வழியாகலாம்."}'::jsonb, array['ACT.16.31']::text[], array['new-believers']::text[])
  on conflict (id) do update set position = excluded.position, q = excluded.q, a = excluded.a, verse_ids = excluded.verse_ids, reading_ids = excluded.reading_ids;
insert into faqs (id, position, q, a, verse_ids, reading_ids) values ('assurance', 10, '{"en":"How can I know I am saved?","ta":"நான் இரட்சிக்கப்பட்டேன் என்று எப்படி அறிவேன்?"}'::jsonb, '{"en":"Not by feelings, which change, but by God''s word, which does not. He says that whoever calls on His name shall be saved, and that to all who receive Him He gives the right to become God''s children. Inwardly, His Spirit also bears witness with your spirit (Romans 8:16).","ta":"மாறும் உணர்ச்சிகளால் அல்ல; மாறாத தேவனுடைய வார்த்தையினாலே. தம்முடைய நாமத்தைத் தொழுதுகொள்ளுகிற எவனும் இரட்சிக்கப்படுவான் என்றும், தம்மை ஏற்றுக்கொள்ளுகிற யாவருக்கும் தேவனுடைய பிள்ளைகளாகும் அதிகாரம் கொடுக்கிறார் என்றும் அவர் சொல்லுகிறார். உள்ளே, அவருடைய ஆவியும் உங்கள் ஆவியோடேகூடச் சாட்சிகொடுக்கிறார் (ரோமர் 8:16)."}'::jsonb, array['ROM.10.13','JHN.1.12']::text[], array['new-believers']::text[])
  on conflict (id) do update set position = excluded.position, q = excluded.q, a = excluded.a, verse_ids = excluded.verse_ids, reading_ids = excluded.reading_ids;

commit;

notify pgrst, 'reload schema';
